/// A built-in Word paragraph style jade can add to a package that lacks it.
struct BuiltinParagraphStyle {
    id: String,
    /// Word's language-independent built-in name, used for lookup because
    /// localized packages store opaque ids (`1`, `a`, ...).
    name: String,
    outline_level: Option<u8>,
    half_points: Option<u32>,
    centered: bool,
}

impl BuiltinParagraphStyle {
    /// Accepts the canonical id (`Heading1`, `Title`) or built-in name
    /// (`heading 1`, `title`), case-insensitively.
    fn parse(requested: &str) -> Option<Self> {
        let compact: String = requested
            .chars()
            .filter(|ch| !ch.is_whitespace())
            .collect::<String>()
            .to_ascii_lowercase();
        if compact == "title" {
            return Some(Self {
                id: "Title".to_string(),
                name: "Title".to_string(),
                outline_level: None,
                half_points: Some(32),
                centered: true,
            });
        }
        let level: u8 = compact.strip_prefix("heading")?.parse().ok()?;
        if !(1..=9).contains(&level) {
            return None;
        }
        Some(Self {
            id: format!("Heading{level}"),
            name: format!("heading {level}"),
            outline_level: Some(level - 1),
            half_points: match level {
                1 => Some(32),
                2 => Some(28),
                3 => Some(24),
                _ => None,
            },
            centered: false,
        })
    }
}

/// `w:rPr` children taken out of a paragraph's runs, by `w:rPr` element and
