pub(crate) struct RemovedRunProperties(Vec<(XmlNodeId, Vec<(usize, XmlNode)>)>);

/// The child tags of the `properties` element (`w:rPr`, `w:pPr`) of the
/// `element` (`w:r`, `w:p`) at `node_id`.
fn declared_property_tags<'a>(
    raw: Option<&'a DocxXmlDocument>,
    node_id: Option<XmlNodeId>,
    element: &str,
    properties: &str,
) -> Vec<&'a str> {
    node_id
        .and_then(|id| raw.and_then(|raw| raw.element(id)))
        .filter(|node| node.name == element)
        .and_then(|node| {
            node.children.iter().find_map(|child| match child {
                XmlNode::Element(child) if child.name == properties => Some(child),
                _ => None,
            })
        })
        .map(|properties| {
            properties
                .children
                .iter()
                .filter_map(|child| match child {
                    XmlNode::Element(element) => Some(element.name.as_str()),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default()
}

/// Replaces the paragraph properties `old` resolves to with what `new`
/// resolves to, for every property the paragraph does not declare itself:
/// `declared` says whether its `w:pPr` has the tag, and a value other than
/// `old`'s came from somewhere else.
pub(crate) fn rebase_paragraph_style_properties(
    props: &mut ParagraphProperties,
    old: &ParagraphProperties,
    new: &ParagraphProperties,
    declared: impl Fn(&str) -> bool,
) {
    macro_rules! rebase {
        ($($field:ident => $tag:literal),* $(,)?) => {
            $(
                if !declared($tag) && props.$field == old.$field {
                    props.$field = new.$field.clone();
                }
            )*
        };
    }
    rebase!(
        alignment => "w:jc",
        bidi => "w:bidi",
        spacing => "w:spacing",
        indent => "w:ind",
        tabs => "w:tabs",
        adjust_right_indent => "w:adjustRightInd",
        snap_to_grid => "w:snapToGrid",
        widow_control => "w:widowControl",
        suppress_auto_hyphens => "w:suppressAutoHyphens",
        page_break_before => "w:pageBreakBefore",
        suppress_line_numbers => "w:suppressLineNumbers",
        keep_lines => "w:keepLines",
        keep_next => "w:keepNext",
        text_alignment => "w:textAlignment",
        mirror_indents => "w:mirrorIndents",
        outline_level => "w:outlineLvl",
        shading => "w:shd",
        borders => "w:pBdr",
        contextual_spacing => "w:contextualSpacing",
    );
}

/// Puts back the paragraph properties the paragraph declares in its own
/// `w:pPr` (`declared`), from `before`, after a style was merged over them:
/// applying a paragraph style keeps direct paragraph formatting, as in Word,
/// and the saved `w:pPr` keeps it too.
///
/// `w:spacing` and `w:ind` are inherited attribute by attribute: a paragraph
/// declaring only `w:before` still takes its space after from the style, as a
/// reload reads it. Only the attributes it declares (`declared_attribute`)
/// come back from `before`; putting the whole element back dropped the
/// style's other spacing, and the paragraph sat higher than after a reload.
pub(crate) fn keep_declared_paragraph_properties(
    props: &mut ParagraphProperties,
    before: &ParagraphProperties,
    declared: impl Fn(&str) -> bool,
    declared_attribute: impl Fn(&str, &str) -> bool,
) {
    macro_rules! keep {
        ($($field:ident => $tag:literal),* $(,)?) => {
            $(
                if declared($tag) {
                    props.$field = before.$field.clone();
                }
            )*
        };
    }
    keep!(
        alignment => "w:jc",
        bidi => "w:bidi",
        tabs => "w:tabs",
        adjust_right_indent => "w:adjustRightInd",
        snap_to_grid => "w:snapToGrid",
        widow_control => "w:widowControl",
        suppress_auto_hyphens => "w:suppressAutoHyphens",
        page_break_before => "w:pageBreakBefore",
        suppress_line_numbers => "w:suppressLineNumbers",
        keep_lines => "w:keepLines",
        keep_next => "w:keepNext",
        text_alignment => "w:textAlignment",
        mirror_indents => "w:mirrorIndents",
        outline_level => "w:outlineLvl",
        shading => "w:shd",
        borders => "w:pBdr",
        numbering => "w:numPr",
        contextual_spacing => "w:contextualSpacing",
    );
    macro_rules! keep_attributes {
        ($target:expr, $source:expr, $tag:literal, $($field:ident => [$($attribute:literal),+]),* $(,)?) => {
            $(
                if $(declared_attribute($tag, $attribute))||+ {
                    $target.$field = $source.$field.clone();
                }
            )*
        };
    }
    if declared("w:spacing") {
        let mut spacing = props.spacing.clone().unwrap_or_default();
        let direct = before.spacing.clone().unwrap_or_default();
        keep_attributes!(spacing, direct, "w:spacing",
            before => ["w:before"],
            after => ["w:after"],
            before_lines => ["w:beforeLines"],
            after_lines => ["w:afterLines"],
            line => ["w:line"],
            // The reader gives a `w:line` without a rule the rule "auto".
            line_rule => ["w:line", "w:lineRule"],
        );
        props.spacing = (spacing != Spacing::default()).then_some(spacing);
    }
    if declared("w:ind") {
        let mut indent = props.indent.clone().unwrap_or_default();
        let direct = before.indent.clone().unwrap_or_default();
        keep_attributes!(indent, direct, "w:ind",
            left => ["w:left"],
            right => ["w:right"],
            start => ["w:start"],
            end => ["w:end"],
            first_line => ["w:firstLine"],
            hanging => ["w:hanging"],
            left_chars => ["w:leftChars"],
            right_chars => ["w:rightChars"],
            start_chars => ["w:startChars"],
            end_chars => ["w:endChars"],
            first_line_chars => ["w:firstLineChars"],
            hanging_chars => ["w:hangingChars"],
        );
        props.indent = (indent != Indent::default()).then_some(indent);
    }
}

/// Replaces the run properties `old` resolves to with what `new` resolves to,
/// for every property the run does not declare itself: `declared` says
/// whether its `w:rPr` has the tag, and a value other than `old`'s came from
/// somewhere else. Font properties go by their direct provenance when known.
fn rebase_run_style_properties(
    run: &mut RunProperties,
    old: &RunProperties,
    new: &RunProperties,
    declared: impl Fn(&str) -> bool,
) {
    // The font properties a load resolves into runs (see
    // `apply_run_font_defaults_to_paragraph`) move to the new style's.
    macro_rules! rebase {
        ($($field:ident => $direct:expr),* $(,)?) => {
            $(
                if !$direct && run.$field == old.$field {
                    run.$field = new.$field.clone();
                }
            )*
        };
    }
    // The rest a load leaves to the paragraph style, which the renderer
    // resolves: a value the old style gave goes, rather than turning into the
    // new style's. Kept, the sync wrote it into the run's `w:rPr` at its next
    // edit, and a heading's theme colour became a fixed direct one.
    macro_rules! release {
        ($($field:ident => $direct:expr),* $(,)?) => {
            $(
                if !$direct && run.$field == old.$field {
                    run.$field = None;
                }
            )*
        };
    }
    let direct = run.direct_font_properties.clone();
    let font_direct = |provenance: bool, tag: &str| {
        if direct.known {
            provenance
        } else {
            declared(tag)
        }
    };
    release!(
        bold => declared("w:b"),
        bold_complex => declared("w:bCs"),
        italic => declared("w:i"),
        italic_complex => declared("w:iCs"),
        strike => declared("w:strike"),
        double_strike => declared("w:dstrike"),
        caps => declared("w:caps"),
        small_caps => declared("w:smallCaps"),
        vanish => declared("w:vanish"),
        spec_vanish => declared("w:specVanish"),
        shadow => declared("w:shadow"),
        outline => declared("w:outline"),
        emboss => declared("w:emboss"),
        imprint => declared("w:imprint"),
        emphasis => declared("w:em"),
        effect => declared("w:effect"),
        baseline => declared("w:vertAlign"),
        text_position => declared("w:position"),
        char_spacing => declared("w:spacing"),
        fit_text => declared("w:fitText"),
        color => declared("w:color"),
        theme_color => declared("w:color"),
        highlight => declared("w:highlight"),
        shading => declared("w:shd"),
        border => declared("w:bdr"),
        east_asian_layout => declared("w:eastAsianLayout"),
    );
    rebase!(
        font_family => declared("w:rFonts"),
        language => declared("w:lang"),
        east_asia_language => declared("w:lang"),
        font_size => font_direct(direct.font_size.is_some(), "w:sz"),
        font_size_complex => font_direct(direct.font_size_complex.is_some(), "w:szCs"),
        kerning => font_direct(direct.kerning.is_some(), "w:kern"),
        text_scale => font_direct(direct.text_scale.is_some(), "w:w"),
        fonts => font_direct(direct.fonts.is_some(), "w:rFonts"),
    );
    // Underline's kind and color travel with the `w:u` that set it.
    if !declared("w:u")
        && (&run.underline, &run.underline_kind, &run.underline_color)
            == (&old.underline, &old.underline_kind, &old.underline_color)
    {
        run.underline = None;
        run.underline_kind = None;
        run.underline_color = None;
    }
}

/// Clears the font properties a run is known to inherit, so the paragraph's
/// new style fills them in again as a load does. Matching them against the
/// old style's to tell inherited from direct fails where a load filled the
/// fonts slot by slot from more than one source (a style's East Asian font
/// and the document default's ASCII one): such a run kept the old style's
/// fonts on screen only. Runs whose direct fonts are not known keep the
/// comparison.
fn release_inherited_fonts(run: &mut RunProperties, declared: impl Fn(&str) -> bool) {
    let direct = run.direct_font_properties.clone();
    if !direct.known {
        return;
    }
    // A `w:rFonts` carrying only `w:hint` names no font: what the run names
    // itself is the test, not the tag. Its hint stays, and the fonts are
    // filled in around it.
    let names_a_font = |fonts: &RunFonts| {
        fonts.ascii.is_some()
            || fonts.h_ansi.is_some()
            || fonts.east_asia.is_some()
            || fonts.complex.is_some()
            || fonts.ascii_theme.is_some()
            || fonts.h_ansi_theme.is_some()
            || fonts.east_asia_theme.is_some()
            || fonts.complex_theme.is_some()
    };
    if !direct.fonts.as_ref().is_some_and(names_a_font) {
        run.fonts = direct.fonts.as_ref().map(|fonts| RunFonts {
            hint: fonts.hint.clone(),
            ..RunFonts::default()
        });
        run.font_family = None;
    }
    if direct.font_size.is_none() {
        run.font_size = None;
    }
    if direct.font_size_complex.is_none() {
        run.font_size_complex = None;
    }
    if direct.kerning.is_none() {
        run.kerning = None;
    }
    if direct.text_scale.is_none() {
        run.text_scale = None;
    }
    if !declared("w:lang") {
        run.language = None;
        run.east_asia_language = None;
    }
}

