/// One border edge as a caller describes it: the line style Word draws, its
/// thickness in points, and its colour.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BorderEdgeSpec {
    pub style: Option<String>,
    pub width: Option<f32>,
    pub color: Option<String>,
}

impl BorderEdgeSpec {
    fn to_border_edge(&self) -> BorderEdge {
        BorderEdge {
            val: Some(
                self.style
                    .clone()
                    .unwrap_or_else(|| "single".to_string())
                    .to_ascii_lowercase(),
            ),
            size_eighths: self.width.map(|pt| (pt * 8.0).round().max(0.0) as u32),
            space: None,
            color: self.color.as_deref().and_then(|color| {
                (!color.eq_ignore_ascii_case("auto"))
                    .then(|| format!("#{}", color.trim_start_matches('#').to_ascii_uppercase()))
            }),
        }
    }
}

/// Which edge a [`BorderEdgeSpec`] applies to.
