/// A border change. Every edge is optional: the ones left out keep whatever
/// they had, so switching off the inside lines does not disturb the frame.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct TableBorderSpec {
    pub top: Option<BorderEdgeSpec>,
    pub bottom: Option<BorderEdgeSpec>,
    pub left: Option<BorderEdgeSpec>,
    pub right: Option<BorderEdgeSpec>,
    pub inside_h: Option<BorderEdgeSpec>,
    pub inside_v: Option<BorderEdgeSpec>,
}

fn table_style_preset_fill(preset: &str, row: usize) -> Result<&'static str, String> {
    match preset {
        "plain" | "grid" => Ok("FFFFFF"),
        "lightBlue" => Ok(if row == 0 { "D9EAF7" } else { "FFFFFF" }),
        "blueBands" => Ok(if row == 0 {
            "BDD7EE"
        } else if row.is_multiple_of(2) {
            "DDEBF7"
        } else {
            "FFFFFF"
        }),
        "grayBands" => Ok(if row == 0 {
            "D9E1F2"
        } else if row.is_multiple_of(2) {
            "E7E6E6"
        } else {
            "FFFFFF"
        }),
        other => Err(format!(
            "table style preset must be plain, grid, lightBlue, blueBands or grayBands, not {other:?}"
        )),
    }
}

fn table_style_preset_border(preset: &str) -> Result<BorderEdgeSpec, String> {
    let (style, color) = match preset {
        "plain" => ("none", "auto"),
        "grid" => ("single", "B7B7B7"),
        "lightBlue" => ("single", "5B9BD5"),
        "blueBands" => ("single", "9EADBD"),
        "grayBands" => ("single", "A6A6A6"),
        other => {
            return Err(format!(
                "table style preset must be plain, grid, lightBlue, blueBands or grayBands, not {other:?}"
            ));
        }
    };
    Ok(BorderEdgeSpec {
        style: Some(style.to_string()),
        width: Some(0.5),
        color: Some(color.to_string()),
    })
}

impl TableBorderSpec {
    /// Word's line styles. `none` is the way to remove a line; the rest are the
    /// tokens `w:val` takes.
    const STYLES: &'static [&'static str] = &[
        "none",
        "nil",
        "single",
        "double",
        "dashed",
        "dotted",
        "thick",
        "wave",
        "dashSmallGap",
        "dotDash",
        "dotDotDash",
        "triple",
    ];

    fn validated_edges(&self) -> Result<Vec<(BorderSide, BorderEdgeSpec)>, String> {
        let edges = [
            (BorderSide::Top, self.top.as_ref()),
            (BorderSide::Bottom, self.bottom.as_ref()),
            (BorderSide::Left, self.left.as_ref()),
            (BorderSide::Right, self.right.as_ref()),
            (BorderSide::InsideH, self.inside_h.as_ref()),
            (BorderSide::InsideV, self.inside_v.as_ref()),
        ];
        let mut validated = Vec::new();
        for (side, edge) in edges {
            let Some(edge) = edge else { continue };
            if let Some(style) = edge.style.as_deref() {
                if !Self::STYLES
                    .iter()
                    .any(|known| known.eq_ignore_ascii_case(style))
                {
                    return Err(format!(
                        "border style {style:?} is not one of {}",
                        Self::STYLES.join(", ")
                    ));
                }
            }
            if let Some(width) = edge.width {
                if !width.is_finite() || width < 0.0 {
                    return Err("border width must be a finite non-negative number".to_string());
                }
            }
            if let Some(color) = edge.color.as_deref() {
                if !color.eq_ignore_ascii_case("auto") {
                    WordDocument::normalize_hex_color(color)?;
                }
            }
            validated.push((side, edge.clone()));
        }
        if validated.is_empty() {
            return Err("at least one border edge must be given".to_string());
        }
        Ok(validated)
    }
}

/// A page-margin change. Every field is optional: `None` leaves that edge as it
