/// table borders, omitted sides are removed rather than preserved, which makes
/// export deterministic and lets embedders represent asymmetric frames.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PageBorderSpec {
    pub top: Option<BorderEdgeSpec>,
    pub bottom: Option<BorderEdgeSpec>,
    pub left: Option<BorderEdgeSpec>,
    pub right: Option<BorderEdgeSpec>,
    /// `page` anchors the frame to the paper edge; `text` anchors it to the
    /// body box. Absent uses Word's `text` default.
    pub offset_from: Option<String>,
}

/// The document-wide font and color theme exposed by Word's Design ribbon.
///
/// The modeled fields intentionally match GenOffice's non-AI theme surface.
/// Unmodeled DrawingML theme children (effects, fills, line styles, script
/// font overrides, and extensions) are preserved when an imported theme is
/// edited.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct DocumentThemeSpec {
    pub name: String,
    pub major_font: String,
    pub minor_font: String,
    pub east_asia_font: String,
    pub dark2: String,
    pub light2: String,
    pub accent1: String,
    pub accent2: String,
    pub accent3: String,
    pub accent4: String,
    pub accent5: String,
    pub accent6: String,
}

impl Default for DocumentThemeSpec {
    fn default() -> Self {
        Self {
            name: "Office".to_string(),
            major_font: "Calibri Light".to_string(),
            minor_font: "Calibri".to_string(),
            east_asia_font: "等线".to_string(),
            dark2: "44546A".to_string(),
            light2: "E7E6E6".to_string(),
            accent1: "4472C4".to_string(),
            accent2: "ED7D31".to_string(),
            accent3: "A5A5A5".to_string(),
            accent4: "FFC000".to_string(),
            accent5: "5B9BD5".to_string(),
            accent6: "70AD47".to_string(),
        }
    }
}

impl PageBorderSpec {
    fn normalized(&self) -> Result<PageBorders, String> {
        let offset_from = match self.offset_from.as_deref() {
            None => None,
            Some(value) if value.eq_ignore_ascii_case("text") => Some("text".to_string()),
            Some(value) if value.eq_ignore_ascii_case("page") => Some("page".to_string()),
            Some(value) => {
                return Err(format!(
                    "page border offset_from must be page or text, not {value:?}"
                ));
            }
        };
        let validation = TableBorderSpec {
            top: self.top.clone(),
            bottom: self.bottom.clone(),
            left: self.left.clone(),
            right: self.right.clone(),
            ..TableBorderSpec::default()
        };
        let edges = validation.validated_edges()?;
        let mut borders = PageBorders {
            offset_from,
            ..PageBorders::default()
        };
        let mut visible = false;
        for (side, spec) in edges {
            if let Some(width) = spec.width {
                if !(0.25..=12.0).contains(&width) {
                    return Err("page border width must be between 0.25 and 12 points".to_string());
                }
            }
            let edge = spec.to_border_edge();
            visible |= edge.is_visible();
            match side {
                BorderSide::Top => borders.top = Some(edge),
                BorderSide::Bottom => borders.bottom = Some(edge),
                BorderSide::Left => borders.left = Some(edge),
                BorderSide::Right => borders.right = Some(edge),
                BorderSide::InsideH | BorderSide::InsideV => unreachable!("page edges are outer"),
            }
        }
        if !visible {
            return Err("at least one visible page border edge must be given".to_string());
        }
        Ok(borders)
    }
}

