/// High-level representation of a DOCX package. It combines the parsed XML
/// structures (`Document`, `NumberingPart`, etc.) with the underlying
/// relationships so that renderers can access additional parts on demand.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct DocumentTextMetrics {
    pub words: usize,
    pub asian_chars: usize,
    pub non_asian_words: usize,
    pub chars_no_space: usize,
    pub chars_with_space: usize,
    pub paragraphs: usize,
}

impl DocumentTextMetrics {
    fn add_assign(&mut self, other: Self) {
        self.asian_chars += other.asian_chars;
        self.non_asian_words += other.non_asian_words;
        self.chars_no_space += other.chars_no_space;
        self.chars_with_space += other.chars_with_space;
        self.paragraphs += other.paragraphs;
        self.words = self.asian_chars + self.non_asian_words;
    }

    fn replace(&mut self, old: Self, new: Self) {
        self.asian_chars = self
            .asian_chars
            .saturating_sub(old.asian_chars)
            .saturating_add(new.asian_chars);
        self.non_asian_words = self
            .non_asian_words
            .saturating_sub(old.non_asian_words)
            .saturating_add(new.non_asian_words);
        self.chars_no_space = self
            .chars_no_space
            .saturating_sub(old.chars_no_space)
            .saturating_add(new.chars_no_space);
        self.chars_with_space = self
            .chars_with_space
            .saturating_sub(old.chars_with_space)
            .saturating_add(new.chars_with_space);
        self.paragraphs = self
            .paragraphs
            .saturating_sub(old.paragraphs)
            .saturating_add(new.paragraphs);
        self.words = self.asian_chars + self.non_asian_words;
    }
}

#[derive(Clone, Debug, Default)]
struct DocumentTextMetricsCache {
    initialized: bool,
    paragraphs: Vec<DocumentTextMetrics>,
    dirty_body_indices: HashSet<usize>,
    total: DocumentTextMetrics,
}

impl DocumentTextMetricsCache {
    fn invalidate_all(&mut self) {
        self.initialized = false;
        self.paragraphs.clear();
        self.dirty_body_indices.clear();
        self.total = DocumentTextMetrics::default();
    }
}

fn is_javascript_whitespace(ch: char) -> bool {
    matches!(
        ch,
        '\u{0009}'..='\u{000D}'
            | '\u{0020}'
            | '\u{00A0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200A}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202F}'
            | '\u{205F}'
            | '\u{3000}'
            | '\u{FEFF}'
    )
}

fn is_asian_word_count_character(ch: char) -> bool {
    matches!(
        ch,
        '\u{1100}'..='\u{11FF}'
            | '\u{2E80}'..='\u{2FDF}'
            | '\u{3001}'..='\u{303F}'
            | '\u{3040}'..='\u{30FF}'
            | '\u{3100}'..='\u{312F}'
            | '\u{3130}'..='\u{318F}'
            | '\u{31C0}'..='\u{31EF}'
            | '\u{3400}'..='\u{4DBF}'
            | '\u{4E00}'..='\u{9FFF}'
            | '\u{AC00}'..='\u{D7AF}'
            | '\u{F900}'..='\u{FAFF}'
            | '\u{FF01}'..='\u{FF60}'
            | '\u{FFE0}'..='\u{FFE6}'
            | '\u{20000}'..='\u{2FFFF}'
    )
}

fn is_non_asian_word_character(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || matches!(ch, '\u{00C0}'..='\u{024F}')
}

fn paragraph_text_metrics(paragraph: &Paragraph) -> DocumentTextMetrics {
    #[derive(Clone, Copy)]
    enum WordState {
        Outside,
        Inside,
        Connector,
    }

    let text = paragraph
        .runs
        .iter()
        .map(|run| run.text.as_str())
        .collect::<String>();
    let mut metrics = DocumentTextMetrics::default();
    let mut word_state = WordState::Outside;
    let mut has_non_whitespace = false;

    for ch in text.chars() {
        let utf16_len = ch.len_utf16();
        // The worker's previous `parts.join('\n').replace(/\n/g, '')`
        // removes both paragraph separators and line feeds already present in
        // a run while retaining every other whitespace character.
        if ch != '\n' {
            metrics.chars_with_space += utf16_len;
        }
        if !is_javascript_whitespace(ch) {
            metrics.chars_no_space += utf16_len;
            has_non_whitespace = true;
        }
        if is_asian_word_count_character(ch) {
            metrics.asian_chars += 1;
        }

        if is_non_asian_word_character(ch) {
            if matches!(word_state, WordState::Outside) {
                metrics.non_asian_words += 1;
            }
            word_state = WordState::Inside;
        } else if matches!(ch, '\'' | '-') && matches!(word_state, WordState::Inside) {
            word_state = WordState::Connector;
        } else {
            word_state = WordState::Outside;
        }
    }

    metrics.paragraphs = usize::from(has_non_whitespace);
    metrics.words = metrics.asian_chars + metrics.non_asian_words;
    metrics
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WordDocument {
    #[serde(skip)]
    package: Option<OpenXmlPackage>,
    /// Newly authored binary OPC parts. Keeping these separate from the
    /// immutable source package makes package-level undo cheap for documents
    /// that contain large pre-existing media while still allowing new images
    /// to be added and removed atomically.
    #[serde(skip)]
    binary_parts: HashMap<String, Vec<u8>>,
    /// Source OPC parts deliberately removed by an edit. The source package is
    /// immutable, so exports need explicit tombstones to avoid resurrecting
    /// deleted media.
    #[serde(skip)]
    removed_parts: HashSet<String>,
    #[serde(skip)]
    pub raw_document: Option<DocxXmlDocument>,
    #[serde(skip)]
    paragraph_surfaces: Vec<ParagraphSurface>,
    /// Text counts shown in the status bar. Ordinary typing invalidates one
    /// body paragraph; structural edits rebuild the cache with the surfaces.
    #[serde(skip)]
    text_metrics_cache: RefCell<DocumentTextMetricsCache>,
    #[serde(skip)]
    revision_session: Option<RevisionSession>,
    /// 保護の中止 with the password: the restriction does not hold until
    /// the document is opened again.
    #[serde(skip)]
    protection_lifted: bool,
    /// Opened 読み取り専用: see `set_opened_read_only`.
    #[serde(skip)]
    opened_read_only: bool,
    #[serde(skip)]
    next_revision_id: u32,
    pub relationships: Vec<Relationship>,
    pub parts: HashMap<String, DocumentPart>,
    pub document_part: Option<DocumentPart>,
    /// The parsed document structure wrapped in `Rc` for efficient sharing.
    /// This avoids expensive cloning when passing to the renderer.
    #[serde(skip)]
    pub document: Option<Rc<Document>>,
    pub numbering_part: Option<NumberingPart>,
    pub styles_part: Option<StylesPart>,
    /// Parsed `word/fontTable.xml`: per-document `w:altName` substitutes the
    /// editor installs into the font resolver at its load boundary (the
    /// document core itself stays layout-free).
    #[serde(skip)]
    pub font_table_part: Option<jade_docx_reader::FontTablePart>,
    pub header_lines: Option<Vec<HeaderLine>>,
    pub footer_lines: Option<Vec<HeaderLine>>,
    /// Header/footer used on the first page when the section sets `w:titlePg`.
    #[serde(default)]
    pub header_lines_first: Option<Vec<HeaderLine>>,
    #[serde(default)]
    pub footer_lines_first: Option<Vec<HeaderLine>>,
    /// Header/footer used on even-numbered pages when the document settings
    /// enable `w:evenAndOddHeaders`.
    #[serde(default)]
    pub header_lines_even: Option<Vec<HeaderLine>>,
    #[serde(default)]
    pub footer_lines_even: Option<Vec<HeaderLine>>,
    /// Whether the document's default section sets `w:titlePg`.
    #[serde(default)]
    pub title_page: bool,
    /// Whether the document's settings.xml enables
    /// `w:evenAndOddHeaders`.
    #[serde(default)]
    pub even_and_odd_headers: bool,
    /// Section whose header/footer parts the current edit session targets
    /// (set while a page's header/footer is being edited). `None` resolves
    /// references document-wide, as before multi-section support.
    pub hf_edit_section: Option<usize>,
    pub comments: HashMap<String, DocumentComment>,
}

#[derive(Clone, Debug)]
pub struct WordDocumentSnapshot {
    source_package: Option<OpenXmlPackage>,
    pub document: Document,
    pub raw_document: Option<DocxXmlDocument>,
    pub next_revision_id: u32,
    /// Present only for snapshots taken with
    /// [`WordDocument::snapshot_including_package`]; see there for why it is
    /// opt-in.
    pub package_state: Option<PackageStateSnapshot>,
}

/// The parts of a [`WordDocument`] that live outside `word/document.xml` and
/// that comment / revision editing writes to.
#[derive(Clone, Debug)]
pub struct PackageStateSnapshot {
    pub comments: HashMap<String, DocumentComment>,
    pub parts: HashMap<String, DocumentPart>,
    pub relationships: Vec<Relationship>,
    pub document_part: Option<DocumentPart>,
    pub numbering_part: Option<NumberingPart>,
    /// Parsed styles model. Restoring the raw `styles.xml` part without this
    /// would leave style lookups (e.g. the note styles created on first
    /// footnote/endnote insertion) believing definitions still exist, so a
    /// redo would skip re-creating them and diverge from the first apply.
    pub styles_part: Option<StylesPart>,
    pub binary_parts: HashMap<String, Vec<u8>>,
    pub removed_parts: HashSet<String>,
    pub revision_session: Option<RevisionSession>,
    pub header_lines: Option<Vec<HeaderLine>>,
    pub footer_lines: Option<Vec<HeaderLine>>,
    pub header_lines_first: Option<Vec<HeaderLine>>,
    pub footer_lines_first: Option<Vec<HeaderLine>>,
    pub header_lines_even: Option<Vec<HeaderLine>>,
    pub footer_lines_even: Option<Vec<HeaderLine>>,
    pub title_page: bool,
    pub even_and_odd_headers: bool,
}

