impl CitationSourceInfo {
    /// Plain in-text representation used by GenOffice, for example
    /// `(Smith, 2024)`. Word still sees the catalog through `b:Sources`.
    pub fn citation_text(&self) -> String {
        let author = if self.author.is_empty() {
            self.title.as_str()
        } else {
            self.author.as_str()
        };
        if self.year.is_empty() {
            format!("({author})")
        } else {
            format!("({author}, {})", self.year)
        }
    }

    /// Simple APA-like bibliography line compatible with GenOffice.
    pub fn bibliography_line(&self) -> String {
        let mut parts = Vec::new();
        if !self.author.is_empty() {
            parts.push(format!("{}.", self.author));
        }
        if !self.year.is_empty() {
            parts.push(format!("({}).", self.year));
        }
        if !self.title.is_empty() {
            parts.push(format!("{}.", self.title));
        }
        if let Some(publisher) = self.publisher.as_deref().filter(|value| !value.is_empty()) {
            parts.push(format!("{publisher}."));
        }
        if let Some(url) = self.url.as_deref().filter(|value| !value.is_empty()) {
            parts.push(url.to_string());
        }
        parts.join(" ")
    }
}

