#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum InlineImageMime {
    Png,
    Jpeg,
    Gif,
}

impl InlineImageMime {
    fn parse(value: &str) -> Result<Self, String> {
        match value.trim().to_ascii_lowercase().as_str() {
            "image/png" => Ok(Self::Png),
            "image/jpeg" => Ok(Self::Jpeg),
            "image/gif" => Ok(Self::Gif),
            _ => Err("image MIME type must be image/png, image/jpeg, or image/gif".to_string()),
        }
    }

    fn content_type(self) -> &'static str {
        match self {
            Self::Png => "image/png",
            Self::Jpeg => "image/jpeg",
            Self::Gif => "image/gif",
        }
    }

    fn extension(self) -> &'static str {
        match self {
            Self::Png => "png",
            Self::Jpeg => "jpeg",
            Self::Gif => "gif",
        }
    }

    fn matches_signature(self, bytes: &[u8]) -> bool {
        match self {
            Self::Png => bytes.starts_with(b"\x89PNG\r\n\x1a\n"),
            Self::Jpeg => bytes.starts_with(&[0xff, 0xd8, 0xff]),
            Self::Gif => bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a"),
        }
    }
}

impl HeaderFooterAlignment {
    fn as_w_value(self) -> &'static str {
        match self {
            HeaderFooterAlignment::Left => "left",
            HeaderFooterAlignment::Center => "center",
            HeaderFooterAlignment::Right => "right",
        }
    }
}

impl HeaderFooterVariant {
    fn as_w_type(self) -> &'static str {
        match self {
            HeaderFooterVariant::Default => "default",
            HeaderFooterVariant::First => "first",
            HeaderFooterVariant::Even => "even",
        }
    }
}

/// Resolves the relationship id for a (role, variant) pair on a
/// [`crate::document::Document`]. Document-level `header_reference` /
/// `footer_reference` track the `default` variant; first/even variants live on
/// the default section. Returns `None` when the requested variant isn't wired
/// up in the source docx (caller must surface a user-facing error).
/// Header/footer stories of one section after Word's "link to previous"
/// inheritance: a section that declares no reference of a given type shows
/// the previous section's story. `title_page` is that section's own
/// `w:titlePg`, which applies to the first page of the section.
#[derive(Debug, Clone, Default)]
pub struct SectionHeaderFooters {
    pub header: Option<Vec<HeaderLine>>,
    pub footer: Option<Vec<HeaderLine>>,
    pub header_first: Option<Vec<HeaderLine>>,
    pub footer_first: Option<Vec<HeaderLine>>,
    pub header_even: Option<Vec<HeaderLine>>,
    pub footer_even: Option<Vec<HeaderLine>>,
    pub header_body: Option<Body>,
    pub footer_body: Option<Body>,
    pub header_body_first: Option<Body>,
    pub footer_body_first: Option<Body>,
    pub header_body_even: Option<Body>,
    pub footer_body_even: Option<Body>,
    pub title_page: bool,
}

/// The relationship id a section declares for one story, without
/// inheritance.
fn section_hf_reference(
    section: &crate::document::SectionProperties,
    role: HeaderFooterRole,
    variant: HeaderFooterVariant,
) -> Option<String> {
    match (role, variant) {
        (HeaderFooterRole::Header, HeaderFooterVariant::Default) => {
            section.header_reference.clone()
        }
        (HeaderFooterRole::Footer, HeaderFooterVariant::Default) => {
            section.footer_reference.clone()
        }
        (HeaderFooterRole::Header, HeaderFooterVariant::First) => {
            section.header_reference_first.clone()
        }
        (HeaderFooterRole::Footer, HeaderFooterVariant::First) => {
            section.footer_reference_first.clone()
        }
        (HeaderFooterRole::Header, HeaderFooterVariant::Even) => {
            section.header_reference_even.clone()
        }
        (HeaderFooterRole::Footer, HeaderFooterVariant::Even) => {
            section.footer_reference_even.clone()
        }
    }
}

/// The relationship id in effect for a story on `section_index`, walking
/// back through earlier sections the way Word's "link to previous" does.
pub(crate) fn hf_reference_for_section(
    document: &crate::document::Document,
    section_index: usize,
    role: HeaderFooterRole,
    variant: HeaderFooterVariant,
) -> Option<String> {
    let sections = &document.sections;
    if sections.is_empty() {
        return pick_hf_reference(document, role, variant);
    }
    let last = section_index.min(sections.len() - 1);
    (0..=last).rev().find_map(|index| {
        sections[index]
            .properties
            .as_ref()
            .and_then(|props| section_hf_reference(props, role, variant))
    })
}

pub(crate) fn pick_hf_reference(
    document: &crate::document::Document,
    role: HeaderFooterRole,
    variant: HeaderFooterVariant,
) -> Option<String> {
    match (role, variant) {
        (HeaderFooterRole::Header, HeaderFooterVariant::Default) => {
            document.header_reference.clone()
        }
        (HeaderFooterRole::Footer, HeaderFooterVariant::Default) => {
            document.footer_reference.clone()
        }
        (HeaderFooterRole::Header, HeaderFooterVariant::First) => document
            .default_section
            .as_ref()
            .and_then(|s| s.header_reference_first.clone()),
        (HeaderFooterRole::Footer, HeaderFooterVariant::First) => document
            .default_section
            .as_ref()
            .and_then(|s| s.footer_reference_first.clone()),
        (HeaderFooterRole::Header, HeaderFooterVariant::Even) => document
            .default_section
            .as_ref()
            .and_then(|s| s.header_reference_even.clone()),
        (HeaderFooterRole::Footer, HeaderFooterVariant::Even) => document
            .default_section
            .as_ref()
            .and_then(|s| s.footer_reference_even.clone()),
    }
}

