    #[test]
    fn scoped_revision_decision_ignores_paragraph_mark_outside_range() {
        let document_xml = r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>
<w:p><w:pPr><w:rPr><w:del w:id="7"/></w:rPr></w:pPr><w:r><w:t>First</w:t></w:r></w:p>
<w:p><w:ins w:id="8"><w:r><w:t>Second</w:t></w:r></w:ins></w:p>
</w:body></w:document>"#;
        let data = build_document_docx(document_xml);
        for accept in [true, false] {
            let mut word_doc =
                executor::block_on(WordDocument::load(&data, &Options::default())).expect("load");
            let result = if accept {
                word_doc.accept_revisions(None, Some(1), Some(1), None)
            } else {
                word_doc.reject_revisions(None, Some(1), Some(1), None)
            };
            assert_eq!(result, Ok(1));
            let exported = word_doc.export_docx().expect("export");
            let reloaded = executor::block_on(WordDocument::load(&exported, &Options::default()))
                .expect("reload");
            assert!(reloaded
                .ensure_revision_decision_supported(None, Some("7"))
                .is_err());
            assert_eq!(reloaded.paragraph_count(), 2);
            assert_eq!(reloaded.paragraph(0).map(paragraph_text_len), Some(5));
            assert_eq!(
                reloaded.paragraph(1).map(paragraph_text_len),
                Some(if accept { 6 } else { 0 })
            );
        }

        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load");
        assert_eq!(
            word_doc.accept_revisions(None, Some(0), Some(1), None),
            Ok(2)
        );
        assert_eq!(word_doc.paragraph_count(), 1);
    }

