    /// P4: settings.xml boolean toggles must round-trip through export.
    #[test]
    fn set_settings_flag_toggles_setting_in_exported_package() {
        let data = std::fs::read(fixture_path("hello.docx")).expect("read fixture");
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load word document");

        // Baseline: hello.docx has no trackChanges setting but does carry
        // evenAndOddHeaders.
        assert!(
            !exported_settings_xml(&word_doc).contains("trackChanges"),
            "baseline settings should not contain trackChanges"
        );
        assert!(
            exported_settings_xml(&word_doc).contains("evenAndOddHeaders"),
            "baseline settings should contain evenAndOddHeaders"
        );

        // The fixture explicitly disables this present setting with
        // `w:val="0"`; enabling it must remove that false value.
        word_doc
            .set_settings_flag("w:evenAndOddHeaders", true)
            .expect("enable explicit-false flag");
        let enabled_even_odd = exported_settings_xml(&word_doc);
        assert!(enabled_even_odd.contains("<w:evenAndOddHeaders"));
        assert!(!enabled_even_odd.contains("<w:evenAndOddHeaders w:val="));

        // Enable an absent flag: the element is inserted under <w:settings>.
        let previous = word_doc
            .set_settings_flag("w:trackChanges", true)
            .expect("enable flag");
        assert!(
            exported_settings_xml(&word_doc).contains("<w:trackChanges"),
            "enabling must insert the setting element"
        );

        // Disable it again: the element is removed.
        word_doc
            .set_settings_flag("w:trackChanges", false)
            .expect("disable flag");
        assert!(
            !exported_settings_xml(&word_doc).contains("trackChanges"),
            "disabling must remove the setting element"
        );

        // Disabling an existing flag removes it too.
        word_doc
            .set_settings_flag("w:evenAndOddHeaders", false)
            .expect("disable existing flag");
        assert!(
            !exported_settings_xml(&word_doc).contains("evenAndOddHeaders"),
            "disabling an existing setting must remove it"
        );

        // Undo via the captured snapshot restores the original part (which still
        // has evenAndOddHeaders and no trackChanges).
        word_doc.restore_settings_xml(previous);
        let restored = exported_settings_xml(&word_doc);
        assert!(
            restored.contains("evenAndOddHeaders") && !restored.contains("trackChanges"),
            "restore must bring back the original settings"
        );
    }

    fn bundled_font_path(name: &str) -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("..")
            .join("fonts")
            .join("Noto_Sans_JP")
            .join("static")
            .join(name)
    }

