    /// An authored `w:val="double" w:color="FF0000"` underline must survive a
    /// run resync. The sync used to force `w:val="single"`, flattening every
    /// decorated underline the moment its paragraph was edited.
    #[test]
    fn edited_run_keeps_authored_underline_kind_and_color() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:r><w:rPr><w:u w:val="double" w:color="FF0000"/></w:rPr><w:t>Hello</w:t></w:r></w:p>
  </w:body>
</w:document>
"#;
        let data = build_document_docx(document_xml);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        // Model carries the kind/color.
        let props = word_doc.paragraph(0).expect("paragraph").runs[0]
            .properties
            .clone()
            .expect("run props");
        assert_eq!(props.underline, Some(true));
        assert_eq!(props.underline_kind.as_deref(), Some("double"));
        assert_eq!(props.underline_color.as_deref(), Some("FF0000"));

        // Edit the paragraph so the run properties resync into the raw XML.
        crate::headless_api::apply_headless_commands_to_document(
            &mut word_doc,
            &jade_docx_headless_api::HeadlessEditRequest {
                commands: vec![jade_docx_headless_api::HeadlessCommand::InsertText {
                    paragraph: 0,
                    offset: 5,
                    text: "!".to_string(),
                }],
            },
        )
        .expect("insert text");

        let document = exported_document_xml(&word_doc);
        assert!(
            document.contains(r#"w:val="double""#),
            "underline kind must survive resync: {document}"
        );
        assert!(
            document.contains(r#"w:color="FF0000""#),
            "underline color must survive resync: {document}"
        );
    }

    /// Redo of an endnote/footnote insertion must reproduce the exact package
    /// of the first apply. Undo restores the raw `styles.xml`, and unless the
    /// parsed styles model is restored with it, `ensure_note_styles` still
    /// resolves the note styles created on the first apply, skips re-creating
    /// them on redo, and the redone package loses the style definitions
    /// (caught by the public endnote Playwright e2e as a redo hash mismatch).
    #[test]
    fn endnote_redo_recreates_note_styles_after_snapshot_restore() {
        use crate::commands::insert_endnote::InsertEndnoteCommand;
        use crate::commands::{CommandContext, CommandExecutor};
        use jade_docx_layout::selection::{SelectionRange, TextPosition};

        let data = std::fs::read(fixture_path("note-styles-creation.docx")).expect("read fixture");
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        let original = word_doc.export_docx().expect("export original");
        let range = SelectionRange::collapsed(TextPosition::new(0, 5));
        let mut selection = Some(range);
        let mut command_executor = CommandExecutor::new();
        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            command_executor
                .execute(
                    Box::new(InsertEndnoteCommand::new(range, "note".to_string())),
                    &mut ctx,
                )
                .expect("insert endnote");
        }
        let applied = word_doc.export_docx().expect("export applied");
        assert_ne!(applied, original, "insertion must change the package");
        let applied_styles = exported_part_xml(&word_doc, "word/styles.xml");
        assert!(
            applied_styles.contains("endnote text"),
            "first apply must create the note styles: {applied_styles}"
        );

        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            command_executor.undo(&mut ctx).expect("undo");
        }
        let undone = word_doc.export_docx().expect("export undone");
        assert_eq!(undone, original, "undo must restore the original package");
        assert_eq!(
            word_doc
                .styles_part
                .as_ref()
                .and_then(|styles| styles.resolve_paragraph_style_id("endnote text")),
            None,
            "undo must also forget the created styles in the parsed model"
        );

        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            command_executor.redo(&mut ctx).expect("redo");
        }
        let redone = word_doc.export_docx().expect("export redone");
        assert_eq!(
            redone, applied,
            "redo must reproduce the first apply byte-for-byte"
        );
    }

    /// Word adds the built-in `heading N` definition the first time a heading
    /// is applied to a document whose styles part lacks it. Without that, the
    /// exported `w:pStyle` names an undefined style and Word drops the heading
    /// look, outline level, navigation pane entry and TOC entry.
    #[test]
    fn applying_missing_builtin_heading_creates_word_style_definition() {
        use crate::commands::set_paragraph_style::SetParagraphStyleCommand;
        use crate::commands::{CommandContext, CommandExecutor};

        let data = std::fs::read(fixture_path("hello.docx")).expect("read fixture");
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");
        assert!(
            !exported_part_xml(&word_doc, "word/styles.xml").contains("heading 2"),
            "fixture must start without a heading 2 style"
        );
        let original = word_doc.export_docx().expect("export original");

        let mut selection = None;
        let mut command_executor = CommandExecutor::new();
        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            command_executor
                .execute(
                    Box::new(SetParagraphStyleCommand::new(
                        0,
                        0,
                        Some("Heading2".to_string()),
                    )),
                    &mut ctx,
                )
                .expect("apply Heading2");
        }

        let styles = exported_part_xml(&word_doc, "word/styles.xml");
        assert!(
            styles.contains(r#"w:styleId="Heading2""#),
            "definition must be added: {styles}"
        );
        assert!(
            styles.contains(r#"<w:name w:val="heading 2"/>"#),
            "{styles}"
        );
        assert!(styles.contains(r#"<w:outlineLvl w:val="1"/>"#), "{styles}");
        assert!(styles.contains("<w:keepNext/>"), "{styles}");
        let document = exported_document_xml(&word_doc);
        assert!(
            document.contains(r#"<w:pStyle w:val="Heading2"/>"#),
            "{document}"
        );
        let run = word_doc.paragraph(0).expect("paragraph").runs[0]
            .properties
            .clone()
            .expect("run props");
        assert_eq!(run.font_size, Some(14.0), "heading 2 is 14pt");
        let applied = word_doc.export_docx().expect("export applied");

        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            assert!(command_executor.undo(&mut ctx).expect("undo"));
        }
        assert_eq!(
            word_doc.export_docx().expect("export undone"),
            original,
            "undo must also remove the created definition"
        );

        {
            let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
            assert!(command_executor.redo(&mut ctx).expect("redo"));
        }
        assert_eq!(word_doc.export_docx().expect("export redone"), applied);
    }

