    #[test]
    fn document_theme_is_created_for_a_package_without_a_theme_part() {
        let data = build_document_docx(
            r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>Theme-less</w:t></w:r></w:p></w:body></w:document>"#,
        );
        let mut document = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load theme-less package");
        assert_eq!(document.document_theme(), None);

        let expected = DocumentThemeSpec {
            name: "新規 & Theme".to_string(),
            major_font: "Aptos Display".to_string(),
            minor_font: "Aptos & Body".to_string(),
            east_asia_font: "游ゴシック".to_string(),
            accent1: "#102A43".to_string(),
            ..DocumentThemeSpec::default()
        };
        assert!(document
            .set_document_theme(&expected)
            .expect("create document theme"));

        let exported = document.export_docx().expect("export themed package");
        let mut archive = ZipArchive::new(std::io::Cursor::new(&exported)).expect("open package");
        let mut theme_xml = String::new();
        archive
            .by_name("word/theme/theme1.xml")
            .expect("theme part")
            .read_to_string(&mut theme_xml)
            .expect("read theme part");
        assert!(theme_xml.contains("新規 &amp; Theme"));
        assert!(theme_xml.contains("Aptos &amp; Body"));

        let mut relationships = String::new();
        archive
            .by_name("word/_rels/document.xml.rels")
            .expect("document relationships")
            .read_to_string(&mut relationships)
            .expect("read document relationships");
        assert!(relationships.contains("relationships/theme"));
        assert!(relationships.contains("theme/theme1.xml"));

        let mut content_types = String::new();
        archive
            .by_name("[Content_Types].xml")
            .expect("content types")
            .read_to_string(&mut content_types)
            .expect("read content types");
        assert!(content_types.contains("/word/theme/theme1.xml"));
        drop(archive);

        let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
            .expect("reopen themed package");
        assert_eq!(
            reopened.document_theme(),
            Some(DocumentThemeSpec {
                accent1: "102A43".to_string(),
                ..expected
            })
        );
    }

