    proptest! {
        #![proptest_config(ProptestConfig { cases: 64, ..ProptestConfig::default() })]

        /// The host outline must preserve source order, Unicode/XML-reserved
        /// text, and selection paragraph coordinates for every valid OOXML
        /// level while excluding Word's body sentinel and empty headings.
        #[test]
        fn navigation_heading_catalog_is_coordinate_stable(
            generated in proptest::collection::vec(
                (
                    0u8..11,
                    proptest::collection::vec(
                        prop_oneof![
                            any::<char>().prop_filter("valid XML character", |value| {
                                matches!(*value, '\t' | '\n' | '\r')
                                    || (*value >= '\u{20}'
                                        && !matches!(*value, '\u{FFFE}' | '\u{FFFF}'))
                            }),
                            Just('<'),
                            Just('&'),
                            Just('>'),
                            Just('漢'),
                            Just('🙂'),
                        ],
                        0..40,
                    ),
                ),
                0..48,
            ),
        ) {
            let mut body = String::new();
            let mut expected = Vec::new();
            for (paragraph_index, (outline_level, characters)) in generated.iter().enumerate() {
                let text = characters.iter().collect::<String>();
                body.push_str(&format!(
                    "<w:p><w:pPr><w:outlineLvl w:val=\"{outline_level}\"/></w:pPr><w:r><w:t xml:space=\"preserve\">{}</w:t></w:r></w:p>",
                    xml_escape_text(&text),
                ));
                if *outline_level <= 8 && !text.trim().is_empty() {
                    // Word reads a line feed inside w:t as a space.
                    expected.push(NavigationHeadingInfo {
                        paragraph_index,
                        level: outline_level + 1,
                        text: text.replace("\r\n", " ").replace(['\n', '\r'], " "),
                    });
                }
            }
            let xml = format!(
                "<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>{body}</w:body></w:document>"
            );
            let data = build_document_docx(&xml);
            let word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load generated navigation headings");
            prop_assert_eq!(word_doc.navigation_headings(), expected);
        }
    }

    fn omitted_grid_table_xml(columns: usize, before: usize, after: usize) -> String {
        let widths: Vec<u32> = (0..columns)
            .map(|column| 400 + column as u32 * 100)
            .collect();
        let grid = widths
            .iter()
            .map(|width| format!(r#"<w:gridCol w:w="{width}"/>"#))
            .collect::<String>();
        let full_row = widths
            .iter()
            .enumerate()
            .map(|(column, width)| {
                format!(
                    r#"<w:tc><w:tcPr><w:tcW w:w="{width}" w:type="dxa"/></w:tcPr><w:p><w:r><w:t>f{column}</w:t></w:r></w:p></w:tc>"#
                )
            })
            .collect::<String>();
        let middle_end = columns - after;
        let partial_row = widths[before..middle_end]
            .iter()
            .enumerate()
            .map(|(column, width)| {
                format!(
                    r#"<w:tc><w:tcPr><w:tcW w:w="{width}" w:type="dxa"/></w:tcPr><w:p><w:r><w:t>p{column}</w:t></w:r></w:p></w:tc>"#
                )
            })
            .collect::<String>();
        let before_width: u32 = widths[..before].iter().sum();
        let after_width: u32 = widths[middle_end..].iter().sum();
        format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:tbl>
    <w:tblPr><w:tblW w:w="0" w:type="auto"/></w:tblPr>
    <w:tblGrid>{grid}</w:tblGrid>
    <w:tr>{full_row}</w:tr>
    <w:tr><w:trPr>
      <w:gridBefore w:val="{before}"/><w:wBefore w:w="{before_width}" w:type="dxa"/>
      <w:gridAfter w:val="{after}"/><w:wAfter w:w="{after_width}" w:type="dxa"/>
    </w:trPr>{partial_row}</w:tr>
  </w:tbl></w:body>
</w:document>"#
        )
    }

    fn rich_nested_table_xml(
        rows: usize,
        columns: usize,
        rich_row: usize,
        rich_column: usize,
    ) -> String {
        let grid = (0..columns)
            .map(|_| r#"<w:gridCol w:w="800"/>"#)
            .collect::<String>();
        let body = (0..rows)
            .map(|row| {
                let cells = (0..columns)
                    .map(|column| {
                        if row == rich_row && column == rich_column {
                            r#"<w:tc>
  <w:tcPr><w:shd w:fill="ABCDEF"/></w:tcPr>
  <w:p w:rsidR="00ABCDEF"><w:pPr><w:pStyle w:val="KeepStyle"/></w:pPr>
    <w:bookmarkStart w:id="91" w:name="KeepBookmark"/>
    <w:r><w:rPr><w:b/></w:rPr><w:t>host</w:t></w:r>
    <w:bookmarkEnd w:id="91"/>
  </w:p>
  <m:oMathPara><m:oMath><m:r><m:t>x+y</m:t></m:r></m:oMath></m:oMathPara>
  <w:tbl><w:tblPr><w:tblStyle w:val="NestedKeep"/></w:tblPr>
    <w:tblGrid><w:gridCol w:w="400"/></w:tblGrid>
    <w:tr><w:tc><w:p><w:r><w:t>nested</w:t></w:r></w:p></w:tc></w:tr>
  </w:tbl>
  <w:p><w:r><w:t>tail</w:t></w:r></w:p>
</w:tc>"#
                                .to_string()
                        } else {
                            format!(
                                r#"<w:tc><w:p><w:r><w:t>{row}:{column}</w:t></w:r></w:p></w:tc>"#
                            )
                        }
                    })
                    .collect::<String>();
                format!(r#"<w:tr>{cells}</w:tr>"#)
            })
            .collect::<String>();
        format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
            xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math">
  <w:body><w:tbl><w:tblPr><w:tblStyle w:val="OuterKeep"/></w:tblPr>
    <w:tblGrid>{grid}</w:tblGrid>{body}
  </w:tbl></w:body>
</w:document>"#
        )
    }

    fn assert_rich_nested_cell_xml_is_preserved(
        word_doc: &WordDocument,
        expected_row: usize,
        expected_column: usize,
    ) {
        let raw = word_doc.raw_document.as_ref().expect("raw document");
        let xml = raw.to_string().expect("serialize document xml");
        for marker in [
            "KeepStyle",
            "KeepBookmark",
            "00ABCDEF",
            "x+y",
            "NestedKeep",
            ">nested<",
            ">tail<",
        ] {
            assert!(xml.contains(marker), "missing preserved marker {marker}");
        }
        assert!(word_doc.table_by_order(1).is_some(), "nested table model");
        let outer = word_doc.table_by_order(0).expect("outer table model");
        let rich_cell = outer
            .rows
            .get(expected_row)
            .and_then(|row| row.cells.get(expected_column))
            .expect("rich cell at expected coordinate");
        assert!(
            rich_cell
                .blocks
                .iter()
                .any(|block| matches!(block, BodyElement::Table(_))),
            "nested table moved away from ({expected_row}, {expected_column})"
        );
    }

    fn assert_rich_nested_cell_xml_is_absent(word_doc: &WordDocument) {
        let raw = word_doc.raw_document.as_ref().expect("raw document");
        let xml = raw.to_string().expect("serialize document xml");
        for marker in [
            "KeepStyle",
            "KeepBookmark",
            "00ABCDEF",
            "x+y",
            "NestedKeep",
            ">nested<",
            ">tail<",
        ] {
            assert!(!xml.contains(marker), "unexpected deleted marker {marker}");
        }
        assert!(word_doc.table_by_order(1).is_none(), "deleted nested table");
    }

    #[test]
    fn table_style_preset_replaces_only_the_target_table_named_style() {
        let data = build_document_docx(&rich_nested_table_xml(2, 2, 0, 0));
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load styled nested table");

        word_doc
            .apply_table_style_preset(0, "blueBands")
            .expect("apply direct-formatting preset");

        let xml = word_doc
            .raw_document
            .as_ref()
            .expect("raw document")
            .to_string()
            .expect("serialize document xml");
        assert!(!xml.contains("OuterKeep"), "target named style was removed");
        assert!(
            xml.contains("NestedKeep"),
            "nested table style was preserved"
        );
        assert_eq!(
            word_doc
                .table_by_order(0)
                .and_then(|table| table.style_name.as_deref()),
            None
        );
        assert_eq!(
            word_doc
                .table_by_order(1)
                .and_then(|table| table.style_name.as_deref()),
            Some("NestedKeep")
        );

        let exported = word_doc.export_docx().expect("export styled nested table");
        let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
            .expect("reopen styled nested table");
        let reopened_xml = reopened
            .raw_document
            .as_ref()
            .expect("reopened raw document")
            .to_string()
            .expect("serialize reopened document xml");
        assert!(!reopened_xml.contains("OuterKeep"));
        assert!(reopened_xml.contains("NestedKeep"));
        assert_eq!(
            reopened
                .table_by_order(0)
                .and_then(|table| table.style_name.as_deref()),
            None
        );
        assert_eq!(
            reopened
                .table_by_order(1)
                .and_then(|table| table.style_name.as_deref()),
            Some("NestedKeep")
        );
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 48, ..ProptestConfig::default() })]

        /// Rewriting an outer table for structural row/column edits must keep
        /// the exact body XML of surviving cells. This includes content the
        /// table model cannot regenerate: paragraph properties, bookmarks,
        /// OMML and a nested table with its own table properties.
        #[test]
        fn table_structure_edits_preserve_rich_nested_cell_content_and_history(
            rows in 2usize..6,
            columns in 2usize..6,
            operation in 0u8..6,
            raw_index in any::<usize>(),
            raw_rich_row in any::<usize>(),
            raw_rich_column in any::<usize>(),
        ) {
            let rich_row = raw_rich_row % rows;
            let rich_column = raw_rich_column % columns;
            let data = build_document_docx(&rich_nested_table_xml(
                rows,
                columns,
                rich_row,
                rich_column,
            ));
            let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load rich nested table");
            assert_rich_nested_cell_xml_is_preserved(&word_doc, rich_row, rich_column);

            let (op, expected_row, expected_column) = match operation {
                0 => {
                    let row_index = raw_index % (rows + 1);
                    (
                        TableStructureOp::InsertRow {
                            row_index,
                            template_row: None,
                        },
                        rich_row + usize::from(row_index <= rich_row),
                        rich_column,
                    )
                }
                1 => {
                    let candidate = raw_index % (rows - 1);
                    let row_index = candidate + usize::from(candidate >= rich_row);
                    (
                        TableStructureOp::DeleteRow { row_index },
                        rich_row - usize::from(row_index < rich_row),
                        rich_column,
                    )
                }
                2 => {
                    let column_index = raw_index % (columns + 1);
                    (
                        TableStructureOp::InsertColumn {
                            column_index,
                            width: Some((raw_index % 200) as f32),
                            template_column: None,
                        },
                        rich_row,
                        rich_column + usize::from(column_index <= rich_column),
                    )
                }
                3 => {
                    let candidate = raw_index % (columns - 1);
                    let column_index = candidate + usize::from(candidate >= rich_column);
                    (
                        TableStructureOp::DeleteColumn { column_index },
                        rich_row,
                        rich_column - usize::from(column_index < rich_column),
                    )
                }
                4 => (
                    TableStructureOp::DeleteRow { row_index: rich_row },
                    rich_row,
                    rich_column,
                ),
                5 => (
                    TableStructureOp::DeleteColumn {
                        column_index: rich_column,
                    },
                    rich_row,
                    rich_column,
                ),
                _ => unreachable!(),
            };
            let rich_cell_survives = operation < 4;
            let mut selection = None;
            let mut command_executor = CommandExecutor::new();
            {
                let mut context = CommandContext::new(&mut word_doc, &mut selection);
                command_executor
                    .execute(Box::new(TableStructureCommand::new(0, op)), &mut context)
                    .expect("structural table edit");
            }
            if rich_cell_survives {
                assert_rich_nested_cell_xml_is_preserved(
                    &word_doc,
                    expected_row,
                    expected_column,
                );

                // A structural rewrite must leave the surviving paragraph's
                // model ids pointing at its restored raw XML, so a subsequent
                // run edit updates the right cell and remains independently
                // undoable.
                let host_paragraph = (0..word_doc.paragraph_count())
                    .find(|index| {
                        word_doc.paragraph(*index).is_some_and(|paragraph| {
                            paragraph.runs.iter().any(|run| run.text == "host")
                        })
                    })
                    .expect("host paragraph after structural edit");
                let range = jade_docx_layout::selection::SelectionRange::collapsed(
                    TextPosition::new(host_paragraph, 4),
                );
                let mut text_executor = CommandExecutor::new();
                {
                    let mut context = CommandContext::new(&mut word_doc, &mut selection);
                    text_executor
                        .execute(
                            Box::new(crate::commands::insert_text::InsertTextCommand::new(
                                range,
                                "!".to_string(),
                                None,
                            )),
                            &mut context,
                        )
                        .expect("edit surviving cell after structural rewrite");
                }
                let edited_xml = word_doc
                    .raw_document
                    .as_ref()
                    .expect("raw document")
                    .to_string()
                    .expect("serialize edited table");
                prop_assert!(edited_xml.contains("host!"));
                {
                    let mut context = CommandContext::new(&mut word_doc, &mut selection);
                    prop_assert!(text_executor.undo(&mut context).expect("undo cell text edit"));
                }
                assert_rich_nested_cell_xml_is_preserved(
                    &word_doc,
                    expected_row,
                    expected_column,
                );
            } else {
                assert_rich_nested_cell_xml_is_absent(&word_doc);
            }

            {
                let mut context = CommandContext::new(&mut word_doc, &mut selection);
                prop_assert!(command_executor.undo(&mut context).expect("undo table edit"));
            }
            assert_rich_nested_cell_xml_is_preserved(&word_doc, rich_row, rich_column);

            {
                let mut context = CommandContext::new(&mut word_doc, &mut selection);
                prop_assert!(command_executor.redo(&mut context).expect("redo table edit"));
            }
            if rich_cell_survives {
                assert_rich_nested_cell_xml_is_preserved(
                    &word_doc,
                    expected_row,
                    expected_column,
                );
            } else {
                assert_rich_nested_cell_xml_is_absent(&word_doc);
            }

            let exported = word_doc.export_docx().expect("export rich nested table");
            let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
                .expect("reopen rich nested table");
            if rich_cell_survives {
                assert_rich_nested_cell_xml_is_preserved(
                    &reopened,
                    expected_row,
                    expected_column,
                );
            } else {
                assert_rich_nested_cell_xml_is_absent(&reopened);
            }
        }

        /// Width replacement and interactive boundary resizing must update the
        /// preferred widths of omitted row regions as well as ordinary cells.
        /// Undo/redo and DOCX round-tripping must preserve the same grid sums.
        #[test]
        fn column_width_edits_keep_omitted_grid_widths_in_sync(
            replacement in prop::collection::vec(0u16..3000, 4..8),
            before in 1usize..4,
            after in 1usize..4,
            operation in 0u8..4,
            target in any::<usize>(),
        ) {
            let columns = replacement.len();
            prop_assume!(before + after < columns);
            let data = build_document_docx(&omitted_grid_table_xml(columns, before, after));
            let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load omitted-grid table");
            let original_widths = word_doc
                .table_by_order(0)
                .expect("table")
                .columns
                .iter()
                .map(|column| column.width.expect("fixture grid width"))
                .collect::<Vec<_>>();
            let requested = replacement
                .iter()
                .map(|width| *width as f32 / 10.0)
                .collect::<Vec<_>>();
            let normalized = requested
                .iter()
                .map(|width| width.max(MIN_TABLE_COLUMN_WIDTH_PT))
                .collect::<Vec<_>>();
            let mut expected = original_widths.clone();
            let mut command_executor = CommandExecutor::new();
            let mut selection = None;

            match operation {
                0 => {
                    word_doc
                        .set_table_column_widths(0, &requested)
                        .expect("set every column width");
                    expected.clone_from(&normalized);
                }
                1 => {
                    let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
                    command_executor
                        .execute(
                            Box::new(ResizeTableColumnCommand::all_columns(0, requested)),
                            &mut ctx,
                        )
                        .expect("replace every rendered column width");
                    expected.clone_from(&normalized);
                }
                2 => {
                    let left = target % (columns - 1);
                    let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
                    command_executor
                        .execute(
                            Box::new(ResizeTableColumnCommand::between_columns(
                                0,
                                left,
                                requested[left],
                                requested[left + 1],
                            )),
                            &mut ctx,
                        )
                        .expect("resize an interior boundary");
                    expected[left] = normalized[left];
                    expected[left + 1] = normalized[left + 1];
                }
                3 => {
                    let column = target % columns;
                    let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
                    command_executor
                        .execute(
                            Box::new(ResizeTableColumnCommand::table_right_edge(
                                0,
                                column,
                                requested[column],
                            )),
                            &mut ctx,
                        )
                        .expect("resize the table right edge");
                    expected[column] = normalized[column];
                }
                _ => unreachable!(),
            }

            let assert_width_invariants = |document: &WordDocument, widths: &[f32]| {
                let table = document.table_by_order(0).expect("table");
                assert_eq!(
                    table.columns.iter().map(|column| column.width).collect::<Vec<_>>(),
                    widths.iter().copied().map(Some).collect::<Vec<_>>(),
                );
                let partial = &table.rows[1];
                let expected_before = format!("{:.2}pt", widths[..before].iter().sum::<f32>());
                let expected_after = format!(
                    "{:.2}pt",
                    widths[columns - after..].iter().sum::<f32>()
                );
                assert_eq!(partial.width_before.as_deref(), Some(expected_before.as_str()));
                assert_eq!(partial.width_after.as_deref(), Some(expected_after.as_str()));
                for (offset, cell) in partial.cells.iter().enumerate() {
                    assert_eq!(
                        cell.style.get("width"),
                        Some(&format!("{:.2}pt", widths[before + offset])),
                    );
                }
            };

            assert_width_invariants(&word_doc, &expected);
            if operation != 0 {
                {
                    let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
                    prop_assert!(command_executor.undo(&mut ctx).expect("undo width edit"));
                }
                assert_width_invariants(&word_doc, &original_widths);
                {
                    let mut ctx = CommandContext::new(&mut word_doc, &mut selection);
                    prop_assert!(command_executor.redo(&mut ctx).expect("redo width edit"));
                }
                assert_width_invariants(&word_doc, &expected);
            }

            let exported = word_doc.export_docx().expect("export resized omitted-grid table");
            let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
                .expect("reopen resized omitted-grid table");
            assert_width_invariants(&reopened, &expected);
        }

        /// Structural column edits inside omitted leading/trailing regions and
        /// the physical middle must keep every row aligned to tblGrid in both
        /// the model and exported XML.
        #[test]
        fn column_edits_round_trip_rows_with_omitted_grid_regions(
            columns in 4usize..8,
            before in 1usize..4,
            after in 1usize..4,
            insert in any::<bool>(),
            region in 0u8..3,
            trailing_at_end in any::<bool>(),
            inserted_width in 0u32..120,
        ) {
            prop_assume!(before + after < columns);
            prop_assume!(region != 2 || !insert || trailing_at_end || after >= 2);
            let data = build_document_docx(&omitted_grid_table_xml(columns, before, after));
            let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load omitted-grid table");
            let middle = columns - before - after;
            let cell_end = columns - after;
            let column = match (region, insert) {
                (0, _) => before - 1,
                (1, _) => before,
                (2, true) => if trailing_at_end { columns } else { cell_end + 1 },
                (2, false) => columns - 1,
                _ => unreachable!(),
            };

            if insert {
                word_doc
                    .insert_table_column(0, column, Some(inserted_width as f32), None)
                    .expect("insert inside omitted region");
            } else {
                word_doc
                    .delete_table_column(0, column)
                    .expect("delete inside omitted region");
            }

            let expected_columns = if insert { columns + 1 } else { columns - 1 };
            let expected_before = if region == 0 {
                if insert { before + 1 } else { before - 1 }
            } else {
                before
            };
            let expected_after = if region == 0 || region == 1 && (insert || middle > 1) {
                after
            } else if region == 2 && insert {
                after + 1
            } else {
                after - 1
            };
            let table = word_doc.table_by_order(0).expect("table");
            let partial = &table.rows[1];
            prop_assert!(!partial.cells.is_empty());
            prop_assert_eq!(partial.grid_before.unwrap_or(0) as usize, expected_before);
            prop_assert_eq!(partial.grid_after.unwrap_or(0) as usize, expected_after);
            let coverage = partial.grid_before.unwrap_or(0) as usize
                + partial.cells.iter().map(|cell| cell.span.unwrap_or(1).max(1) as usize).sum::<usize>()
                + partial.grid_after.unwrap_or(0) as usize;
            prop_assert_eq!(coverage, expected_columns);
            prop_assert_eq!(table.columns.len(), expected_columns);
            if insert {
                prop_assert_eq!(
                    table.columns[column].width,
                    Some((inserted_width as f32).max(MIN_TABLE_COLUMN_WIDTH_PT)),
                );
            }
            let expected_width_before = partial.width_before.clone();
            let expected_width_after = partial.width_after.clone();

            let exported = word_doc.export_docx().expect("export edited omitted-grid table");
            let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
                .expect("reopen edited omitted-grid table");
            let reopened_table = reopened.table_by_order(0).expect("reopened table");
            let reopened_partial = &reopened_table.rows[1];
            prop_assert!(!reopened_partial.cells.is_empty());
            prop_assert_eq!(reopened_table.columns.len(), expected_columns);
            prop_assert_eq!(reopened_partial.grid_before.unwrap_or(0) as usize, expected_before);
            prop_assert_eq!(reopened_partial.grid_after.unwrap_or(0) as usize, expected_after);
            if insert {
                prop_assert_eq!(
                    reopened_table.columns[column].width,
                    Some((inserted_width as f32).max(MIN_TABLE_COLUMN_WIDTH_PT)),
                );
            }
            prop_assert_eq!(reopened_partial.width_before.clone(), expected_width_before);
            prop_assert_eq!(reopened_partial.width_after.clone(), expected_width_after);
        }
    }

    fn body_paragraphs_xml(count: usize) -> String {
        let mut xml = String::from(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
"#,
        );
        for index in 0..count {
            xml.push_str(&format!(
                r#"    <w:p><w:r><w:t>Paragraph {index}</w:t></w:r></w:p>
"#
            ));
        }
        xml.push_str(
            r#"  </w:body>
</w:document>
"#,
        );
        xml
    }

    fn read_document_xml_from_docx(data: &[u8]) -> String {
        let mut archive =
            ZipArchive::new(std::io::Cursor::new(data)).expect("zip archive for docx");
        let mut document_xml = String::new();
        archive
            .by_name("word/document.xml")
            .expect("document.xml in docx")
            .read_to_string(&mut document_xml)
            .expect("read document xml");
        document_xml
    }

