    #[test]
    fn editing_text_preserves_authored_image_drawingml() {
        use crate::commands::{insert_text::InsertTextCommand, CommandContext, CommandExecutor};
        use jade_docx_layout::selection::{SelectionRange, TextPosition};

        for (fixture, preserved) in [
            (
                "image-floating.docx",
                &[
                    "descr=\"10220449.png\"",
                    "<a:ln w=\"12700\" cap=\"flat\">",
                    "<a:noFill/>",
                    "<a:miter lim=\"400000\"/>",
                    "<a:effectLst/>",
                    "<wp:effectExtent l=\"0\" t=\"0\" r=\"0\" b=\"0\"/>",
                    "<wp:wrapThrough wrapText=\"bothSides\" distL=\"152400\" distR=\"152400\">",
                    "<a:extLst/>",
                ][..],
            ),
            (
                "image-inline.docx",
                &[
                    "<wp:effectExtent l=\"0\" t=\"0\" r=\"0\" b=\"0\"/>",
                    "<a:graphicFrameLocks xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" noChangeAspect=\"1\"/>",
                    "<a14:useLocalDpi xmlns:a14=\"http://schemas.microsoft.com/office/drawing/2010/main\" val=\"0\"/>",
                    "wp14:anchorId=\"5D0FFA16\"",
                    "wp14:editId=\"3C7C8BD2\"",
                    "<pic:cNvPicPr/>",
                ][..],
            ),
        ] {
            let data = std::fs::read(fixture_path(fixture)).expect("read image fixture");
            let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load image fixture");
            let range = SelectionRange::collapsed(TextPosition::new(0, 0));
            let mut selection = Some(range);
            CommandExecutor::new()
                .execute(
                    Box::new(InsertTextCommand::new(range, "X".to_string(), None)),
                    &mut CommandContext::new(&mut word_doc, &mut selection),
                )
                .expect("insert text");

            let xml = exported_document_xml(&word_doc);
            for expected in preserved {
                assert!(xml.contains(expected), "{fixture} lost {expected}: {xml}");
            }
            if fixture == "image-inline.docx" {
                assert!(!xml.contains("<a:picLocks"), "invented picture locks: {xml}");
            }
        }
    }

    #[test]
    fn edited_image_drawingml_exports_and_round_trips_layout_and_crop() {
        let data = build_document_docx(single_image_document_xml());
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load image docx");
        let image = word_doc
            .paragraph_mut(0)
            .and_then(|paragraph| paragraph.runs[0].image.as_mut())
            .expect("image");
        image.width_px = Some(144.5);
        image.height_px = Some(91.25);
        image.crop = Some(crate::document::ImageCrop {
            left: 0.1,
            top: 0.2,
            right: 0.15,
            bottom: 0.05,
        });
        image.layout = RunImageLayout {
            kind: RunImageKind::Floating,
            position_h: Some(ImagePosition {
                relative_from: Some("margin".into()),
                offset_px: None,
                align: Some("right".into()),
            }),
            position_v: Some(ImagePosition {
                relative_from: Some("page".into()),
                offset_px: Some(42.5),
                align: None,
            }),
            rotation_deg: Some(12.5),
            flip_horizontal: true,
            flip_vertical: true,
            wrap: WrapMode::Through,
            wrap_text: WrapTextSide::Right,
            wrap_polygon: Some(WrapPolygon {
                edited: true,
                points: vec![
                    WrapPolygonPoint { x: 10800, y: 0 },
                    WrapPolygonPoint { x: 21600, y: 21600 },
                    WrapPolygonPoint { x: 0, y: 21600 },
                    WrapPolygonPoint { x: 10800, y: 0 },
                ],
            }),
            behind_doc: true,
            relative_height: Some(251_659_777),
            simple_position: Some(ImageSimplePosition {
                x_px: -12.5,
                y_px: 27.25,
            }),
            dist_top: Some(3.0),
            dist_bottom: Some(4.0),
            dist_left: Some(5.0),
            dist_right: Some(6.0),
        };
        word_doc.paragraph_mut(0).unwrap().runs[0].node_id = None;
        word_doc.sync_paragraph_text(0);

        let exported = word_doc.export_docx().expect("export image docx");
        let xml = read_document_xml_from_docx(&exported);
        assert!(xml.contains("<wp:anchor"), "missing floating anchor: {xml}");
        assert!(xml.contains("behindDoc=\"1\""), "missing behindDoc: {xml}");
        assert!(
            xml.contains("relativeHeight=\"251659777\""),
            "missing relativeHeight: {xml}"
        );
        assert!(xml.contains("simplePos=\"1\""), "missing simplePos: {xml}");
        assert!(
            xml.contains("<wp:simplePos x=\"-119063\" y=\"259556\"/>"),
            "missing simple coordinates: {xml}"
        );
        assert!(
            xml.contains("<wp:wrapThrough wrapText=\"right\"><wp:wrapPolygon edited=\"1\"><wp:start x=\"10800\" y=\"0\"/>")
                && xml.contains("<wp:lineTo x=\"21600\" y=\"21600\"/>")
                && xml.contains("<wp:lineTo x=\"0\" y=\"21600\"/>"),
            "missing edited wrap polygon: {xml}"
        );
        assert!(
            xml.contains("<wp:align>right</wp:align>"),
            "missing align: {xml}"
        );
        assert!(
            xml.contains("<a:srcRect l=\"10000\" t=\"20000\" r=\"15000\" b=\"5000\"/>"),
            "missing crop: {xml}"
        );
        assert!(xml.contains("rot=\"750000\""), "missing rotation: {xml}");
        assert!(
            xml.contains("flipH=\"1\""),
            "missing horizontal flip: {xml}"
        );
        assert!(xml.contains("flipV=\"1\""), "missing vertical flip: {xml}");

        let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
            .expect("reopen image docx");
        let image = reopened.paragraph(0).unwrap().runs[0]
            .image
            .as_ref()
            .unwrap();
        assert!((image.width_px.unwrap() - 144.5).abs() < 0.001);
        assert!((image.height_px.unwrap() - 91.25).abs() < 0.001);
        assert_eq!(image.crop.unwrap().left, 0.1);
        assert_eq!(image.layout.kind, RunImageKind::Floating);
        assert_eq!(image.layout.wrap, WrapMode::Through);
        assert_eq!(image.layout.wrap_text, WrapTextSide::Right);
        assert_eq!(
            image
                .layout
                .wrap_polygon
                .as_ref()
                .expect("wrap polygon")
                .points,
            vec![
                WrapPolygonPoint { x: 10800, y: 0 },
                WrapPolygonPoint { x: 21600, y: 21600 },
                WrapPolygonPoint { x: 0, y: 21600 },
                WrapPolygonPoint { x: 10800, y: 0 },
            ]
        );
        assert!(image.layout.behind_doc);
        assert_eq!(image.layout.relative_height, Some(251_659_777));
        let simple_position = image.layout.simple_position.expect("simple position");
        assert!((simple_position.x_px + 12.5).abs() < 0.001);
        assert!((simple_position.y_px - 27.25).abs() < 0.001);
        assert_eq!(
            image.layout.position_h.as_ref().unwrap().align.as_deref(),
            Some("right")
        );
        assert!((image.layout.rotation_deg.unwrap() - 12.5).abs() < 0.001);
        assert!(image.layout.flip_horizontal);
        assert!(image.layout.flip_vertical);
    }

    #[test]
    fn edited_image_preserves_negative_drawingml_crop_edges() {
        let data = build_document_docx(single_image_document_xml());
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load image docx");
        let expected = crate::document::ImageCrop {
            left: -0.2,
            top: 0.125,
            right: -0.075,
            bottom: 0.25,
        };
        let run = &mut word_doc.paragraph_mut(0).unwrap().runs[0];
        run.image.as_mut().expect("image").crop = Some(expected);
        run.node_id = None;
        word_doc.sync_paragraph_text(0);

        let exported = word_doc.export_docx().expect("export image docx");
        let xml = read_document_xml_from_docx(&exported);
        assert!(
            xml.contains("<a:srcRect l=\"-20000\" t=\"12500\" r=\"-7500\" b=\"25000\"/>"),
            "negative crop edges were clamped: {xml}"
        );

        let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
            .expect("reopen image docx");
        let actual = reopened.paragraph(0).unwrap().runs[0]
            .image
            .as_ref()
            .and_then(|image| image.crop)
            .expect("round-tripped crop");
        assert_eq!(actual, expected);
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 96, ..ProptestConfig::default() })]

        #[test]
        fn image_drawingml_property_round_trips_current_layout(
            width_hundredths in 100u32..80_000,
            height_hundredths in 100u32..80_000,
            left_pct in 0u32..40,
            right_pct in 0u32..40,
            top_pct in 0u32..40,
            bottom_pct in 0u32..40,
            x_tenths in -2_000i32..8_000,
            y_tenths in -2_000i32..8_000,
            rotation_tenths in -3_600i32..3_600,
            wrap_index in 0u8..5,
            wrap_side_index in 0u8..4,
            floating in any::<bool>(),
            behind_doc in any::<bool>(),
            relative_height in any::<u32>(),
            flip_horizontal in any::<bool>(),
            flip_vertical in any::<bool>(),
        ) {
            let data = build_document_docx(single_image_document_xml());
            let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load image docx");
            let expected_width = width_hundredths as f64 / 100.0;
            let expected_height = height_hundredths as f64 / 100.0;
            let expected_crop = crate::document::ImageCrop {
                left: left_pct as f64 / 100.0,
                right: right_pct as f64 / 100.0,
                top: top_pct as f64 / 100.0,
                bottom: bottom_pct as f64 / 100.0,
            };
            let expected_wrap = match wrap_index {
                0 => WrapMode::None,
                1 => WrapMode::Square,
                2 => WrapMode::Tight,
                3 => WrapMode::Through,
                _ => WrapMode::TopAndBottom,
            };
            let authored_wrap_text = match wrap_side_index {
                0 => WrapTextSide::BothSides,
                1 => WrapTextSide::Left,
                2 => WrapTextSide::Right,
                _ => WrapTextSide::Largest,
            };
            let expected_wrap_text = if matches!(
                expected_wrap,
                WrapMode::Square | WrapMode::Tight | WrapMode::Through
            ) {
                authored_wrap_text
            } else {
                WrapTextSide::BothSides
            };
            let expected_kind = if floating { RunImageKind::Floating } else { RunImageKind::Inline };
            let expected_rotation = rotation_tenths as f64 / 10.0;
            let authored_wrap_polygon = WrapPolygon {
                edited: true,
                points: vec![
                    WrapPolygonPoint { x: 10800, y: 0 },
                    WrapPolygonPoint { x: 21600, y: 21600 },
                    WrapPolygonPoint { x: 0, y: 21600 },
                    WrapPolygonPoint { x: 10800, y: 0 },
                ],
            };
            let expected_wrap_polygon = matches!(expected_wrap, WrapMode::Tight | WrapMode::Through)
                .then_some(authored_wrap_polygon.clone());
            {
                let image = word_doc.paragraph_mut(0).unwrap().runs[0].image.as_mut().unwrap();
                image.width_px = Some(expected_width);
                image.height_px = Some(expected_height);
                image.crop = Some(expected_crop);
                image.layout = RunImageLayout {
                    kind: expected_kind,
                    position_h: Some(ImagePosition {
                        relative_from: Some("page".into()),
                        offset_px: Some(x_tenths as f64 / 10.0),
                        align: None,
                    }),
                    position_v: Some(ImagePosition {
                        relative_from: Some("page".into()),
                        offset_px: Some(y_tenths as f64 / 10.0),
                        align: None,
                    }),
                    rotation_deg: Some(expected_rotation),
                    flip_horizontal,
                    flip_vertical,
                    wrap: expected_wrap,
                    wrap_text: authored_wrap_text,
                    wrap_polygon: Some(authored_wrap_polygon),
                    behind_doc,
                    relative_height: Some(relative_height),
                    simple_position: None,
                    dist_top: Some(2.0),
                    dist_bottom: Some(3.0),
                    dist_left: Some(4.0),
                    dist_right: Some(5.0),
                };
            }
            word_doc.paragraph_mut(0).unwrap().runs[0].node_id = None;
            word_doc.sync_paragraph_text(0);
            let exported = word_doc.export_docx().expect("export image docx");
            let reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
                .expect("reopen image docx");
            let actual = reopened.paragraph(0).unwrap().runs[0].image.as_ref().unwrap();

            prop_assert!((actual.width_px.unwrap() - expected_width).abs() < 0.001);
            prop_assert!((actual.height_px.unwrap() - expected_height).abs() < 0.001);
            prop_assert_eq!(actual.crop, Some(expected_crop));
            prop_assert_eq!(actual.layout.kind, expected_kind);
            prop_assert_eq!(actual.layout.rotation_deg, Some(expected_rotation));
            prop_assert_eq!(actual.layout.flip_horizontal, flip_horizontal);
            prop_assert_eq!(actual.layout.flip_vertical, flip_vertical);
            if floating {
                prop_assert_eq!(actual.layout.wrap, expected_wrap);
                prop_assert_eq!(actual.layout.wrap_text, expected_wrap_text);
                prop_assert_eq!(actual.layout.wrap_polygon.clone(), expected_wrap_polygon);
                prop_assert_eq!(actual.layout.behind_doc, behind_doc);
                prop_assert_eq!(actual.layout.relative_height, Some(relative_height));
                prop_assert!((actual.layout.position_h.as_ref().unwrap().offset_px.unwrap() - x_tenths as f64 / 10.0).abs() < 0.001);
                prop_assert!((actual.layout.position_v.as_ref().unwrap().offset_px.unwrap() - y_tenths as f64 / 10.0).abs() < 0.001);
            } else {
                prop_assert_eq!(actual.layout.kind, RunImageKind::Inline);
            }
        }
    }

    #[test]
    fn remove_paragraph_range_at_updates_model_and_raw_xml() {
        let data = build_document_docx(&body_paragraphs_xml(5));
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated docx");

        assert!(word_doc.remove_paragraph_range_at(1, 3));
        assert_eq!(word_doc.paragraph_count(), 2);
        assert_eq!(
            word_doc.paragraph(0).expect("first").runs[0].text,
            "Paragraph 0"
        );
        assert_eq!(
            word_doc.paragraph(1).expect("second").runs[0].text,
            "Paragraph 4"
        );

        let xml = exported_document_xml(&word_doc);
        assert!(xml.contains("Paragraph 0"));
        assert!(xml.contains("Paragraph 4"));
        assert!(!xml.contains("Paragraph 1"));
        assert!(!xml.contains("Paragraph 2"));
        assert!(!xml.contains("Paragraph 3"));
    }

    #[test]
    #[ignore]
    fn benchmark_remove_paragraph_range_raw_xml() {
        let data = build_document_docx(&body_paragraphs_xml(512));
        let template = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated docx");
        const ITERS: usize = 80;
        const START: usize = 128;
        const END: usize = 255;

        let mut legacy_elapsed = Duration::ZERO;
        for _ in 0..ITERS {
            let mut doc = template.clone();
            let start = Instant::now();
            for idx in (START..=END).rev() {
                black_box(doc.remove_paragraph_at(idx));
            }
            legacy_elapsed += start.elapsed();
            assert_eq!(black_box(doc.paragraph_count()), 384);
        }

        let mut batched_elapsed = Duration::ZERO;
        for _ in 0..ITERS {
            let mut doc = template.clone();
            let start = Instant::now();
            black_box(doc.remove_paragraph_range_at(START, END));
            batched_elapsed += start.elapsed();
            assert_eq!(black_box(doc.paragraph_count()), 384);
        }

        println!(
            "remove 128/512 paragraphs over {ITERS} iters: legacy={legacy_elapsed:?}, batched={batched_elapsed:?}, speedup={:.2}x",
            legacy_elapsed.as_secs_f64() / batched_elapsed.as_secs_f64()
        );
    }

    fn build_comment_docx() -> Vec<u8> {
        const CONTENT_TYPES: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
  <Override PartName="/word/comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/>
</Types>
"#;

        const RELS: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>
"#;

        const DOCUMENT_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <w:body>
    <w:p>
      <w:r><w:t>Hello</w:t></w:r>
      <w:commentRangeStart w:id="1"/>
      <w:r><w:t>world</w:t></w:r>
      <w:commentRangeEnd w:id="1"/>
      <w:r><w:commentReference w:id="1"/></w:r>
    </w:p>
  </w:body>
</w:document>
"#;

        const DOCUMENT_RELS: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/>
</Relationships>
"#;

        const COMMENTS_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:comments xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <w:comment w:id="1" w:author="Alice">
    <w:p><w:r><w:t>Hello world</w:t></w:r></w:p>
  </w:comment>
</w:comments>
"#;

        let cursor = std::io::Cursor::new(Vec::new());
        let mut zip = zip::ZipWriter::new(cursor);
        let options = SimpleFileOptions::default();

        zip.start_file("[Content_Types].xml", options)
            .expect("content types entry");
        zip.write_all(CONTENT_TYPES.as_bytes())
            .expect("write content types");

        zip.start_file("_rels/.rels", options).expect("rels entry");
        zip.write_all(RELS.as_bytes()).expect("write rels");

        zip.start_file("word/document.xml", options)
            .expect("document entry");
        zip.write_all(DOCUMENT_XML.as_bytes())
            .expect("write document");

        zip.start_file("word/_rels/document.xml.rels", options)
            .expect("doc rels entry");
        zip.write_all(DOCUMENT_RELS.as_bytes())
            .expect("write doc rels");

        zip.start_file("word/comments.xml", options)
            .expect("comments entry");
        zip.write_all(COMMENTS_XML.as_bytes())
            .expect("write comments");

        let cursor = zip.finish().expect("finish zip");
        cursor.into_inner()
    }

    fn build_docx_from_parts(parts: &[(&str, &str)]) -> Vec<u8> {
        let cursor = std::io::Cursor::new(Vec::new());
        let mut zip = zip::ZipWriter::new(cursor);
        let options = SimpleFileOptions::default();
        for (name, content) in parts {
            zip.start_file(*name, options).expect("part entry");
            zip.write_all(content.as_bytes()).expect("write part");
        }
        zip.finish().expect("finish zip").into_inner()
    }

    const SMARTART_DATA_XML: &str = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<dgm:dataModel xmlns:dgm="http://schemas.openxmlformats.org/drawingml/2006/diagram" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><dgm:ptLst/><dgm:cxnLst/><dgm:bg/><dgm:whole/><dgm:extLst><a:ext uri="http://schemas.microsoft.com/office/drawing/2008/diagram"><dsp:dataModelExt xmlns:dsp="http://schemas.microsoft.com/office/drawing/2008/diagram" relId="rId8" minVer="http://schemas.openxmlformats.org/drawingml/2006/diagram"/></a:ext></dgm:extLst></dgm:dataModel>"#;

