    fn build_smartart_docx() -> Vec<u8> {
        build_docx_from_parts(&[
            (
                "[Content_Types].xml",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="xml" ContentType="application/xml"/><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/diagrams/data1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawingml.diagramData+xml"/><Override PartName="/word/diagrams/drawing1.xml" ContentType="application/vnd.ms-office.drawingml.diagramDrawing+xml"/></Types>"#,
            ),
            (
                "_rels/.rels",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>"#,
            ),
            (
                "word/_rels/document.xml.rels",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/diagramData" Target="diagrams/data1.xml"/><Relationship Id="rId8" Type="http://schemas.microsoft.com/office/2007/relationships/diagramDrawing" Target="diagrams/drawing1.xml"/></Relationships>"#,
            ),
            (
                "word/document.xml",
                r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:dgm="http://schemas.openxmlformats.org/drawingml/2006/diagram"><w:body><w:p><w:r><w:t>Before</w:t></w:r></w:p><w:p><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="4114800" cy="1371600"/><wp:docPr id="1" name="Diagram 1"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/diagram"><dgm:relIds r:dm="rId4" r:lo="rId5" r:qs="rId6" r:cs="rId7"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p></w:body></w:document>"#,
            ),
            ("word/diagrams/data1.xml", SMARTART_DATA_XML),
            ("word/diagrams/drawing1.xml", SMARTART_DRAWING_XML),
        ])
    }

    #[test]
    fn smartart_renders_the_cached_drawing_and_round_trips_its_parts() {
        let data = build_smartart_docx();
        let options = Options::default();
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &options)).expect("load SmartArt");
        let image = word_doc
            .paragraph(1)
            .and_then(|paragraph| paragraph.runs.iter().find_map(|run| run.image.as_ref()))
            .expect("SmartArt drawing")
            .clone();
        assert!(image.placeholder_label.is_none(), "{image:?}");
        let group = image.shape_group.as_ref().expect("cached drawing shapes");
        assert_eq!(group.children.len(), 2);
        assert_eq!(group.child_extent_width, 4_114_800.0);
        assert_eq!(group.children[0].text, "Plan");
        assert_eq!(group.children[1].shape, TextBoxShape::Ellipse);
        let style = group.children[0].text_style.as_ref().expect("text style");
        assert_eq!(style.color.as_deref(), Some("#FFFFFF"));
        assert_eq!(style.font_size_pt, Some(24.0));

        crate::headless_api::apply_headless_commands_to_document(
            &mut word_doc,
            &jade_docx_headless_api::HeadlessEditRequest {
                commands: vec![jade_docx_headless_api::HeadlessCommand::InsertText {
                    paragraph: 0,
                    offset: 6,
                    text: " edit".to_string(),
                }],
            },
        )
        .expect("edit body");
        let exported = word_doc.export_docx().expect("export SmartArt");
        let mut archive = ZipArchive::new(std::io::Cursor::new(exported)).expect("exported zip");
        let mut read = |name: &str| {
            let mut content = String::new();
            archive
                .by_name(name)
                .expect("exported part")
                .read_to_string(&mut content)
                .expect("read part");
            content
        };
        assert_eq!(read("word/diagrams/drawing1.xml"), SMARTART_DRAWING_XML);
        assert_eq!(read("word/diagrams/data1.xml"), SMARTART_DATA_XML);
        let document = read("word/document.xml");
        assert!(
            document.contains(r#"<dgm:relIds r:dm="rId4""#),
            "{document}"
        );
        assert!(document.contains("Before edit"));
        assert!(
            !document.contains("wpg:wgp"),
            "SmartArt must not become a group"
        );
    }

    fn object_docx(body: &str, rels: &str, extra: &[(&str, &str)]) -> Vec<u8> {
        let document = format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office"><w:body>{body}</w:body></w:document>"#
        );
        let rels = format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">{rels}</Relationships>"#
        );
        let mut parts = vec![
            (
                "[Content_Types].xml",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Default Extension="bin" ContentType="application/vnd.openxmlformats-officedocument.oleObject"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>"#,
            ),
            (
                "_rels/.rels",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>"#,
            ),
            ("word/document.xml", document.as_str()),
            ("word/_rels/document.xml.rels", rels.as_str()),
        ];
        parts.extend_from_slice(extra);
        build_docx_from_parts(&parts)
    }

    fn first_image(word_doc: &WordDocument) -> RunImage {
        word_doc
            .paragraph(0)
            .and_then(|paragraph| paragraph.runs.iter().find_map(|run| run.image.clone()))
            .expect("object image")
    }

    #[test]
    fn existing_charts_draw_a_preview_or_a_placeholder_never_nothing() {
        const CHART_REL: &str = r#"<Relationship Id="rIdC" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="charts/chart1.xml"/>"#;
        let body = r#"<w:p><w:r><w:drawing><wp:inline><wp:extent cx="3657600" cy="2194560"/><wp:docPr id="5" name="Chart 1"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart r:id="rIdC"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>"#;
        let chart = |plot: &str| {
            format!(
                r#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:plotArea><c:{plot}><c:ser><c:cat><c:strLit><c:ptCount val="1"/><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat><c:val><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>7</c:v></c:pt></c:numLit></c:val></c:ser></c:{plot}></c:plotArea></c:chart></c:chartSpace>"#
            )
        };
        let options = Options::default();
        for (plot, previewed) in [
            ("barChart", true),
            ("doughnutChart", true),
            ("bubbleChart", false),
        ] {
            let xml = chart(plot);
            let data = object_docx(body, CHART_REL, &[("word/charts/chart1.xml", &xml)]);
            let word_doc = executor::block_on(WordDocument::load(&data, &options)).expect(plot);
            let image = first_image(&word_doc);
            assert_eq!(
                image
                    .data_uri
                    .as_deref()
                    .is_some_and(|uri| uri.starts_with("data:image/png;base64,")),
                previewed,
                "{plot}"
            );
            assert_eq!(
                image.placeholder_label.is_some(),
                !previewed,
                "{plot}: an unpreviewable chart is labelled"
            );
        }
        // A chart whose part is missing is labelled too.
        let data = object_docx(body, CHART_REL, &[]);
        let word_doc = executor::block_on(WordDocument::load(&data, &options)).expect("missing");
        assert_eq!(
            first_image(&word_doc).placeholder_label.as_deref(),
            Some("Chart")
        );
    }

    /// Word-authored WordArt is a `wps:wsp` text box: its shape effects and
    /// the run's `w:color` render, while the text warp (`a:prstTxWarp`) and
    /// the `w14` text effects are kept verbatim for Word (not drawn yet).
    #[test]
    fn existing_word_art_renders_as_an_effected_text_box_and_round_trips() {
        let body = r#"<w:p><w:r><w:t>Host</w:t></w:r><w:r><w:drawing><wp:anchor distT="0" distB="0" distL="114300" distR="114300" simplePos="0" relativeHeight="1" behindDoc="0" locked="0" layoutInCell="1" allowOverlap="1"><wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="column"><wp:posOffset>0</wp:posOffset></wp:positionH><wp:positionV relativeFrom="paragraph"><wp:posOffset>0</wp:posOffset></wp:positionV><wp:extent cx="2743200" cy="914400"/><wp:wrapNone/><wp:docPr id="3" name="WordArt 1"/><a:graphic><a:graphicData uri="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"><wps:wsp xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"><wps:cNvSpPr txBox="1"/><wps:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="2743200" cy="914400"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/><a:ln><a:noFill/></a:ln><a:effectLst><a:outerShdw blurRad="38100" dist="38100" dir="2700000" algn="tl"><a:srgbClr val="000000"><a:alpha val="40000"/></a:srgbClr></a:outerShdw></a:effectLst></wps:spPr><wps:txbx><w:txbxContent><w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/><w:color w:val="ED7D31"/><w:sz w:val="72"/><w14:textOutline xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" w14:w="9525" w14:cap="flat" w14:cmpd="sng" w14:algn="ctr"><w14:solidFill><w14:srgbClr w14:val="FFFFFF"/></w14:solidFill><w14:prstDash w14:val="solid"/><w14:round/></w14:textOutline></w:rPr><w:t>WordArt</w:t></w:r></w:p></w:txbxContent></wps:txbx><wps:bodyPr wrap="none"><a:prstTxWarp prst="textArchUp"><a:avLst/></a:prstTxWarp><a:spAutoFit/></wps:bodyPr></wps:wsp></a:graphicData></a:graphic></wp:anchor></w:drawing></w:r></w:p>"#;
        let data = object_docx(body, "", &[]);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("WordArt");
        let text_box = word_doc
            .paragraph(0)
            .and_then(|paragraph| paragraph.runs.iter().find_map(|run| run.text_box.clone()))
            .expect("WordArt shape");
        assert!(text_box.shadow.is_some(), "effectLst shadow renders");
        assert!(text_box.fill_color.is_none());
        let paragraph = text_box.blocks[0].as_paragraph().expect("WordArt text");
        let run = &paragraph.runs[0];
        assert_eq!(run.text, "WordArt");
        let properties = run.properties.as_ref().expect("run properties");
        assert_eq!(properties.color.as_deref(), Some("#ED7D31"));
        assert_eq!(properties.font_size, Some(36.0));

        crate::headless_api::apply_headless_commands_to_document(
            &mut word_doc,
            &jade_docx_headless_api::HeadlessEditRequest {
                commands: vec![jade_docx_headless_api::HeadlessCommand::InsertText {
                    paragraph: 0,
                    offset: 4,
                    text: "!".to_string(),
                }],
            },
        )
        .expect("edit host");
        let document = exported_document_xml(&word_doc);
        assert!(
            document.contains(r#"<a:prstTxWarp prst="textArchUp">"#),
            "{document}"
        );
        assert!(document.contains("w14:textOutline"), "{document}");
        assert!(document.contains("<a:outerShdw"), "{document}");
    }

    #[test]
    fn ole_objects_draw_their_cached_png_preview() {
        let body = r##"<w:p><w:r><w:object w:dxaOrig="1440" w:dyaOrig="720"><v:shape id="_x0000_i1025" type="#_x0000_t75" style="width:72pt;height:36pt"><v:imagedata r:id="rIdP" o:title=""/></v:shape><o:OLEObject Type="Embed" ProgID="Package" ShapeID="_x0000_i1025" DrawAspect="Content" ObjectID="_1" r:id="rIdO"/></w:object></w:r></w:p>"##;
        let rels = r#"<Relationship Id="rIdP" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image1.png"/><Relationship Id="rIdO" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/oleObject" Target="embeddings/oleObject1.bin"/>"#;
        let data = object_docx(
            body,
            rels,
            &[
                ("word/media/image1.png", "\u{89}PNG-preview"),
                ("word/embeddings/oleObject1.bin", "ole"),
            ],
        );
        let word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("OLE");
        let image = first_image(&word_doc);
        assert_eq!(image.ole_program_id.as_deref(), Some("Package"));
        assert_eq!(image.ole_relationship_id.as_deref(), Some("rIdO"));
        // The renderer draws `data_uri` ahead of the placeholder label.
        assert!(image
            .data_uri
            .as_deref()
            .is_some_and(|uri| uri.starts_with("data:image/png;base64,")));
        assert_eq!(image.width_px, Some(96.0));
        assert_eq!(image.height_px, Some(48.0));
    }

