    fn build_doc_grid_mode_docx(grid_type: &str, char_space: Option<i32>) -> Vec<u8> {
        const CONTENT_TYPES: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
</Types>
"#;

        const RELS: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>
"#;

        let doc_grid_attrs = if let Some(char_space) = char_space {
            format!(r#"w:type="{grid_type}" w:linePitch="640" w:charSpace="{char_space}""#)
        } else {
            format!(r#"w:type="{grid_type}" w:linePitch="640""#)
        };

        let document_xml = format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:r><w:t>Grid Mode</w:t></w:r>
    </w:p>
    <w:sectPr>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/>
      <w:docGrid {doc_grid_attrs}/>
    </w:sectPr>
  </w:body>
</w:document>
"#
        );

        let cursor = std::io::Cursor::new(Vec::new());
        let mut zip = zip::ZipWriter::new(cursor);
        let options = SimpleFileOptions::default();

        zip.start_file("[Content_Types].xml", options)
            .expect("content types entry");
        zip.write_all(CONTENT_TYPES.as_bytes())
            .expect("write content types");

        zip.start_file("_rels/.rels", options).expect("rels entry");
        zip.write_all(RELS.as_bytes()).expect("write rels");

        zip.start_file("word/document.xml", options)
            .expect("document entry");
        zip.write_all(document_xml.as_bytes())
            .expect("write document");

        let cursor = zip.finish().expect("finish zip");
        cursor.into_inner()
    }

