    /// What the editor's load boundary does with the parsed part
    /// (`canvas_view::install_document_font_substitutes`); inlined here so the
    /// shared document core, which has no view layer, compiles this test too.
    fn install_font_substitutes(doc: &WordDocument) {
        jade_docx_layout::font_resolver::set_document_font_alt_names(
            doc.font_table_part
                .as_ref()
                .map(|table| {
                    table
                        .alt_names()
                        .map(|(name, alt)| (name.to_string(), vec![alt.to_string()]))
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default(),
        );
    }

    #[test]
    fn font_table_alt_names_extend_resolution_and_reset_on_next_load() {
        let data = build_font_table_docx();
        let options = Options::default();
        let doc =
            executor::block_on(WordDocument::load(&data, &options)).expect("load fontTable docx");
        install_font_substitutes(&doc);

        let props = RunProperties {
            fonts: Some(RunFonts {
                ascii: Some("HGP創英角ﾎﾟｯﾌﾟ体".into()),
                ..RunFonts::default()
            }),
            ..RunProperties::default()
        };
        let resolved = jade_docx_layout::font_resolver::resolve_font_families(Some(&props));
        assert!(
            resolved.latin_ascii_stack().contains("HGPSoeiKakupoptai"),
            "the fontTable substitute must join the resolved stack: {}",
            resolved.latin_ascii_stack()
        );

        // Loading a document WITHOUT a usable fontTable clears the registry;
        // the previous document's substitutes must not leak into it.
        let plain = build_theme_font_fallback_docx();
        let doc =
            executor::block_on(WordDocument::load(&plain, &options)).expect("load plain docx");
        install_font_substitutes(&doc);
        let resolved = jade_docx_layout::font_resolver::resolve_font_families(Some(&props));
        assert!(
            !resolved.latin_ascii_stack().contains("HGPSoeiKakupoptai"),
            "a new load must reset the substitutes: {}",
            resolved.latin_ascii_stack()
        );
    }

