    #[test]
    fn extract_empty_header_footer_lines_preserves_paragraph_alignment() {
        for (alignment, expected) in [
            ("left", (None, None)),
            ("center", (Some(""), None)),
            ("right", (None, Some(""))),
            ("end", (None, Some(""))),
        ] {
            for text in ["", "\t", "\t\t"] {
                let mut paragraph = make_paragraph(text);
                paragraph.properties = Some(crate::document::ParagraphProperties {
                    alignment: Some(alignment.into()),
                    ..Default::default()
                });
                let body = Body {
                    elements: vec![BodyElement::from_paragraph(paragraph)],
                };
                let lines = WordDocument::extract_text_lines_from_body(&body, true);
                assert_eq!(lines.len(), 1);
                assert!(lines[0].left.is_none());
                let expected = if text.is_empty() {
                    expected
                } else {
                    // Empty tab segments must not become ordinary aligned text.
                    (None, None)
                };
                assert_eq!(
                    (lines[0].center.as_deref(), lines[0].right.as_deref()),
                    expected,
                    "alignment {alignment}, text {text:?}"
                );
                assert!(WordDocument::extract_text_lines(&body).is_empty());
            }
        }
    }

