    #[test]
    fn legacy_page_number_block_keeps_prefix_before_page_placeholder() {
        // `w:pgNum` is allowed after literal text in the same run. Package
        // header/footer extraction must retain that inline order; emitting the
        // field before run.text changes "Page: 1" into "1 Page:".
        let xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:r><w:t xml:space="preserve">Page: </w:t><w:pgNum/></w:r></w:p>
  </w:body>
</w:document>"#;
        let document = DocumentParser::new()
            .parse_document_xml(xml)
            .expect("parse legacy page-number block");
        let body = document.body.as_ref().expect("body");

        let lines = WordDocument::extract_text_lines(body);
        assert_eq!(lines.len(), 1);
        let expected = format!("Page: {}", crate::document::PAGE_FIELD_PLACEHOLDER);
        assert_eq!(lines[0].left.as_deref(), Some(expected.as_str()));
    }

