    #[test]
    fn load_generated_fixture_keeps_header_blocks_for_rich_layout() {
        // Header/footer editing still exposes flattened HeaderLine values, but
        // rendering must retain the original story body. Otherwise a table is
        // indistinguishable from three aligned strings and loses its cell
        // widths, borders, shading, nested paragraphs, images, and wrapping.
        let data = std::fs::read(fixture_path("header-footer-edge-cases.docx"))
            .expect("read generated header/footer fixture");
        let doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated header/footer fixture");

        let header = doc
            .header_footer_body(HeaderFooterRole::Header, HeaderFooterVariant::Default)
            .expect("parsed default header body");
        assert!(
            header
                .elements
                .iter()
                .any(|element| matches!(element, BodyElement::Table(_))),
            "header table must survive as a block for the shared body renderer",
        );
        fn elements_have_resolved_image(elements: &[BodyElement]) -> bool {
            elements.iter().any(|element| match element {
                BodyElement::Paragraph(paragraph) => paragraph.runs.iter().any(|run| {
                    run.image.as_ref().is_some_and(|image| {
                        image
                            .data_uri
                            .as_deref()
                            .is_some_and(|uri| uri.starts_with("data:image/png;base64,"))
                    })
                }),
                BodyElement::Table(table) => table.rows.iter().any(|row| {
                    row.cells
                        .iter()
                        .any(|cell| elements_have_resolved_image(&cell.blocks))
                }),
                BodyElement::Math(_) => false,
            })
        }
        let has_resolved_image = elements_have_resolved_image(&header.elements);
        assert!(has_resolved_image, "header image relationship must resolve");

        let footer = doc
            .header_footer_body(HeaderFooterRole::Footer, HeaderFooterVariant::Default)
            .expect("parsed default footer body");
        assert!(
            footer
                .elements
                .iter()
                .any(|element| matches!(element, BodyElement::Table(_))),
            "footer table must survive as a block for bottom-up placement",
        );
        let settings = doc
            .document
            .as_deref()
            .and_then(|document| document.page_settings.as_ref())
            .expect("page settings");
        assert_eq!(settings.header_distance, Some(21.6));
        assert_eq!(settings.footer_distance, Some(21.6));
    }

    fn hf_text(lines: &Option<Vec<HeaderLine>>) -> String {
        lines
            .as_ref()
            .map(|lines| {
                lines
                    .iter()
                    .flat_map(|line| {
                        [
                            line.left.as_deref(),
                            line.center.as_deref(),
                            line.right.as_deref(),
                        ]
                    })
                    .flatten()
                    .collect::<Vec<_>>()
                    .join("|")
            })
            .unwrap_or_default()
    }

    /// Creating a missing footer while editing a page of a sectioned document
    /// registers the new part document-wide; the section-scoped edit path
    /// must still find it instead of reporting "no footer reference".
    #[test]
    fn creating_a_missing_footer_resolves_through_the_editing_section() {
        let data = std::fs::read(fixture_path("contract.docx")).expect("read contract fixture");
        let mut doc = futures::executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load contract fixture");
        assert!(
            !doc.document.as_ref().expect("document").sections.is_empty(),
            "fixture must carry section ranges"
        );
        assert!(
            doc.footer_lines.is_none(),
            "fixture must start without a footer"
        );
        doc.hf_edit_section = Some(0);
        doc.ensure_hf_part_for_edit(HeaderFooterRole::Footer, HeaderFooterVariant::Default)
            .expect("create the missing footer part");
        let path = doc
            .resolve_header_footer_part_path_for(
                HeaderFooterRole::Footer,
                HeaderFooterVariant::Default,
            )
            .expect("the new footer resolves through the editing section");
        assert!(path.ends_with(".xml"));
        assert!(
            doc.section_header_footers()[0].footer.is_some(),
            "the created footer renders on the edited section"
        );
    }

    /// Word resolves headers per section: a section without a reference of
    /// a given type is "linked to previous" and shows the previous section's
    /// story, while `w:titlePg` applies to the first page of its own section.
    #[test]
    fn section_header_footers_follow_word_link_to_previous() {
        let data = std::fs::read(fixture_path("header-footer-sections.docx"))
            .expect("read two-section fixture");
        let doc = futures::executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load two-section fixture");
        let sections = doc.section_header_footers();
        assert_eq!(sections.len(), 2, "one section per sectPr");

        assert!(hf_text(&sections[0].header).contains("SECTION ONE HEADER"));
        assert!(hf_text(&sections[0].header_first).contains("TITLE PAGE HEADER"));
        assert!(hf_text(&sections[0].footer).contains("SHARED FOOTER"));
        assert!(sections[0].title_page, "section 1 declares w:titlePg");

        // Section 2 references only a default header: its footer and its
        // first-page header are inherited from section 1, and it does not
        // start with a title page of its own.
        assert!(hf_text(&sections[1].header).contains("SECTION TWO HEADER"));
        assert!(hf_text(&sections[1].footer).contains("SHARED FOOTER"));
        assert!(hf_text(&sections[1].header_first).contains("TITLE PAGE HEADER"));
        assert!(!sections[1].title_page);
        assert!(sections[1].header_body.is_some(), "rich story resolved");
        assert!(
            sections[1].footer_body.is_some(),
            "inherited rich story resolved"
        );
    }

    /// Enter (or any split) in the last paragraph of a section leaves the
    /// section break on the paragraph mark that ended the paragraph — the
    /// tail. The head used to keep a copy too, so every Enter there added a
    /// section.
    #[test]
    fn splitting_a_section_terminator_keeps_a_single_section_break() {
        let data = std::fs::read(fixture_path("hello.docx")).expect("read hello fixture");
        let mut doc = futures::executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load hello fixture");
        let hello_len: usize = doc
            .paragraph(0)
            .expect("paragraph 0")
            .runs
            .iter()
            .map(|run| run.text.len())
            .sum();
        doc.insert_section_break_at(0, hello_len, SectionBreakType::NextPage)
            .expect("section break after Hello");
        assert_eq!(doc.document.as_ref().expect("document").sections.len(), 2);

        assert!(doc.split_paragraph_at(0, 3), "split Hel|lo");
        assert_eq!(
            doc.document.as_ref().expect("document").sections.len(),
            2,
            "the split adds no section"
        );
        let has_section = |index: usize| {
            doc.paragraph(index)
                .and_then(|paragraph| paragraph.properties.as_ref())
                .and_then(|props| props.section.as_ref())
                .is_some()
        };
        assert!(!has_section(0), "the head lost the section break");
        assert!(has_section(1), "the tail carries the section break");
        let xml = exported_document_xml(&doc);
        assert_eq!(
            xml.matches("<w:sectPr").count(),
            2,
            "one paragraph sectPr plus the body sectPr: {xml}"
        );
    }

    /// Typing into a header of a document whose sections own several header
    /// parts must land in the part of the edited page's section and variant,
    /// and survive the export.
    #[test]
    fn header_edit_in_a_multi_part_document_reaches_the_edited_part() {
        let data = std::fs::read(fixture_path("header-footer-sections.docx"))
            .expect("read two-section fixture");
        let mut doc = futures::executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load two-section fixture");

        // Page 1 is section 1's title page: its header is the `first` variant.
        // The document-wide fields describe the final section (no first-page
        // header, header2.xml as default), so the editor must read the
        // section's own story.
        assert!(doc.header_lines_first.is_none());
        assert!(hf_text(&doc.header_lines).contains("SECTION TWO HEADER"));
        doc.hf_edit_section = Some(0);
        assert!(hf_text(
            &doc.hf_lines_for_edit(HeaderFooterRole::Header, HeaderFooterVariant::First)
        )
        .contains("TITLE PAGE HEADER"));
        assert!(hf_text(
            &doc.hf_lines_for_edit(HeaderFooterRole::Header, HeaderFooterVariant::Default)
        )
        .contains("SECTION ONE HEADER"));
        doc.hf_edit_section = Some(1);
        assert!(
            hf_text(&doc.hf_lines_for_edit(HeaderFooterRole::Footer, HeaderFooterVariant::Default))
                .contains("SHARED FOOTER"),
            "section 2 inherits section 1's footer"
        );
        doc.hf_edit_section = Some(0);
        doc.ensure_hf_part_for_edit(HeaderFooterRole::Header, HeaderFooterVariant::First)
            .expect("first-page header exists");
        doc.replace_header_first_paragraph_text(0, "TITLE PAGE HEADER edited")
            .expect("edit the first-page header");
        let header3 = exported_part_xml(&doc, "word/header3.xml");
        assert!(
            header3.contains("TITLE PAGE HEADER edited"),
            "first-page header text must be written to header3.xml, got {header3}"
        );

        // Page 2 belongs to section 2, whose default header is header2.xml.
        doc.hf_edit_section = Some(1);
        doc.ensure_hf_part_for_edit(HeaderFooterRole::Header, HeaderFooterVariant::Default)
            .expect("section 2 header exists");
        doc.replace_header_paragraph_text(0, "SECTION TWO HEADER edited")
            .expect("edit section 2's header");
        let header2 = exported_part_xml(&doc, "word/header2.xml");
        assert!(
            header2.contains("SECTION TWO HEADER edited"),
            "section 2 header text must be written to header2.xml, got {header2}"
        );
        let header1 = exported_part_xml(&doc, "word/header1.xml");
        assert!(
            header1.contains("SECTION ONE HEADER") && !header1.contains("edited"),
            "section 1's header is untouched, got {header1}"
        );

        // Editing section 1's own default header must not overwrite the
        // document-wide lines, which render the final section's header.
        doc.hf_edit_section = Some(0);
        doc.replace_header_paragraph_text(0, "SECTION ONE HEADER edited")
            .expect("edit section 1's header");
        assert!(exported_part_xml(&doc, "word/header1.xml").contains("SECTION ONE HEADER edited"));
        assert!(
            hf_text(&doc.header_lines).contains("SECTION TWO HEADER edited"),
            "document-wide header lines still describe the final section"
        );
        assert!(
            hf_text(&doc.section_header_footers()[0].header).contains("SECTION ONE HEADER edited")
        );
        assert!(
            hf_text(&doc.section_header_footers()[1].header).contains("SECTION TWO HEADER edited"),
            "the rendered section 2 header follows the edit"
        );
    }

    #[test]
    fn load_generated_sectionpages_footer_uses_a_live_section_placeholder() {
        let data = std::fs::read(fixture_path("header-footer-sectionpages.docx"))
            .expect("read generated SECTIONPAGES fixture");
        let doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated SECTIONPAGES fixture");
        let footer = doc.footer_lines.expect("footer lines");
        let flattened = footer
            .iter()
            .flat_map(|line| [&line.left, &line.center, &line.right])
            .filter_map(|segment| segment.as_deref())
            .collect::<String>();

        // Header/footer extraction must retain semantic placeholders rather
        // than Word's cached `1`, otherwise changing section pagination
        // would leave a stale footer or duplicate the cached field result.
        assert!(flattened.contains(crate::document::PAGE_FIELD_PLACEHOLDER));
        assert!(flattened.contains(crate::document::SECTION_PAGE_COUNT_FIELD_PLACEHOLDER));
        assert!(!flattened.contains("{SECTIONPAGES}1"));
    }

    #[test]
    fn load_generated_docproperty_fields_prefers_package_metadata_over_cached_results() {
        let data = std::fs::read(fixture_path("document-property-fields.docx"))
            .expect("read generated DOCPROPERTY fixture");
        let doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated DOCPROPERTY fixture");
        let parsed = doc.document.as_ref().expect("parsed document");
        let body_field = parsed
            .body
            .as_ref()
            .into_iter()
            .flat_map(|body| &body.elements)
            .filter_map(BodyElement::as_paragraph)
            .flat_map(|paragraph| &paragraph.runs)
            .filter_map(|run| run.field.as_ref())
            .find(|field| {
                matches!(
                    &field.kind,
                    RunFieldKind::DocumentProperty { name, .. }
                        if name.eq_ignore_ascii_case("Title")
                )
            })
            .expect("body Title property field");

        assert_eq!(body_field.cached_text.as_deref(), Some("Stale Body Title"));
        assert_eq!(
            body_field.resolved_value.as_deref(),
            Some("Live Package Title")
        );

        let flatten_lines = |lines: &Option<Vec<HeaderLine>>| {
            lines
                .as_ref()
                .into_iter()
                .flatten()
                .flat_map(|line| [&line.left, &line.center, &line.right])
                .filter_map(|segment| segment.as_deref())
                .collect::<String>()
        };
        let header = flatten_lines(&doc.header_lines);
        let footer = flatten_lines(&doc.footer_lines);
        assert!(header.contains("Title: Live Package Title"));
        assert!(!header.contains("Stale Header Title"));
        assert!(header.contains("Company: Analytical Engines & Co."));
        assert!(!header.contains("Stale Header Company"));
        assert!(footer.contains("Author: Ada Lovelace"));
        assert!(!footer.contains("Stale Footer Author"));

        let manager_field = parsed
            .body
            .as_ref()
            .into_iter()
            .flat_map(|body| &body.elements)
            .filter_map(BodyElement::as_paragraph)
            .flat_map(|paragraph| &paragraph.runs)
            .filter_map(|run| run.field.as_ref())
            .find(|field| {
                matches!(
                    &field.kind,
                    RunFieldKind::DocumentProperty { name, .. }
                        if name.eq_ignore_ascii_case("Manager")
                )
            })
            .expect("body Manager property field");
        assert_eq!(
            manager_field.cached_text.as_deref(),
            Some("Stale Body Manager")
        );
        assert_eq!(
            manager_field.resolved_value.as_deref(),
            Some("Grace Hopper")
        );
    }

    #[test]
    fn document_property_fields_apply_word_capitalization_switches() {
        // Property metadata is authoritative, but Word applies general case
        // switches after reading it. Cover a quoted custom property name and a
        // built-in field so both parser paths share the same resolver contract.
        let mut parsed = DocumentParser::new()
            .parse_document_xml(
                r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>
                  <w:p><w:fldSimple w:instr=' DOCPROPERTY "Document Title" \*Upper '><w:r><w:t>STALE</w:t></w:r></w:fldSimple></w:p>
                  <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> COMM</w:instrText></w:r><w:r><w:instrText>ENTS \* First</w:instrText></w:r><w:r><w:instrText>Cap </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>stale</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
                </w:body></w:document>"#,
            )
            .expect("parse property case fields");
        WordDocument::resolve_package_value_fields(
            &mut parsed,
            &HashMap::from([
                ("document title".to_string(), "Quarterly Report".to_string()),
                ("comments".to_string(), "weekly REPORT".to_string()),
            ]),
            &HashMap::new(),
            None,
        );
        let values = parsed
            .body
            .as_ref()
            .expect("body")
            .elements
            .iter()
            .filter_map(BodyElement::as_paragraph)
            .filter_map(|paragraph| paragraph.runs.iter().find_map(|run| run.field.as_ref()))
            .map(|field| field.resolved_value.as_deref())
            .collect::<Vec<_>>();
        assert_eq!(values, [Some("QUARTERLY REPORT"), Some("Weekly REPORT")]);
    }

    #[test]
    fn numwords_and_numchars_prefer_extended_properties_over_stale_results() {
        // Cached field text can lag behind the statistics saved in
        // docProps/app.xml. Resolve the semantic field only after all package
        // properties are available, while retaining the cache as a fallback
        // for malformed/minimal packages that omit those properties.
        let statistics_run = |kind, cached: &str| Run {
            text: String::new(),
            properties: None,
            image: None,
            text_box: None,
            math: None,
            field: Some(RunField {
                word_mac_body_result: None,
                kind,
                cached_text: Some(cached.to_string()),
                source_field_id: None,
                resolved_value: None,
            }),
            hyperlink: None,
            node_id: None,
            text_node_id: None,
            revision_node_id: None,
            comment_reference_ids: Vec::new(),
            footnote_reference_ids: Vec::new(),
            endnote_reference_ids: Vec::new(),
            note_separator: None,
            has_footnote_ref: false,
            has_endnote_ref: false,
            revision: None,
        };
        let mut document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(Paragraph {
                    runs: vec![
                        statistics_run(RunFieldKind::NumWords, "999"),
                        statistics_run(RunFieldKind::NumChars, "888"),
                    ],
                    properties: None,
                    node_id: None,
                    comment_ranges: Vec::new(),
                    comment_markers: Vec::new(),
                })],
            }),
            ..Document::default()
        };
        let properties = HashMap::from([
            ("words".to_string(), "17".to_string()),
            ("characters".to_string(), "91".to_string()),
        ]);

        WordDocument::resolve_package_value_fields(
            &mut document,
            &properties,
            &HashMap::new(),
            None,
        );

        // Keep both values: rendering prefers resolved_value, but export can
        // still preserve Word's original result run until field refresh is
        // implemented as a write-time operation.
        let fields = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .expect("statistics paragraph")
            .runs
            .iter()
            .filter_map(|run| run.field.as_ref())
            .collect::<Vec<_>>();
        assert_eq!(fields[0].cached_text.as_deref(), Some("999"));
        assert_eq!(fields[0].resolved_value.as_deref(), Some("17"));
        assert_eq!(fields[1].cached_text.as_deref(), Some("888"));
        assert_eq!(fields[1].resolved_value.as_deref(), Some("91"));
    }

    #[test]
    fn edittime_prefers_total_time_over_a_stale_saved_result() {
        // Word stores EDITTIME's live value in docProps/app.xml as TotalTime,
        // measured in minutes. The cached field result can be older than that
        // package metadata, so rendering must use resolved_value without
        // discarding cached_text (which remains useful for malformed packages).
        let mut document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(Paragraph {
                    runs: vec![Run {
                        text: String::new(),
                        properties: None,
                        image: None,
                        text_box: None,
                        math: None,
                        field: Some(RunField {
                            word_mac_body_result: None,
                            kind: RunFieldKind::EditTime,
                            cached_text: Some("999".to_string()),
                            source_field_id: None,
                            resolved_value: None,
                        }),
                        hyperlink: None,
                        node_id: None,
                        text_node_id: None,
                        revision_node_id: None,
                        comment_reference_ids: Vec::new(),
                        footnote_reference_ids: Vec::new(),
                        endnote_reference_ids: Vec::new(),
                        note_separator: None,
                        has_footnote_ref: false,
                        has_endnote_ref: false,
                        revision: None,
                    }],
                    properties: None,
                    node_id: None,
                    comment_ranges: Vec::new(),
                    comment_markers: Vec::new(),
                })],
            }),
            ..Document::default()
        };
        let properties = HashMap::from([("totaltime".to_string(), "37".to_string())]);

        WordDocument::resolve_package_value_fields(
            &mut document,
            &properties,
            &HashMap::new(),
            None,
        );

        let field = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .and_then(|paragraph| paragraph.runs.first())
            .and_then(|run| run.field.as_ref())
            .expect("EDITTIME field");
        assert_eq!(field.cached_text.as_deref(), Some("999"));
        assert_eq!(field.resolved_value.as_deref(), Some("37"));

        // Office does not write negative TotalTime values. If a third-party
        // producer does, do not expose it as a live Word field result; keeping
        // resolved_value empty lets the renderer use the saved result instead.
        let invalid_properties = HashMap::from([("totaltime".to_string(), "-1".to_string())]);
        WordDocument::resolve_package_value_fields(
            &mut document,
            &invalid_properties,
            &HashMap::new(),
            None,
        );
        let field = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .and_then(|paragraph| paragraph.runs.first())
            .and_then(|run| run.field.as_ref())
            .expect("EDITTIME field after invalid metadata");
        assert_eq!(field.resolved_value, None);
    }

    #[test]
    fn filesize_resolves_original_package_bytes_and_decimal_units() {
        // Microsoft documents FILESIZE's default as raw bytes and its \k/\m
        // switches as decimal units rounded to the nearest whole number. Use
        // the published 2,084,228-byte example to guard both the 1000-based
        // divisor and rounding behavior (binary KiB/MiB would disagree).
        let field_run = |unit| Run {
            text: String::new(),
            properties: None,
            image: None,
            text_box: None,
            math: None,
            field: Some(RunField {
                word_mac_body_result: None,
                kind: RunFieldKind::FileSize { unit },
                cached_text: Some("stale".to_string()),
                source_field_id: None,
                resolved_value: None,
            }),
            hyperlink: None,
            node_id: None,
            text_node_id: None,
            revision_node_id: None,
            comment_reference_ids: Vec::new(),
            footnote_reference_ids: Vec::new(),
            endnote_reference_ids: Vec::new(),
            note_separator: None,
            has_footnote_ref: false,
            has_endnote_ref: false,
            revision: None,
        };
        let mut document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(Paragraph {
                    runs: vec![
                        field_run(crate::document::FileSizeUnit::Bytes),
                        field_run(crate::document::FileSizeUnit::Kilobytes),
                        field_run(crate::document::FileSizeUnit::Megabytes),
                    ],
                    properties: None,
                    node_id: None,
                    comment_ranges: Vec::new(),
                    comment_markers: Vec::new(),
                })],
            }),
            ..Document::default()
        };

        WordDocument::resolve_package_value_fields(
            &mut document,
            &HashMap::new(),
            &HashMap::new(),
            Some(2_084_228),
        );

        let values = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .expect("FILESIZE paragraph")
            .runs
            .iter()
            .map(|run| {
                run.field
                    .as_ref()
                    .and_then(|field| field.resolved_value.as_deref())
                    .expect("resolved FILESIZE")
            })
            .collect::<Vec<_>>();
        assert_eq!(values, ["2084228", "2084", "2"]);

        // Synthetic/incomplete packages may not have source ZIP length. Do
        // not replace Word's usable saved result with an invented zero.
        WordDocument::resolve_package_value_fields(
            &mut document,
            &HashMap::new(),
            &HashMap::new(),
            None,
        );
        let fields = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .expect("FILESIZE fallback paragraph")
            .runs
            .iter()
            .filter_map(|run| run.field.as_ref())
            .collect::<Vec<_>>();
        assert!(fields.iter().all(|field| field.resolved_value.is_none()));
        assert!(fields
            .iter()
            .all(|field| field.cached_text.as_deref() == Some("stale")));
    }

    #[test]
    fn document_date_prefers_core_timestamp_over_stale_result() {
        let mut parsed = DocumentParser::new()
            .parse_document_xml(
                r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:fldSimple w:instr=' CREATEDATE \@ "yyyy-MM-dd HH:mm:ss" '><w:r><w:t>stale</w:t></w:r></w:fldSimple></w:p></w:body></w:document>"#,
            )
            .expect("parse CREATEDATE document");
        WordDocument::resolve_package_value_fields(
            &mut parsed,
            &HashMap::from([("created".to_string(), "2024-01-02T03:04:05Z".to_string())]),
            &HashMap::new(),
            None,
        );
        let field = parsed
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .and_then(|paragraph| paragraph.runs.iter().find_map(|run| run.field.as_ref()))
            .expect("CREATEDATE field");
        assert_eq!(field.cached_text.as_deref(), Some("stale"));
        assert_eq!(field.resolved_value.as_deref(), Some("2024-01-02 03:04:05"));

        WordDocument::resolve_package_value_fields(
            &mut parsed,
            &HashMap::from([(
                "created".to_string(),
                "2024-01-02T03:04:05+09:00".to_string(),
            )]),
            &HashMap::new(),
            None,
        );
        let offset_value = parsed
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(BodyElement::as_paragraph)
            .and_then(|paragraph| paragraph.runs.iter().find_map(|run| run.field.as_ref()))
            .and_then(|field| field.resolved_value.as_deref());
        assert_eq!(offset_value, Some("2024-01-01 18:04:05"));
    }

    #[test]
    fn load_generated_docvariable_fields_prefers_settings_values_in_every_story() {
        let data = std::fs::read(fixture_path("document-variable-fields.docx"))
            .expect("read generated DOCVARIABLE fixture");
        let mut doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated DOCVARIABLE fixture");
        let parsed = doc.document.as_ref().expect("parsed document");
        let body_field = parsed
            .body
            .as_ref()
            .into_iter()
            .flat_map(|body| &body.elements)
            .filter_map(BodyElement::as_paragraph)
            .flat_map(|paragraph| &paragraph.runs)
            .filter_map(|run| run.field.as_ref())
            .find(|field| {
                matches!(
                    &field.kind,
                    RunFieldKind::DocumentVariable { name, .. }
                        if name.eq_ignore_ascii_case("Release Channel")
                )
            })
            .expect("body Release Channel variable field");

        assert_eq!(
            body_field.cached_text.as_deref(),
            Some("Stale Body Channel")
        );
        assert_eq!(body_field.resolved_value.as_deref(), Some("Beta & Preview"));

        fn collect_variable_values(elements: &[BodyElement], values: &mut Vec<Option<String>>) {
            for element in elements {
                match element {
                    BodyElement::Paragraph(paragraph) => {
                        for run in &paragraph.runs {
                            if let Some(field) = run.field.as_ref() {
                                if matches!(field.kind, RunFieldKind::DocumentVariable { .. }) {
                                    values.push(field.resolved_value.clone());
                                }
                            }
                            if let Some(text_box) = run.text_box.as_ref() {
                                collect_variable_values(&text_box.blocks, values);
                            }
                        }
                    }
                    BodyElement::Table(table) => {
                        for row in &table.rows {
                            for cell in &row.cells {
                                collect_variable_values(&cell.blocks, values);
                            }
                        }
                    }
                    BodyElement::Math(_) => {}
                }
            }
        }
        let mut body_variable_values = Vec::new();
        collect_variable_values(
            &parsed.body.as_ref().expect("document body").elements,
            &mut body_variable_values,
        );
        assert_eq!(body_variable_values.len(), 3);
        assert!(body_variable_values
            .iter()
            .all(|value| value.as_deref() == Some("Beta & Preview")));

        let flatten_lines = |lines: &Option<Vec<HeaderLine>>| {
            lines
                .as_ref()
                .into_iter()
                .flatten()
                .flat_map(|line| [&line.left, &line.center, &line.right])
                .filter_map(|segment| segment.as_deref())
                .collect::<String>()
        };
        let header = flatten_lines(&doc.header_lines);
        let footer = flatten_lines(&doc.footer_lines);
        assert!(header.contains("Channel: Beta & Preview"));
        assert!(!header.contains("Stale Header Channel"));
        assert!(footer.contains("Build: 2026.07"));
        assert!(!footer.contains("Stale Footer Build"));

        // Header/footer editing reparses the standalone part. That refresh
        // path must resolve settings values again instead of reviving Word's
        // deliberately stale cached result.
        doc.refresh_header_footer_lines_for(
            HeaderFooterRole::Header,
            HeaderFooterVariant::Default,
            "word/header1.xml",
        )
        .expect("refresh header lines");
        let refreshed_header = flatten_lines(&doc.header_lines);
        assert!(refreshed_header.contains("Channel: Beta & Preview"));
        assert!(!refreshed_header.contains("Stale Header Channel"));
    }

    #[test]
    fn document_variable_fields_apply_word_capitalization_switches() {
        // Variable names may be quoted and instruction text may split inside
        // both the field name and switch. Apply formatting only after the
        // settings lookup so casing never changes the lookup key itself.
        let mut parsed = DocumentParser::new()
            .parse_document_xml(
                r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>
                  <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> DOCVAR</w:instrText></w:r><w:r><w:instrText>IABLE "Release Channel" \* Ca</w:instrText></w:r><w:r><w:instrText>ps </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>stale</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
                  <w:p><w:fldSimple w:instr=' DOCVARIABLE Environment \*Lower '><w:r><w:t>STALE</w:t></w:r></w:fldSimple></w:p>
                </w:body></w:document>"#,
            )
            .expect("parse DOCVARIABLE case fields");
        WordDocument::resolve_package_value_fields(
            &mut parsed,
            &HashMap::new(),
            &HashMap::from([
                (
                    "release channel".to_string(),
                    "production-ready".to_string(),
                ),
                ("environment".to_string(), "STAGING".to_string()),
            ]),
            None,
        );
        let values = parsed
            .body
            .as_ref()
            .expect("body")
            .elements
            .iter()
            .filter_map(BodyElement::as_paragraph)
            .filter_map(|paragraph| paragraph.runs.iter().find_map(|run| run.field.as_ref()))
            .map(|field| field.resolved_value.as_deref())
            .collect::<Vec<_>>();
        assert_eq!(values, [Some("Production-Ready"), Some("staging")]);
    }

    #[test]
    fn load_generated_if_compare_fields_recomputes_header_and_footer_results() {
        let data = std::fs::read(fixture_path("if-compare-field-edge-cases.docx"))
            .expect("read generated IF/COMPARE fixture");
        let doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load generated IF/COMPARE fixture");
        let flatten = |lines: &Option<Vec<HeaderLine>>| {
            lines
                .as_ref()
                .into_iter()
                .flatten()
                .flat_map(|line| [&line.left, &line.center, &line.right])
                .filter_map(|segment| segment.as_deref())
                .collect::<String>()
        };
        let header = flatten(&doc.header_lines);
        let footer = flatten(&doc.footer_lines);

        // `IF 2<10 …`: Word shows its syntax error for a compact expression
        // with a number on the left.
        assert!(
            header.contains("Header IF: エラー! 条件式が正しくありません。"),
            "{header}"
        );
        assert!(!header.contains("Stale header"), "{header}");
        assert!(footer.contains("Footer COMPARE: 1"), "{footer}");
    }

    #[test]
    fn header_footer_paragraph_merge_preserves_surviving_properties_and_run_xml() {
        let data = std::fs::read(fixture_path("header-footer-sections.docx")).unwrap();
        for role in [HeaderFooterRole::Header, HeaderFooterRole::Footer] {
            for variant in [
                HeaderFooterVariant::Default,
                HeaderFooterVariant::First,
                HeaderFooterVariant::Even,
            ] {
                let mut doc =
                    executor::block_on(WordDocument::load(&data, &Options::default())).unwrap();
                doc.ensure_hf_part_for_edit(role, variant).unwrap();
                let path = doc
                    .resolve_header_footer_part_path_for(role, variant)
                    .unwrap();
                let root = if role == HeaderFooterRole::Header {
                    "hdr"
                } else {
                    "ftr"
                };
                let properties = r#"<w:pPr w:custom="keep"><w:jc w:val="center"/><w:ind w:left="240"/><w:spacing w:after="120"/></w:pPr>"#;
                let first_run = r#"<w:r w:rsidR="12345678"><w:rPr><w:b/><w:lang w:val="ja-JP"/></w:rPr><w:t>ABC</w:t></w:r>"#;
                let second_run = r#"<w:r w:rsidR="87654321"><w:rPr><w:i/><w:color w:val="DC2626"/></w:rPr><w:t>DEF</w:t></w:r>"#;
                let untouched = r#"<w:p w:rsidR="11223344"><w:fldSimple w:instr="PAGE"><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p>"#;
                let wrap = |content: &str| {
                    format!(
                        r#"<w:{root} xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">{content}</w:{root}>"#
                    )
                };
                doc.upsert_xml_part_content(&path, wrap(&format!(
                    r#"<w:p w:rsidR="AABBCCDD">{properties}{first_run}</w:p><w:p w:rsidR="DDCCBBAA"><w:pPr><w:jc w:val="right"/></w:pPr>{second_run}</w:p>{untouched}"#
                )));
                doc.refresh_header_footer_lines_for(role, variant, &path)
                    .unwrap();
                let body_before = doc.read_xml_part_content("word/document.xml").unwrap();
                doc.merge_hf_paragraph_with_previous(role, variant, 1)
                    .unwrap();
                let expected = DocxXmlDocument::parse(&wrap(&format!(
                    r#"<w:p w:rsidR="AABBCCDD">{properties}{first_run}{second_run}</w:p>{untouched}"#
                ))).unwrap().to_string().unwrap();
                assert_eq!(doc.read_xml_part_content(&path).unwrap(), expected);
                assert_eq!(
                    doc.hf_plain_paragraph_text(role, variant, 0).as_deref(),
                    Some("ABCDEF")
                );
                assert_eq!(
                    doc.hf_paragraph_alignment(role, variant, 0).as_deref(),
                    Some("center")
                );
                assert_eq!(
                    doc.read_xml_part_content("word/document.xml").unwrap(),
                    body_before
                );
                let exported = doc.export_docx().unwrap();
                let reopened =
                    executor::block_on(WordDocument::load(&exported, &Options::default())).unwrap();
                assert_eq!(reopened.read_xml_part_content(&path).unwrap(), expected);
                assert_eq!(
                    reopened
                        .hf_plain_paragraph_text(role, variant, 0)
                        .as_deref(),
                    Some("ABCDEF")
                );
            }
        }
    }

