    #[test]
    fn header_footer_paragraph_break_inherits_formatting_at_empty_edges() {
        let data = std::fs::read(fixture_path("header-footer-sections.docx")).unwrap();
        for role in [HeaderFooterRole::Header, HeaderFooterRole::Footer] {
            for variant in [
                HeaderFooterVariant::Default,
                HeaderFooterVariant::First,
                HeaderFooterVariant::Even,
            ] {
                for offset in [0, 4] {
                    let mut doc =
                        executor::block_on(WordDocument::load(&data, &Options::default())).unwrap();
                    doc.ensure_hf_part_for_edit(role, variant).unwrap();
                    let path = doc
                        .resolve_header_footer_part_path_for(role, variant)
                        .unwrap();
                    let root = if role == HeaderFooterRole::Header {
                        "hdr"
                    } else {
                        "ftr"
                    };
                    let properties = r#"<w:pPr w:custom="keep"><w:spacing w:after="120"/><w:jc w:val="right"/></w:pPr>"#;
                    let first = r#"<w:r w:rsidR="12345678"><w:rPr><w:b/><w:sz w:val="36"/></w:rPr><w:t>AB</w:t></w:r>"#;
                    let last = r#"<w:r w:rsidR="87654321"><w:rPr><w:i/><w:color w:val="DC2626"/><w:lang w:val="ja-JP"/></w:rPr><w:t>CD</w:t></w:r>"#;
                    doc.upsert_xml_part_content(&path, format!(
                        r#"<w:{root} xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:p>{properties}{first}{last}</w:p></w:{root}>"#));
                    doc.refresh_header_footer_lines_for(role, variant, &path)
                        .unwrap();
                    doc.split_hf_paragraph_at_display_offset(role, variant, 0, offset, 2)
                        .unwrap();
                    let xml = doc.read_xml_part_content(&path).unwrap();
                    assert_eq!(xml.matches(properties).count(), 3);
                    assert!(xml.contains(first) && xml.contains(last));
                    for index in if offset == 0 { vec![0, 1] } else { vec![1, 2] } {
                        doc.replace_hf_paragraph_text(role, variant, index, "X")
                            .unwrap();
                        let state = doc.hf_paragraph_run_state(role, variant, index).unwrap();
                        assert_eq!(state.all_bold, offset == 0);
                        assert_eq!(state.all_italic, offset == 4);
                        assert_eq!(state.font_size, (offset == 0).then_some(18.0));
                        assert_eq!(state.color.as_deref(), (offset == 4).then_some("#DC2626"));
                    }
                    let xml = doc.read_xml_part_content(&path).unwrap();
                    let reopened = executor::block_on(WordDocument::load(
                        &doc.export_docx().unwrap(),
                        &Options::default(),
                    ))
                    .unwrap();
                    assert_eq!(reopened.read_xml_part_content(&path).unwrap(), xml);
                }
            }
        }
    }

