    /// `w:titlePg` (先頭ページのみ別指定) is a section property. The ribbon
    /// toggle has to land on the caret's section; writing it to the final
    /// section silently changed a different part of the document.
    #[test]
    fn title_page_toggle_targets_the_named_section() {
        let data = std::fs::read(fixture_path("header-footer-sections.docx"))
            .expect("read multi-section fixture");
        let mut doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load word document");
        assert_eq!(doc.section_title_page(0), Some(true));
        assert_eq!(doc.section_title_page(1), Some(false));

        // Turning it off in the first section leaves the second alone.
        assert!(doc
            .set_header_footer_variants(false, false, Some(0))
            .expect("clear the first section's title page"));
        let sections = section_properties_xml(&exported_document_xml(&doc));
        assert!(!sections[0].contains("<w:titlePg"), "{}", sections[0]);
        assert!(!sections[1].contains("<w:titlePg"), "{}", sections[1]);
        assert_eq!(doc.section_title_page(0), Some(false));

        // Turning it on in the second writes the body-level `w:sectPr` only.
        assert!(doc
            .set_header_footer_variants(true, false, Some(1))
            .expect("set the second section's title page"));
        let sections = section_properties_xml(&exported_document_xml(&doc));
        assert!(!sections[0].contains("<w:titlePg"), "{}", sections[0]);
        assert!(sections[1].contains("<w:titlePg"), "{}", sections[1]);
        assert_eq!(doc.section_title_page(0), Some(false));
        assert_eq!(doc.section_title_page(1), Some(true));

        let reopened = executor::block_on(WordDocument::load(
            &doc.export_docx().expect("export"),
            &Options::default(),
        ))
        .expect("reopen");
        assert_eq!(reopened.section_title_page(0), Some(false));
        assert_eq!(reopened.section_title_page(1), Some(true));
    }

