        let mut doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load word document");
        doc.ensure_hf_part_for_edit(HeaderFooterRole::Header, HeaderFooterVariant::Default)
            .expect("create header");
        let part_path = doc
            .resolve_header_footer_part_path_for(
                HeaderFooterRole::Header,
                HeaderFooterVariant::Default,
            )
            .expect("resolve header");
        doc.upsert_xml_part_content(
            &part_path,
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:x="urn:jade:test">
  <w:p><w:r><w:t>replace me</w:t></w:r></w:p>
  <w:tbl><w:tr><w:tc><w:p><w:r><w:t>table too</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
  <x:keep x:value="preserved"><x:child/></x:keep>
</w:hdr>"#
                .to_string(),
        );
