    #[test]
    fn remove_page_numbers_handles_complex_simple_and_legacy_fields() {
        let mut xml = DocxXmlDocument::parse(
            r#"<w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:x="urn:jade:test"><w:p>
<w:r><w:t>keep-a</w:t></w:r>
<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>7</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>
<w:fldSimple w:instr="PAGE \\* MERGEFORMAT"><w:r><w:t>8</w:t></w:r></w:fldSimple>
<w:r><w:t>keep-b</w:t><w:pgNum/></w:r>
<w:fldSimple w:instr="NUMPAGES"><w:r><w:t>9</w:t></w:r></w:fldSimple>
<x:keep/>
</w:p></w:hdr>"#,
        )
        .expect("parse field forms");
        let root_id = xml.root().id;
        let removed = {
            let root = xml.element_mut(root_id).expect("root");
            WordDocument::remove_page_fields_from_children(&mut root.children)
        };
        assert_eq!(removed, 3);
        xml.rebuild_index();
        let serialized = xml.to_string().expect("serialize fields");
        assert!(serialized.contains("keep-a"));
        assert!(serialized.contains("keep-b"));
        assert!(serialized.contains("NUMPAGES"));
        assert!(serialized.contains("x:keep"));
        assert!(!serialized.contains(" PAGE "));
        assert!(!serialized.contains("w:pgNum"));
    }

    #[test]
    fn remove_page_numbers_visits_every_existing_header_footer_variant() {
        let data = std::fs::read(fixture_path("hello.docx")).expect("read hello fixture");
        let mut doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load word document");
        let slots = [
            (HeaderFooterRole::Header, HeaderFooterVariant::Default),
            (HeaderFooterRole::Header, HeaderFooterVariant::First),
            (HeaderFooterRole::Header, HeaderFooterVariant::Even),
            (HeaderFooterRole::Footer, HeaderFooterVariant::Default),
            (HeaderFooterRole::Footer, HeaderFooterVariant::First),
            (HeaderFooterRole::Footer, HeaderFooterVariant::Even),
        ];
        let mut part_paths = Vec::new();
        for (index, (role, variant)) in slots.into_iter().enumerate() {
            let alignment = match index % 3 {
                0 => HeaderFooterAlignment::Left,
                1 => HeaderFooterAlignment::Center,
                _ => HeaderFooterAlignment::Right,
            };
            doc.set_hf_page_number(role, variant, alignment)
                .expect("insert page number into variant");
            let part_path = doc
                .resolve_header_footer_part_path_for(role, variant)
                .expect("resolve variant part");
            assert!(exported_part_xml(&doc, &part_path).contains(" PAGE "));
            part_paths.push(part_path);
        }

        assert_eq!(
            doc.remove_page_numbers_from_header_footers()
                .expect("remove all page numbers"),
            slots.len()
        );
        for part_path in &part_paths {
            assert!(!exported_part_xml(&doc, part_path).contains(" PAGE "));
        }

        let exported = doc.export_docx().expect("export without page numbers");
        let mut reopened = executor::block_on(WordDocument::load(&exported, &Options::default()))
            .expect("reopen without page numbers");
        for ((role, variant), expected_path) in slots.into_iter().zip(part_paths) {
            assert_eq!(
                reopened
                    .resolve_header_footer_part_path_for(role, variant)
                    .expect("variant reference survives removal"),
                expected_path
            );
            assert!(!exported_part_xml(&reopened, &expected_path).contains(" PAGE "));
        }
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 64, ..ProptestConfig::default() })]

        #[test]
        fn removing_page_numbers_preserves_generated_unicode_and_other_fields(
            prefix in proptest::collection::vec(
                prop::sample::select(vec!['a', 'Z', '0', ' ', 'あ', '界', '😀', 'é']),
                0..24,
            ).prop_map(|chars| chars.into_iter().collect::<String>()),
            suffix in proptest::collection::vec(
                prop::sample::select(vec!['b', 'Y', '9', ' ', 'い', '語', '🚀', 'ß']),
                0..24,
            ).prop_map(|chars| chars.into_iter().collect::<String>()),
        ) {
            let data = std::fs::read(fixture_path("hello.docx")).expect("read hello fixture");
            let mut doc = executor::block_on(WordDocument::load(&data, &Options::default()))
                .expect("load word document");
            doc.ensure_hf_part_for_edit(
                HeaderFooterRole::Footer,
                HeaderFooterVariant::Default,
            )
            .expect("create footer");
            let part_path = doc
                .resolve_header_footer_part_path_for(
                    HeaderFooterRole::Footer,
                    HeaderFooterVariant::Default,
                )
                .expect("resolve footer");
            let footer_xml = format!(
                r#"<?xml version="1.0" encoding="UTF-8"?>
<w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:x="urn:jade:test"><w:p>
<w:r><w:t xml:space="preserve">{}</w:t></w:r>
<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>7</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>
<w:r><w:t xml:space="preserve">{}</w:t></w:r>
<w:fldSimple w:instr="NUMPAGES"><w:r><w:t>9</w:t></w:r></w:fldSimple><x:keep x:value="yes"/>
</w:p></w:ftr>"#,
                xml_escape_text(&prefix),
                xml_escape_text(&suffix),
            );
            doc.upsert_xml_part_content(&part_path, footer_xml);
            doc.refresh_header_footer_lines_for(
                HeaderFooterRole::Footer,
                HeaderFooterVariant::Default,
                &part_path,
            )
            .expect("refresh generated footer");

            let removed = doc
                .remove_page_numbers_from_header_footers()
                .expect("remove generated PAGE field");
            prop_assert_eq!(removed, 1);
            let xml = exported_part_xml(&doc, &part_path);
            prop_assert!(!xml.contains(" PAGE "));
            prop_assert!(xml.contains("NUMPAGES"));
            prop_assert!(xml.contains("x:keep"));
            prop_assert!(xml.contains(&xml_escape_text(&prefix)));
            prop_assert!(xml.contains(&xml_escape_text(&suffix)));

            let exported = doc.export_docx().expect("export removed page number");
            let reopened = executor::block_on(WordDocument::load(
                &exported,
                &Options::default(),
            ))
            .expect("reopen removed page number");
            let flattened = reopened
                .footer_lines
                .as_ref()
                .into_iter()
                .flatten()
                .flat_map(|line| [&line.left, &line.center, &line.right])
                .filter_map(|segment| segment.as_deref())
                .collect::<String>();
            prop_assert!(!flattened.contains(crate::document::PAGE_FIELD_PLACEHOLDER));
            prop_assert!(flattened.contains(crate::document::PAGE_COUNT_FIELD_PLACEHOLDER));
            let visible_prefix = prefix.trim();
            let visible_suffix = suffix.trim();
            prop_assert!(visible_prefix.is_empty() || flattened.contains(visible_prefix));
            prop_assert!(visible_suffix.is_empty() || flattened.contains(visible_suffix));
        }
    }

