    #[test]
    fn load_yokohama_fixture_resolves_group_shape_hyperlinks() {
        let data =
            std::fs::read(fixture_path("yokohama_page1.docx")).expect("read yokohama fixture");
        let doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load yokohama docx");
        let image = doc
            .document
            .as_ref()
            .and_then(|document| document.body.as_ref())
            .and_then(|body| {
                body.elements
                    .iter()
                    .filter_map(|element| element.as_paragraph())
                    .find_map(|paragraph| {
                        paragraph.runs.iter().find_map(|run| {
                            let image = run.image.as_ref()?;
                            image.shape_group.as_ref()?;
                            Some(image)
                        })
                    })
            })
            .expect("shape group image");
        let group = image.shape_group.as_ref().expect("shape group");
        assert!(matches!(image.layout.kind, RunImageKind::Floating));

        let hyperlinks = group
            .children
            .iter()
            .map(|shape| shape.hyperlink.as_ref().expect("child hyperlink"))
            .collect::<Vec<_>>();
        assert_eq!(
            hyperlinks[0].target.as_deref(),
            Some("https://cgi.city.yokohama.lg.jp/index.html")
        );
        assert_eq!(
            hyperlinks[1].target.as_deref(),
            Some("https://www.city.yokohama.lg.jp/aboutweb/search/search.html")
        );
        assert!(hyperlinks
            .iter()
            .all(|hyperlink| hyperlink.target_mode.as_deref() == Some("External")));
        assert!(hyperlinks
            .iter()
            .all(|hyperlink| hyperlink.target_frame.as_deref() == Some("_top")));
    }

