    #[test]
    fn apply_style_numbering_propagates_style_auto_space_settings() {
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="jpStyle"/></w:pPr>
      <w:r><w:t>第2項</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="jpStyle">
    <w:pPr>
      <w:autoSpaceDE w:val="0"/>
      <w:autoSpaceDN/>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_numbering_to_document(&mut document, &styles);

        let paragraph = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(|element| element.as_paragraph())
            .expect("paragraph");
        let settings = paragraph
            .properties
            .as_ref()
            .and_then(|props| props.east_asian_settings.as_ref())
            .expect("east asian settings");
        assert_eq!(settings.auto_space_de, Some(false));
        assert_eq!(settings.auto_space_dn, Some(true));
    }

    #[test]
    fn apply_style_paragraph_defaults_propagates_style_shading_and_borders() {
        // A paragraph that only references a style (no direct `w:shd`/`w:pBdr`)
        // must inherit the style's shading and borders so the renderer—which
        // reads `paragraph.properties.shading`/`.borders` directly—reproduces
        // the box. ECMA-376 §17.3.5 / §17.3.1.24.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="boxed"/></w:pPr>
      <w:r><w:t>本文</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="boxed">
    <w:pPr>
      <w:shd w:val="clear" w:color="auto" w:fill="FFFF00"/>
      <w:pBdr>
        <w:top w:val="single" w:sz="8" w:space="4" w:color="FF0000"/>
      </w:pBdr>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let paragraph = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(|element| element.as_paragraph())
            .expect("paragraph");
        let props = paragraph.properties.as_ref().expect("paragraph props");

        let shading = props.shading.as_ref().expect("inherited shading");
        assert_eq!(shading.fill.as_deref(), Some("#FFFF00"));

        let borders = props.borders.as_ref().expect("inherited borders");
        let top = borders.top.as_ref().expect("top edge");
        assert_eq!(top.val.as_deref(), Some("single"));
        assert_eq!(top.color.as_deref(), Some("#FF0000"));
    }

    #[test]
    fn apply_style_paragraph_defaults_propagates_suppress_line_numbers() {
        // A paragraph that only references a style (no direct
        // `w:suppressLineNumbers`) must inherit the style's flag so the renderer
        // excludes its lines from margin line numbering. ECMA-376 §17.3.1.35.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="nonumber"/></w:pPr>
      <w:r><w:t>本文</w:t></w:r>
    </w:p>
    <w:p>
      <w:r><w:t>本文2</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="nonumber">
    <w:pPr>
      <w:suppressLineNumbers/>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let elements = document
            .body
            .as_ref()
            .map(|body| body.elements.as_slice())
            .expect("body");
        let styled = elements[0].as_paragraph().expect("styled paragraph");
        assert_eq!(
            styled
                .properties
                .as_ref()
                .and_then(|props| props.suppress_line_numbers),
            Some(true),
            "styled paragraph inherits suppressLineNumbers"
        );

        let plain = elements[1].as_paragraph().expect("plain paragraph");
        assert_eq!(
            plain
                .properties
                .as_ref()
                .and_then(|props| props.suppress_line_numbers),
            None,
            "paragraph without the style is unaffected"
        );
    }

    #[test]
    fn apply_style_paragraph_defaults_propagates_text_alignment() {
        // A paragraph that only references a style (no direct `w:textAlignment`)
        // inherits the style's vertical glyph alignment so the renderer can
        // resolve the line-box leading share. ECMA-376 §17.3.1.39.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="centered"/></w:pPr>
      <w:r><w:t>styled</w:t></w:r>
    </w:p>
    <w:p>
      <w:r><w:t>plain</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="centered">
    <w:pPr>
      <w:textAlignment w:val="center"/>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let body = document.body.as_ref().expect("body");
        let styled = body.elements[0].as_paragraph().expect("styled paragraph");
        assert_eq!(
            styled
                .properties
                .as_ref()
                .and_then(|p| p.text_alignment.as_deref()),
            Some("center")
        );

        let plain = body.elements[1].as_paragraph().expect("plain paragraph");
        assert_eq!(
            plain
                .properties
                .as_ref()
                .and_then(|p| p.text_alignment.as_deref()),
            None
        );
    }

    #[test]
    fn apply_style_paragraph_defaults_propagates_outline_level() {
        // A paragraph that only references a heading style (no direct
        // `w:outlineLvl`) inherits the style's outline level so the document
        // structure / navigation can resolve heading depth. ECMA-376 §17.3.1.20.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="Heading1"/></w:pPr>
      <w:r><w:t>heading</w:t></w:r>
    </w:p>
    <w:p>
      <w:r><w:t>body</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="Heading1">
    <w:pPr>
      <w:outlineLvl w:val="0"/>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let body = document.body.as_ref().expect("body");
        let styled = body.elements[0].as_paragraph().expect("styled paragraph");
        assert_eq!(
            styled.properties.as_ref().and_then(|p| p.outline_level),
            Some(0),
            "styled paragraph inherits the Heading 1 outline level"
        );

        let plain = body.elements[1].as_paragraph().expect("plain paragraph");
        assert_eq!(
            plain.properties.as_ref().and_then(|p| p.outline_level),
            None,
            "paragraph without the style stays body text"
        );
    }

