    #[test]
    fn direct_paragraph_shading_overrides_style_shading() {
        // Direct `w:shd` on the paragraph wins over the style's shading because
        // `fill_missing_paragraph_props` only fills when the target is absent.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr>
        <w:pStyle w:val="boxed"/>
        <w:shd w:val="clear" w:color="auto" w:fill="00FF00"/>
      </w:pPr>
      <w:r><w:t>本文</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="boxed">
    <w:pPr>
      <w:shd w:val="clear" w:color="auto" w:fill="FFFF00"/>
    </w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let paragraph = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(|element| element.as_paragraph())
            .expect("paragraph");
        let shading = paragraph
            .properties
            .as_ref()
            .and_then(|props| props.shading.as_ref())
            .expect("shading");
        assert_eq!(shading.fill.as_deref(), Some("#00FF00"));
    }

    #[test]
    fn style_inherited_outline_level_remains_a_toc_source_without_u() {
        // Word's `TOC \\o` is not limited to the built-in Heading1…Heading9
        // style ids. A custom style whose definition supplies `w:outlineLvl`
        // is also a heading source. This guards the other half of the `\\u`
        // fix: provenance tracking must exclude direct outline formatting
        // without accidentally excluding outline levels inherited from styles.
        let document_xml = r#"
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:pPr><w:pStyle w:val="OutlineHeading"/></w:pPr>
      <w:r><w:t>Style-defined outline heading</w:t></w:r>
    </w:p>
  </w:body>
</w:document>
"#;
        let styles_xml = r#"
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:style w:type="paragraph" w:styleId="OutlineHeading">
    <w:name w:val="Outline Heading"/>
    <w:pPr><w:outlineLvl w:val="1"/></w:pPr>
  </w:style>
</w:styles>
"#;

        let parser = DocumentParser::new();
        let mut document = parser
            .parse_document_xml(document_xml)
            .expect("parse document");
        let styles = crate::styles::StylesPart::from_xml(styles_xml).expect("parse styles");

        WordDocument::apply_style_paragraph_defaults_to_document(&mut document, &styles);

        let paragraph_props = document
            .body
            .as_ref()
            .and_then(|body| body.elements.first())
            .and_then(|element| element.as_paragraph())
            .and_then(|paragraph| paragraph.properties.as_ref())
            .expect("styled paragraph properties");
        assert_eq!(paragraph_props.outline_level, Some(1));
        assert!(
            !paragraph_props.outline_level_is_direct,
            "style materialization must not mark inherited outlineLvl as direct"
        );

        let entries = document.generate_outline(&TocOptions::default());
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].text, "Style-defined outline heading");
        assert_eq!(entries[0].level, 2);
    }

    #[test]
    fn font_size_falls_back_to_style_and_doc_defaults() {
        let data = build_font_size_fallback_docx();
        let options = Options::default();
        let doc = executor::block_on(WordDocument::load(&data, &options))
            .expect("load fallback font docx");

        let body = doc
            .document
            .as_ref()
            .and_then(|d| d.body.as_ref())
            .expect("document body");

        let mut styled_size = None;
        let mut doc_default_size = None;
        let mut explicit_size = None;
        let mut explicit_complex_size = None;

        for element in &body.elements {
            if let Some(paragraph) = element.as_paragraph() {
                let text: String = paragraph.runs.iter().map(|run| run.text.as_str()).collect();
                if text.contains("Styled") {
                    styled_size = paragraph
                        .runs
                        .first()
                        .and_then(|run| run.properties.as_ref())
                        .and_then(|props| props.font_size);
                } else if text.contains("DocDefault") {
                    doc_default_size = paragraph
                        .runs
                        .first()
                        .and_then(|run| run.properties.as_ref())
                        .and_then(|props| props.font_size);
                } else if text.contains("Explicit") {
                    let props = paragraph
                        .runs
                        .first()
                        .and_then(|run| run.properties.as_ref());
                    explicit_size = props.and_then(|props| props.font_size);
                    explicit_complex_size = props.and_then(|props| props.font_size_complex);
                }
            }
        }

        assert_eq!(
            styled_size,
            Some(16.0),
            "custom paragraph style should define the fallback size"
        );
        assert_eq!(
            doc_default_size,
            Some(11.0),
            "paragraphs without run or style overrides should inherit doc defaults"
        );
        // `w:szCs` sizes complex-script text only. Word for Mac draws a run
        // that declares `w:szCs` alone at the inherited `w:sz`, Latin and
        // Japanese text alike.
        assert_eq!(
            explicit_size,
            Some(11.0),
            "a direct szCs alone leaves the run's size to the doc defaults"
        );
        assert_eq!(explicit_complex_size, Some(15.0));
    }

    #[test]
    fn adjust_right_indent_load_cascade_and_export_preserve_directness() {
        const DOC: &str = r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>
            <w:p><w:r><w:t>default off</w:t></w:r></w:p>
            <w:p><w:pPr><w:pStyle w:val="On"/></w:pPr><w:r><w:t>style on</w:t></w:r></w:p>
            <w:p><w:pPr><w:pStyle w:val="On"/><w:adjustRightInd w:val="0"/></w:pPr><w:r><w:t>direct off</w:t></w:r></w:p>
        </w:body></w:document>"#;
        const STYLES: &str = r#"<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
            <w:docDefaults><w:pPrDefault><w:pPr><w:adjustRightInd w:val="0"/></w:pPr></w:pPrDefault></w:docDefaults>
            <w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style>
            <w:style w:type="paragraph" w:styleId="On"><w:basedOn w:val="Normal"/><w:pPr><w:adjustRightInd/></w:pPr></w:style>
        </w:styles>"#;
        let data = build_docx_from_parts(&[
            (
                "[Content_Types].xml",
                r#"<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>"#,
            ),
            (
                "_rels/.rels",
                r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>"#,
            ),
            (
                "word/_rels/document.xml.rels",
                r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>"#,
            ),
            ("word/document.xml", DOC),
            ("word/styles.xml", STYLES),
        ]);
        let doc = executor::block_on(WordDocument::load(&data, &Options::default())).unwrap();
        let values: Vec<_> = doc
            .document
            .as_ref()
            .unwrap()
            .body
            .as_ref()
            .unwrap()
            .elements
            .iter()
            .map(|e| {
                e.as_paragraph()
                    .unwrap()
                    .properties
                    .as_ref()
                    .and_then(|p| p.adjust_right_indent)
            })
            .collect();
        assert_eq!(values, vec![Some(false), Some(true), Some(false)]);
        let exported = doc.export_docx().unwrap();
        let mut archive = ZipArchive::new(std::io::Cursor::new(exported)).unwrap();
        let mut xml = String::new();
        archive
            .by_name("word/document.xml")
            .unwrap()
            .read_to_string(&mut xml)
            .unwrap();
        assert_eq!(
            xml.matches("adjustRightInd").count(),
            1,
            "inherited formatting must not become direct formatting"
        );
        let reparsed = DocumentParser::new().parse_document_xml(&xml).unwrap();
        let direct: Vec<_> = reparsed
            .body
            .unwrap()
            .elements
            .iter()
            .map(|e| {
                e.as_paragraph()
                    .unwrap()
                    .properties
                    .as_ref()
                    .and_then(|p| p.adjust_right_indent)
            })
            .collect();
        assert_eq!(direct, vec![None, None, Some(false)]);
    }

