    #[test]
    fn paragraph_spacing_inherits_unset_parts_and_table_style_spacing() {
        const DOCUMENT_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:pPr><w:spacing w:after="0"/></w:pPr><w:r><w:t>Body</w:t></w:r></w:p>
    <w:tbl>
      <w:tblPr><w:tblStyle w:val="TableGrid"/></w:tblPr>
      <w:tblGrid><w:gridCol w:w="2000"/></w:tblGrid>
      <w:tr><w:tc>
        <w:p><w:r><w:t>Cell</w:t></w:r></w:p>
        <w:p><w:pPr><w:pStyle w:val="Spaced"/></w:pPr><w:r><w:t>Styled</w:t></w:r></w:p>
      </w:tc></w:tr>
    </w:tbl>
    <w:p><w:r><w:t>After</w:t></w:r></w:p>
  </w:body>
</w:document>"#;
        const STYLES_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:docDefaults><w:pPrDefault><w:pPr>
    <w:spacing w:after="200" w:line="276" w:lineRule="auto"/>
  </w:pPr></w:pPrDefault></w:docDefaults>
  <w:style w:type="paragraph" w:styleId="Spaced"><w:name w:val="Spaced"/>
    <w:pPr><w:spacing w:before="120"/></w:pPr></w:style>
  <w:style w:type="table" w:styleId="TableGrid"><w:name w:val="Table Grid"/>
    <w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr></w:style>
</w:styles>"#;
        let cursor = std::io::Cursor::new(Vec::new());
        let mut zip = zip::ZipWriter::new(cursor);
        let options = SimpleFileOptions::default();
        for (name, body) in [
            (
                "[Content_Types].xml",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
  <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
</Types>"#,
            ),
            (
                "_rels/.rels",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>"#,
            ),
            (
                "word/_rels/document.xml.rels",
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>"#,
            ),
            ("word/document.xml", DOCUMENT_XML),
            ("word/styles.xml", STYLES_XML),
        ] {
            zip.start_file(name, options).expect("zip entry");
            zip.write_all(body.as_bytes()).expect("write entry");
        }
        let data = zip.finish().expect("finish zip").into_inner();
        let doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");
        let body = doc.document.as_ref().and_then(|d| d.body.as_ref()).unwrap();
        let spacing = |paragraph: &Paragraph| {
            let spacing = paragraph
                .properties
                .as_ref()
                .and_then(|props| props.spacing.clone())
                .expect("spacing");
            (spacing.before, spacing.after, spacing.line)
        };
        let BodyElement::Paragraph(direct) = &body.elements[0] else {
            panic!("paragraph")
        };
        // `w:after` alone keeps the default 1.15 line spacing.
        assert_eq!(spacing(direct), (None, Some(0.0), Some(1.15)));
        let BodyElement::Table(table) = &body.elements[1] else {
            panic!("table")
        };
        let cell = &table.rows[0].cells[0].blocks;
        let BodyElement::Paragraph(cell_plain) = &cell[0] else {
            panic!("cell paragraph")
        };
        let BodyElement::Paragraph(cell_styled) = &cell[1] else {
            panic!("cell paragraph")
        };
        // The table style sits between the paragraph style and the defaults.
        assert_eq!(spacing(cell_plain), (None, Some(0.0), Some(1.0)));
        assert_eq!(spacing(cell_styled), (Some(6.0), Some(0.0), Some(1.0)));
        let BodyElement::Paragraph(after) = &body.elements[2] else {
            panic!("paragraph")
        };
        assert_eq!(spacing(after), (None, Some(10.0), Some(1.15)));
    }

