    #[test]
    fn table_row_insert_preserves_table_properties_and_new_cell_text_export() {
        use crate::commands::{insert_text::InsertTextCommand, CommandContext, CommandExecutor};
        use jade_docx_layout::selection::{SelectionRange, TextPosition};

        let data = std::fs::read(fixture_path("table2x2.docx")).expect("read table fixture");
        let options = Options::default();
        let mut doc = executor::block_on(WordDocument::load(&data, &options)).expect("load docx");
        doc.insert_table_row(0, 2, None).expect("insert row");

        let new_paragraph_node_id = doc
            .table_by_order(0)
            .and_then(|table| table.rows.get(2))
            .and_then(|row| row.cells.first())
            .and_then(|cell| cell.blocks.first())
            .and_then(BodyElement::as_paragraph)
            .and_then(|paragraph| paragraph.node_id)
            .expect("new paragraph node id");
        assert!(
            doc.raw_document
                .as_ref()
                .and_then(|raw| raw.element(new_paragraph_node_id))
                .is_some(),
            "new paragraph id must remain indexed after table rewrite",
        );
        let new_cell_paragraph = (0..doc.paragraph_count())
            .find(|index| {
                doc.paragraph(*index)
                    .and_then(|paragraph| paragraph.node_id)
                    == Some(new_paragraph_node_id)
            })
            .expect("new cell paragraph surface");
        let range = SelectionRange::collapsed(TextPosition::new(new_cell_paragraph, 0));
        let mut selection = Some(range);
        let mut command_executor = CommandExecutor::new();
        {
            let mut ctx = CommandContext::new(&mut doc, &mut selection);
            command_executor
                .execute(
                    Box::new(InsertTextCommand::new(
                        range,
                        "NEW-CELL-TEXT".to_string(),
                        None,
                    )),
                    &mut ctx,
                )
                .expect("edit new cell");
        }

        let xml = exported_document_xml(&doc);
        assert!(xml.contains("<w:tblBorders>"), "table borders were lost");
        assert!(
            xml.contains("NEW-CELL-TEXT"),
            "new cell edit was not exported: {xml}"
        );
    }

    #[test]
    fn table_with_text_direction_fixture_parses_per_cell_directions() {
        // Locks the parse path that feeds the vertical-cell caret/hit-test fix
        // (TODO item 19): the single-row table carries one cell per OOXML
        // textDirection variant. tbRl/tbRlV are the vertically-stacked cells
        // whose caret coordinates the fix corrects.
        use crate::document::TextDirection;

        let data = std::fs::read(fixture_path("table-with-text-direction.docx"))
            .expect("read table-with-text-direction fixture");
        let options = Options::default();
        let doc = executor::block_on(WordDocument::load(&data, &options)).expect("load docx");

        let body = doc
            .document
            .as_ref()
            .and_then(|d| d.body.as_ref())
            .expect("document body");

        let table = body
            .elements
            .iter()
            .find_map(|element| match element {
                BodyElement::Table(table) => Some(table.as_ref()),
                _ => None,
            })
            .expect("first table in fixture");

        let directions: Vec<Option<TextDirection>> = table
            .rows
            .iter()
            .flat_map(|row| row.cells.iter())
            .map(|cell| cell.text_direction)
            .collect();

        assert_eq!(
            directions,
            vec![
                Some(TextDirection::TbRlV),
                Some(TextDirection::TbRl),
                Some(TextDirection::BtLr),
                Some(TextDirection::LrTbV),
            ],
            "each cell should carry its declared textDirection"
        );

        // The vertically-stacked cells (tbRl/tbRlV) must retain their text so the
        // renderer can stack one grapheme per line and the caret can walk Y.
        let cell_text = |row_idx: usize, cell_idx: usize| -> String {
            table.rows[row_idx].cells[cell_idx]
                .blocks
                .iter()
                .filter_map(|block| match block {
                    BodyElement::Paragraph(paragraph) => Some(
                        paragraph
                            .runs
                            .iter()
                            .map(|run| run.text.as_str())
                            .collect::<String>(),
                    ),
                    _ => None,
                })
                .collect()
        };
        assert_eq!(cell_text(0, 0), "こんにちは");
        assert_eq!(cell_text(0, 1), "世界");
    }

    #[test]
    fn math_blocks_reserve_noneditable_surface_between_paragraphs() {
        let paragraph_before = make_paragraph("Before math");
        let paragraph_after = make_paragraph("After math");

        let text_node = MathElement {
            kind: MathElementKind::Text,
            tag: Some("t".to_string()),
            children: Vec::new(),
            text: Some("E = mc^2".to_string()),
            attributes: BTreeMap::new(),
        };
        let math_node = MathElement {
            kind: MathElementKind::Math,
            tag: Some("oMath".to_string()),
            children: vec![text_node],
            text: None,
            attributes: BTreeMap::new(),
        };
        let root = MathElement {
            kind: MathElementKind::MathParagraph,
            tag: Some("oMathPara".to_string()),
            children: vec![math_node],
            text: None,
            attributes: BTreeMap::new(),
        };

        let math_paragraph = MathParagraph {
            properties: None,
            raw_omml: "<m:oMathPara><m:oMath>E = mc^2</m:oMath></m:oMathPara>".to_string(),
            elements: vec![root],
        };

        let document = Document {
            body: Some(Body {
                elements: vec![
                    BodyElement::from_paragraph(paragraph_before),
                    BodyElement::from_math_paragraph(math_paragraph.clone()),
                    BodyElement::from_paragraph(paragraph_after),
                ],
            }),
            ..Document::default()
        };

        let word_doc = WordDocument::from_document(document);

        assert_eq!(word_doc.paragraph_count(), 3);
        assert_eq!(word_doc.paragraph(0).unwrap().runs[0].text, "Before math");
        assert!(word_doc.paragraph(1).is_none());
        assert!(!word_doc.is_body_paragraph_surface(1));
        assert!(word_doc.story_position_for_surface(1).is_none());
        assert_eq!(word_doc.paragraph(2).unwrap().runs[0].text, "After math");
        let preview = math_paragraph.preview_text(16).expect("preview text");
        assert_eq!(preview, "E = mc^2");
    }

