    #[test]
    fn clamps_rendered_offsets_to_editable_utf8_boundaries() {
        let document = Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(make_paragraph("無断欠勤"))],
            }),
            ..Document::default()
        };
        let word_doc = WordDocument::from_document(document);

        assert_eq!(
            word_doc.clamp_rendered_text_position(TextPosition::new(0, 5)),
            Some(TextPosition::new(0, 3)),
            "an offset inside a Japanese character must move to its byte boundary"
        );
        assert_eq!(
            word_doc.clamp_rendered_text_position(TextPosition::new(0, 5_267)),
            Some(TextPosition::new(0, 12)),
            "computed field text must not produce an offset past the stored paragraph"
        );
    }

