    #[test]
    fn table_fixture_accepts_text_in_each_cell() {
        use crate::commands::{insert_text::InsertTextCommand, CommandContext, CommandExecutor};
        use jade_docx_layout::selection::{SelectionRange, TextPosition};

        let data = std::fs::read(fixture_path("table2x2.docx")).expect("read table2x2 fixture");
        let options = Options::default();
        let mut doc = executor::block_on(WordDocument::load(&data, &options)).expect("load docx");

        let mut executor = CommandExecutor::new();

        for (idx, paragraph_index) in [0usize, 1, 2, 3].into_iter().enumerate() {
            let range = SelectionRange::collapsed(TextPosition::new(paragraph_index, 0));
            let label = match idx {
                0 => "L1",
                1 => "R1",
                2 => "L2",
                3 => "R2",
                _ => unreachable!(),
            };
            let mut selection = Some(range);
            {
                let mut ctx = CommandContext::new(&mut doc, &mut selection);
                executor
                    .execute(
                        Box::new(InsertTextCommand::new(range, label.to_string(), None)),
                        &mut ctx,
                    )
                    .expect("insert text");
            }
        }

        let expected = ["L1Hello", "R1", "L2", "R2World"];
        for (idx, expected_text) in expected.iter().enumerate() {
            let paragraph = doc.paragraph(idx).expect("paragraph");
            let text: String = paragraph.runs.iter().map(|run| run.text.as_str()).collect();
            assert!(
                text.contains(expected_text),
                "paragraph {idx} should contain {expected_text:?}, got {text:?}"
            );
        }
    }

