    #[test]
    fn insert_footnote_creates_reference_part_and_exports_docx() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <w:body>
    <w:p><w:r><w:t>Hello world</w:t></w:r></w:p>
  </w:body>
</w:document>
"#;
        let data = build_document_docx(document_xml);
        let options = Options::default();
        let mut doc =
            executor::block_on(WordDocument::load(&data, &options)).expect("load minimal docx");

        let id = doc
            .insert_footnote_at(0, "Hello".len(), "Footnote body")
            .expect("insert footnote");
        assert_eq!(id, "2");

        let paragraph = doc.paragraph(0).expect("paragraph");
        assert!(
            paragraph
                .runs
                .iter()
                .any(|run| run.footnote_reference_ids == vec!["2".to_string()]),
            "main paragraph should contain a footnote reference run"
        );
        let parsed = doc.document.as_ref().expect("document");
        assert!(
            parsed.footnotes.contains_key("2"),
            "model should include inserted footnote"
        );
        assert_eq!(
            doc.paragraph_count(),
            2,
            "inserted footnote paragraph should be exposed as an editable paragraph surface"
        );
        {
            let footnote_paragraph = doc.paragraph_mut(1).expect("footnote paragraph surface");
            let body_run = footnote_paragraph
                .runs
                .iter_mut()
                .find(|run| run.text.contains("Footnote body"))
                .expect("footnote body run");
            body_run.text.push_str(" edited");
        }
        doc.sync_paragraph_text(1);

        let exported = doc.export_docx().expect("export docx");
        let mut archive = ZipArchive::new(std::io::Cursor::new(exported)).expect("zip archive");

        let mut document_xml = String::new();
        archive
            .by_name("word/document.xml")
            .expect("document.xml")
            .read_to_string(&mut document_xml)
            .expect("read document");
        assert!(
            document_xml.contains(r#"<w:footnoteReference w:id="2"/>"#),
            "document.xml should contain footnote reference: {document_xml}"
        );
        assert!(
            document_xml.contains(
                r#"<w:rPr><w:vertAlign w:val="superscript"/></w:rPr><w:footnoteReference w:id="2"/>"#
            ),
            "the body reference run should be superscript, matching both Word \
             and the canvas rendering: {document_xml}"
        );

        let mut rels_xml = String::new();
        archive
            .by_name("word/_rels/document.xml.rels")
            .expect("document rels")
            .read_to_string(&mut rels_xml)
            .expect("read rels");
        assert!(rels_xml.contains("relationships/footnotes"));
        assert!(rels_xml.contains(r#"Target="footnotes.xml""#));

        let mut content_types = String::new();
        archive
            .by_name("[Content_Types].xml")
            .expect("content types")
            .read_to_string(&mut content_types)
            .expect("read content types");
        assert!(content_types.contains("/word/footnotes.xml"));

        let mut footnotes_xml = String::new();
        archive
            .by_name("word/footnotes.xml")
            .expect("footnotes.xml")
            .read_to_string(&mut footnotes_xml)
            .expect("read footnotes");
        assert!(footnotes_xml.contains(r#"<w:footnote w:id="2">"#));
        assert!(footnotes_xml.contains("<w:footnoteRef/>"));
        assert!(
            footnotes_xml
                .contains(r#"<w:rPr><w:vertAlign w:val="superscript"/></w:rPr><w:footnoteRef/>"#),
            "the note-area marker run should be superscript: {footnotes_xml}"
        );
        assert!(footnotes_xml.contains("<w:t>Footnote body edited</w:t>"));
    }

