    #[test]
    fn soft_hyphen_round_trips_as_word_run_element() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:r><w:t>co</w:t><w:softHyphen/><w:t>operate</w:t></w:r></w:p>
  </w:body>
</w:document>"#;
        let data = build_document_docx(document_xml);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        let paragraph = word_doc.paragraph_mut(0).expect("paragraph");
        assert_eq!(paragraph.runs[0].text, "co\u{00AD}operate");
        paragraph.runs[0].text = "re\u{00AD}enter".to_string();
        word_doc.sync_paragraph_text(0);

        let raw = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert_eq!(
            raw.matches("<w:softHyphen/>").count(),
            1,
            "edited run must contain exactly one discretionary hyphen: {raw}",
        );
        assert!(
            raw.contains("<w:t>re</w:t><w:softHyphen/><w:t>enter</w:t>"),
            "soft hyphen must remain at its logical character offset: {raw}",
        );
        assert!(
            !raw.contains('\u{00AD}'),
            "U+00AD must serialize as the Word run element, not literal text: {raw}",
        );
    }

