    #[test]
    fn symbol_run_element_does_not_duplicate_decoded_character() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:r><w:sym w:font="Wingdings" w:char="F0E0"/><w:t xml:space="preserve"> tail</w:t></w:r></w:p>
  </w:body>
</w:document>"#;
        let data = build_document_docx(document_xml);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        let paragraph = word_doc.paragraph_mut(0).expect("paragraph");
        assert_eq!(paragraph.runs[0].text, "\u{F0E0} tail");
        paragraph.runs[0].text = "\u{F0E0} updated".to_string();
        word_doc.sync_paragraph_text(0);

        let raw = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert_eq!(
            raw.matches("<w:sym ").count(),
            1,
            "edited run must retain exactly one symbol element: {raw}",
        );
        assert!(
            raw.contains(r#"<w:sym w:font="Wingdings" w:char="F0E0"/><w:t xml:space="preserve"> updated</w:t>"#),
            "symbol element must consume its decoded logical character: {raw}",
        );
        assert!(
            !raw.contains('\u{F0E0}'),
            "decoded symbol must not also serialize as literal text: {raw}",
        );

        // Replacing the decoded character removes the stale symbol element;
        // preserving it unconditionally would make the user's deletion appear
        // to fail after save/reload.
        word_doc.paragraph_mut(0).expect("paragraph").runs[0].text = "X updated".to_string();
        word_doc.sync_paragraph_text(0);
        let replaced = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert!(!replaced.contains("<w:sym "), "stale symbol: {replaced}");
        assert!(replaced.contains("<w:t>X updated</w:t>"));
    }

