    #[test]
    fn typed_break_elements_preserve_word_semantics_during_run_rebuild() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p><w:r><w:t>A</w:t><w:br w:type="column"/><w:t>B</w:t></w:r></w:p>
    <w:p><w:r><w:t>E</w:t><w:br w:type="futureBreak"/><w:t>F</w:t></w:r></w:p>
  </w:body>
</w:document>"#;
        let data = build_document_docx(document_xml);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        // A column break reads as its own control character, and saving
        // retains the original OOXML type.
        let paragraph = word_doc.paragraph_mut(0).expect("column paragraph");
        assert_eq!(paragraph.runs[0].text, "A\u{000E}B");
        paragraph.runs[0].text = "Column\u{000E}B".to_string();

        // Future/extension break types are intentionally absent from editable
        // text, but lossless editing must still preserve their raw marker.
        let paragraph = word_doc.paragraph_mut(1).expect("unknown paragraph");
        assert_eq!(paragraph.runs[0].text, "EF");
        paragraph.runs[0].text = "XF".to_string();

        for paragraph_index in 0..2 {
            word_doc.sync_paragraph_text(paragraph_index);
        }

        let raw = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert!(
            raw.contains(r#"<w:t>Column</w:t><w:br w:type="column"/><w:t>B</w:t>"#),
            "column break must not become a page break after editing: {raw}",
        );
        assert!(
            !raw.contains(r#"<w:t>Column</w:t><w:br w:type="page"/>"#),
            "column break was rewritten as a page break: {raw}",
        );
        assert!(
            raw.contains(r#"<w:t>X</w:t><w:br w:type="futureBreak"/><w:t>F</w:t>"#),
            "unknown break types must survive lossless editing: {raw}",
        );
    }

    #[test]
    fn text_wrapping_break_clear_attribute_survives_run_rebuild() {
        let document_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    <w:p>
      <w:r><w:t>Above</w:t><w:br w:type="textWrapping" w:clear="all"/><w:t>Below</w:t></w:r>
    </w:p>
  </w:body>
</w:document>"#;
        let data = build_document_docx(document_xml);
        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &Options::default())).expect("load docx");

        let paragraph = word_doc.paragraph_mut(0).expect("paragraph");
        assert_eq!(
            paragraph.runs.len(),
            1,
            "an attributed break must stay mapped to its original raw run",
        );
        assert_eq!(paragraph.runs[0].text, "Above\nBelow");
        paragraph.runs[0].text = "Changed\nBelow".to_string();
        word_doc.sync_paragraph_text(0);

        let raw = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert!(
            raw.contains(
                r#"<w:t>Changed</w:t><w:br w:type="textWrapping" w:clear="all"/><w:t>Below</w:t>"#,
            ),
            "w:clear controls Word's floating-object avoidance and must survive editing: {raw}",
        );

        // Removing the logical line break must remove its attributed OOXML
        // element as well; otherwise the deleted break returns after reload.
        word_doc.paragraph_mut(0).expect("paragraph").runs[0].text = "ChangedBelow".to_string();
        word_doc.sync_paragraph_text(0);
        let removed = word_doc
            .raw_document
            .as_ref()
            .expect("raw xml")
            .to_string()
            .expect("serialize xml");
        assert!(
            !removed.contains("<w:br "),
            "stale wrapping break: {removed}"
        );
        assert!(removed.contains("<w:t>ChangedBelow</w:t>"));
    }

