    #[test]
    fn split_paragraph_distributes_bookmark_and_comment_anchors_without_duplicates() {
        let data = build_document_docx(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:p>
    <w:bookmarkStart w:id="1" w:name="splitBookmark"/>
    <w:commentRangeStart w:id="7"/>
    <w:r><w:t>AB</w:t></w:r>
    <w:r><w:t>CD</w:t></w:r>
    <w:commentRangeEnd w:id="7"/>
    <w:bookmarkEnd w:id="1"/>
  </w:p></w:body>
</w:document>"#,
        );
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load anchored paragraph");

        assert!(word_doc.split_paragraph_at(0, 2));
        let xml = exported_document_xml(&word_doc);
        for marker in [
            "<w:bookmarkStart",
            "<w:bookmarkEnd",
            "<w:commentRangeStart",
            "<w:commentRangeEnd",
        ] {
            assert_eq!(xml.matches(marker).count(), 1, "duplicate {marker}: {xml}");
        }
        let split = xml.find("</w:p><w:p").expect("two paragraphs");
        assert!(xml[..split].contains("<w:bookmarkStart"), "{xml}");
        assert!(xml[..split].contains("<w:commentRangeStart"), "{xml}");
        assert!(xml[split..].contains("<w:bookmarkEnd"), "{xml}");
        assert!(xml[split..].contains("<w:commentRangeEnd"), "{xml}");
    }

    /// The new paragraph keeps the markers between the runs a split moves
    /// into it where they were, as Word does.
    ///
    /// It rebuilt those runs, which put every run before the first marker:
    /// a bookmark around "CD" collapsed after "EF", and a comment's range
    /// ended after its own reference mark. A collapsed bookmark at the split
    /// (Word's `_GoBack`) ended in the first paragraph and started in the
    /// second.
    #[test]
    fn split_paragraph_keeps_markers_between_the_runs_it_moves() {
        let paragraph_xml = |runs: &str| {
            build_document_docx(&format!(
                r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p>{runs}</w:p></w:body></w:document>"#
            ))
        };
        for (source, offset, expected) in [
            (
                r#"<w:r><w:t>AB</w:t></w:r><w:bookmarkStart w:id="1" w:name="b"/><w:r><w:t>CD</w:t></w:r><w:bookmarkEnd w:id="1"/><w:r><w:t>EF</w:t></w:r>"#,
                1,
                r#"<w:p><w:r><w:t>A</w:t></w:r></w:p><w:p><w:r><w:t>B</w:t></w:r><w:bookmarkStart w:id="1" w:name="b"/><w:r><w:t>CD</w:t></w:r><w:bookmarkEnd w:id="1"/><w:r><w:t>EF</w:t></w:r></w:p>"#,
            ),
            (
                r#"<w:commentRangeStart w:id="1"/><w:r><w:t>AB</w:t></w:r><w:commentRangeEnd w:id="1"/><w:r><w:commentReference w:id="1"/></w:r>"#,
                0,
                r#"<w:p/><w:p><w:commentRangeStart w:id="1"/><w:r><w:t>AB</w:t></w:r><w:commentRangeEnd w:id="1"/><w:r><w:commentReference w:id="1"/></w:r></w:p>"#,
            ),
            (
                r#"<w:bookmarkStart w:id="0" w:name="_GoBack"/><w:bookmarkEnd w:id="0"/><w:r><w:t>AB</w:t></w:r>"#,
                0,
                r#"<w:p/><w:p><w:bookmarkStart w:id="0" w:name="_GoBack"/><w:bookmarkEnd w:id="0"/><w:r><w:t>AB</w:t></w:r></w:p>"#,
            ),
            (
                r#"<w:r><w:t>AB</w:t></w:r><w:ins w:id="5" w:author="a"><w:r><w:t>CD</w:t></w:r></w:ins><w:bookmarkStart w:id="1" w:name="b"/><w:r><w:t>EF</w:t></w:r><w:bookmarkEnd w:id="1"/>"#,
                1,
                r#"<w:p><w:r><w:t>A</w:t></w:r></w:p><w:p><w:r><w:t>B</w:t></w:r><w:ins w:id="5" w:author="a"><w:r><w:t>CD</w:t></w:r></w:ins><w:bookmarkStart w:id="1" w:name="b"/><w:r><w:t>EF</w:t></w:r><w:bookmarkEnd w:id="1"/></w:p>"#,
            ),
        ] {
            let mut word_doc = executor::block_on(WordDocument::load(
                &paragraph_xml(source),
                &Options::default(),
            ))
            .expect("load paragraph");
            assert!(word_doc.split_paragraph_at(0, offset), "{source}");
            let xml = exported_document_xml(&word_doc);
            let body = &xml[xml.find("<w:body>").expect("body") + "<w:body>".len()
                ..xml.find("</w:body>").expect("body end")];
            assert_eq!(body, expected, "splitting {source} at {offset}");
        }
    }

    /// A field the split moves into the new paragraph stays a field, with
    /// the `w:fldChar` and `w:instrText` runs it was written with.
    #[test]
    fn split_paragraph_keeps_a_field_it_moves() {
        let data = build_document_docx(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>AB</w:t></w:r><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>1</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r><w:r><w:t>CD</w:t></w:r></w:p></w:body></w:document>"#,
        );
        let mut word_doc = executor::block_on(WordDocument::load(&data, &Options::default()))
            .expect("load field paragraph");
        assert!(word_doc.split_paragraph_at(0, 1));
        let xml = exported_document_xml(&word_doc);
        let tail = &xml[xml.find("</w:p><w:p").expect("two paragraphs")..];
        assert!(
            tail.contains(
                r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>1</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>"#
            ),
            "{xml}"
        );
    }

    #[test]
    fn split_paragraph_rebases_comment_ranges_and_markers() {
        let mut paragraph = make_paragraph("ABCD");
        paragraph.comment_ranges = vec![crate::document::CommentRange {
            id: "7".to_string(),
            start: 1,
            end: 3,
        }];
        paragraph.comment_markers = vec![crate::document::CommentMarker {
            id: "7".to_string(),
            position: 3,
        }];
        let mut word_doc = WordDocument::from_document(Document {
            body: Some(Body {
                elements: vec![BodyElement::from_paragraph(paragraph)],
            }),
            ..Document::default()
        });

        assert!(word_doc.split_paragraph_at(0, 2));
        let head = word_doc.paragraph(0).expect("head");
        let tail = word_doc.paragraph(1).expect("tail");
        assert_eq!(
            (head.comment_ranges[0].start, head.comment_ranges[0].end),
            (1, 2)
        );
        assert_eq!(
            (tail.comment_ranges[0].start, tail.comment_ranges[0].end),
            (0, 1)
        );
        assert!(head.comment_markers.is_empty());
        assert_eq!(tail.comment_markers[0].position, 1);
    }

