        let mut word_doc =
            executor::block_on(WordDocument::load(&data, &options)).expect("load docx");
        word_doc
            .insert_shape_at(
                0,
                4,
                ShapeInsertSpec {
                    shape: TextBoxShape::Rectangle,
                    width_px: 160.0,
                    height_px: 80.0,
                    fill_color: Some("4472C4".to_string()),
                    border_color: Some("000000".to_string()),
                    border_width_px: 1.0,
                    text: "Transparent".to_string(),
                    text_color: None,
                    text_font_size_pt: None,
                    text_bold: None,
                    text_italic: None,
                    text_alignment: None,
                },
            )
            .expect("insert shape");
        word_doc
            .paragraph_mut(0)
            .expect("host paragraph")
            .runs
            .iter_mut()
            .find_map(|run| run.text_box.as_mut())
