    #[test]
    fn line_variants_export_stroke_only_and_reopen_with_arrow_identity() {
        for shape in [
            TextBoxShape::Line,
            TextBoxShape::LineArrow,
            TextBoxShape::LineArrowDouble,
            TextBoxShape::LineBent,
            TextBoxShape::LineCurved,
        ] {
            let data = build_document_docx(
                r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:p><w:r><w:t>Host</w:t></w:r></w:p></w:body>
</w:document>"#,
            );
            let options = Options::default();
            let mut word_doc =
                executor::block_on(WordDocument::load(&data, &options)).expect("load line source");
            word_doc
                .insert_shape_at(
                    0,
                    2,
                    ShapeInsertSpec {
                        shape,
                        width_px: 240.0,
                        height_px: 80.0,
                        fill_color: Some("4472C4".to_string()),
                        border_color: Some("000000".to_string()),
                        border_width_px: 2.0,
                        text: "must be removed".to_string(),
                        text_color: None,
                        text_font_size_pt: None,
                        text_bold: None,
                        text_italic: None,
                        text_alignment: None,
                    },
                )
                .expect("insert line");

            let exported = word_doc.export_docx().expect("export line");
            let xml = exported_document_xml(&word_doc);
            assert!(xml.contains(&format!(r#"<a:prstGeom prst="{}">"#, shape.preset_name())));
            assert!(xml.contains("<a:noFill/>"));
            assert!(!xml.contains("<wps:txbx>"));
            assert!(xml.contains("<wps:cNvCnPr><a:cxnSpLocks/></wps:cNvCnPr>"));
            assert!(!xml.contains("<wps:cNvSpPr"));
            assert_eq!(
                xml.contains("<a:headEnd type=\"triangle\"/>"),
                shape.has_head_arrow()
            );
            assert_eq!(
                xml.contains("<a:tailEnd type=\"triangle\"/>"),
                shape.has_tail_arrow()
            );

            let reopened =
                executor::block_on(WordDocument::load(&exported, &options)).expect("reopen line");
            let line = reopened
                .paragraph(0)
                .expect("host")
                .runs
                .iter()
                .find_map(|run| run.text_box.as_ref())
                .expect("line model");
            assert_eq!(line.shape, shape);
            assert!(line.text.is_empty());
            assert!(line.blocks.is_empty());
            assert!(line.fill_color.is_none());
        }
    }

    #[test]
    fn connector_writer_preserves_authored_end_side_and_type() {
        fn descendants_named<'a>(
            element: &'a XmlElement,
            name: &str,
            found: &mut Vec<&'a XmlElement>,
        ) {
            if element.name == name {
                found.push(element);
            }
            for child in &element.children {
                if let XmlNode::Element(child) = child {
                    descendants_named(child, name, found);
                }
            }
        }

        let mut xml_doc = DocxXmlDocument::parse("<w:document/>").expect("minimal XML tree");
        let text_box = RunTextBox {
            width_px: Some(240.0),
            height_px: Some(80.0),
            shape: TextBoxShape::LineArrow,
            border: TextBoxBorder {
                width_px: Some(2.0),
                head_end: Some(TextBoxLineEnd::Stealth),
                tail_end: None,
                ..TextBoxBorder::default()
            },
            ..RunTextBox::default()
        };
        let graphic = WordDocument::create_text_box_graphic_element(
            &mut xml_doc,
            &text_box,
            2_286_000,
            762_000,
        );
        let mut head_ends = Vec::new();
        let mut tail_ends = Vec::new();
        descendants_named(&graphic, "a:headEnd", &mut head_ends);
        descendants_named(&graphic, "a:tailEnd", &mut tail_ends);
        let mut connector_properties = Vec::new();
        descendants_named(&graphic, "wps:cNvCnPr", &mut connector_properties);

        assert_eq!(head_ends.len(), 1);
        assert_eq!(tail_ends.len(), 0, "head-only must not gain a tail marker");
        assert_eq!(connector_properties.len(), 1);
        assert!(connector_properties[0]
            .children
            .iter()
            .any(|child| matches!(child, XmlNode::Element(child) if child.name == "a:cxnSpLocks")));
        assert!(head_ends[0]
            .attributes
            .iter()
            .any(|attribute| attribute.name == "type" && attribute.value == "stealth"));

        let curved = RunTextBox {
            width_px: Some(240.0),
            height_px: Some(80.0),
            shape: TextBoxShape::LineCurved,
            border: TextBoxBorder {
                width_px: Some(2.0),
                head_end: None,
                tail_end: Some(TextBoxLineEnd::Oval),
                ..TextBoxBorder::default()
            },
            ..RunTextBox::default()
        };
        let graphic = WordDocument::create_text_box_graphic_element(
            &mut xml_doc,
            &curved,
            2_286_000,
            762_000,
        );
        let mut head_ends = Vec::new();
        let mut tail_ends = Vec::new();
        descendants_named(&graphic, "a:headEnd", &mut head_ends);
        descendants_named(&graphic, "a:tailEnd", &mut tail_ends);
        assert_eq!(head_ends.len(), 0, "tail-only must not gain a head marker");
        assert_eq!(tail_ends.len(), 1);
        assert!(tail_ends[0]
            .attributes
            .iter()
            .any(|attribute| attribute.name == "type" && attribute.value == "oval"));
    }

    proptest! {
        #![proptest_config(ProptestConfig {
            cases: 64,
            max_shrink_iters: 3000,
            .. ProptestConfig::default()
        })]

        #[test]
        fn generated_shape_insertions_export_and_reopen_at_every_utf8_run_boundary(
            shape_index in 0usize..TextBoxShape::EXACT_PRESETS.len(),
            boundary_seed in any::<usize>(),
            width in 12.0f64..700.0,
            height in 12.0f64..500.0,
            border_width in 0.0f64..12.0,
            shape_text in "[a-zA-Z0-9ぁ-んァ-ヶ一-龠]{0,32}",
        ) {
            let source = "甲A🙂乙B";
            let boundaries = source
                .char_indices()
                .map(|(offset, _)| offset)
                .chain(std::iter::once(source.len()))
                .collect::<Vec<_>>();
            let offset = boundaries[boundary_seed % boundaries.len()];
            let shape = TextBoxShape::EXACT_PRESETS[shape_index];
            let preset = shape.preset_name();
            let is_line = shape.is_line();
            let data = build_document_docx(
                r#"<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:p><w:r><w:t>甲A</w:t></w:r><w:r><w:t>🙂乙</w:t></w:r><w:r><w:t>B</w:t></w:r></w:p></w:body>
</w:document>"#,
            );
            let options = Options::default();
            let mut word_doc = executor::block_on(WordDocument::load(&data, &options))
                .expect("load generated source");
            word_doc
                .insert_shape_at(
                    0,
                    offset,
                    ShapeInsertSpec {
                        shape,
                        width_px: width,
                        height_px: height,
                        fill_color: Some("#4472c4".to_string()),
                        border_color: Some("2f5496".to_string()),
                        border_width_px: border_width,
                        text: shape_text.clone(),
                        text_color: None,
                        text_font_size_pt: None,
                        text_bold: None,
                        text_italic: None,
                        text_alignment: None,
                    },
                )
                .expect("insert generated shape");

            let exported = word_doc.export_docx().expect("export shape");
            let xml = exported_document_xml(&word_doc);
            let expected_geometry = format!(r#"<a:prstGeom prst="{}">"#, preset);
            prop_assert!(xml.contains(&expected_geometry));
            if is_line {
                prop_assert!(xml.contains("<a:noFill/>"));
                prop_assert!(!xml.contains("<wps:txbx>"));
                prop_assert_eq!(xml.contains("<a:headEnd type=\"triangle\"/>"), shape.has_head_arrow());
                prop_assert_eq!(xml.contains("<a:tailEnd type=\"triangle\"/>"), shape.has_tail_arrow());
            } else {
                prop_assert!(xml.contains(r#"<a:srgbClr val="4472C4"/>"#));
            }
            prop_assert!(xml.contains(r#"<a:srgbClr val="2F5496"/>"#) || border_width == 0.0);

            let reopened = executor::block_on(WordDocument::load(&exported, &options))
                .expect("reopen generated shape");
            let host = reopened.paragraph(0).expect("reopened host paragraph");
            prop_assert_eq!(
                host.runs.iter().map(|run| run.text.as_str()).collect::<String>(),
                source
            );
            let reopened_shape = host
                .runs
                .iter()
                .find_map(|run| run.text_box.as_ref())
                .expect("reopened shape model");
            prop_assert_eq!(reopened_shape.shape, shape);
            prop_assert_eq!(
                reopened_shape.text.as_str(),
                if is_line { "" } else { shape_text.as_str() }
            );
            prop_assert_eq!(
                reopened_shape.fill_color.as_deref(),
                if is_line { None } else { Some("#4472C4") }
            );
            prop_assert_eq!(reopened_shape.blocks.is_empty(), is_line);
            prop_assert!((reopened_shape.width_px.unwrap_or_default() - width).abs() < 0.01);
            prop_assert!((reopened_shape.height_px.unwrap_or_default() - height).abs() < 0.01);
        }
    }

