    #[test]
    fn authored_note_numbering_is_section_scoped_and_roundtrips() {
        let bytes = std::fs::read(fixture_path("header-footer-sections.docx")).unwrap();
        let mut doc = executor::block_on(WordDocument::load(&bytes, &Options::default())).unwrap();
        let before = section_properties_xml(&exported_document_xml(&doc));
        let settings_before = doc.settings_xml_content();
        assert!(doc
            .set_note_numbering(true, "upperRoman", 8, "eachSect", Some(0))
            .unwrap());
        assert!(doc
            .set_note_numbering(false, "lowerLetter", 3, "continuous", Some(1))
            .unwrap());
        assert!(!doc
            .set_note_numbering(true, "upperRoman", 8, "eachSect", Some(0))
            .unwrap());
        let sections = section_properties_xml(&exported_document_xml(&doc));
        assert!(sections[0].contains("<w:footnotePr>"));
        assert!(sections[0].contains("w:val=\"upperRoman\""));
        assert!(!sections[0].contains("<w:endnotePr>"));
        assert!(sections[1].contains("<w:endnotePr>"));
        assert!(!sections[1].contains("<w:footnotePr>"));
        for (old, new) in before.iter().zip(&sections) {
            let mut stripped = new.clone();
            for name in ["footnotePr", "endnotePr"] {
                if let Some(start) = stripped.find(&format!("<w:{name}>")) {
                    let end_tag = format!("</w:{name}>");
                    let end = start + stripped[start..].find(&end_tag).unwrap() + end_tag.len();
                    stripped.replace_range(start..end, "");
                }
            }
            assert_eq!(old, &stripped, "other section properties are preserved");
        }
        assert_eq!(doc.settings_xml_content(), settings_before);
        let saved = doc.export_docx().unwrap();
        let reopened = executor::block_on(WordDocument::load(&saved, &Options::default())).unwrap();
        for candidate in [&doc, &reopened] {
            let first = candidate.note_numbering(true, Some(0)).unwrap();
            assert_eq!(first.number_format.as_deref(), Some("upperroman"));
            assert_eq!(first.number_start, Some(8));
            assert_eq!(first.number_restart.as_deref(), Some("eachsect"));
            let last = candidate.note_numbering(false, Some(1)).unwrap();
            assert_eq!(last.number_format.as_deref(), Some("lowerletter"));
            assert_eq!(last.number_start, Some(3));
            assert_eq!(last.number_restart.as_deref(), Some("continuous"));
        }
    }

    #[test]
    fn note_numbering_prepares_deferred_xml_only_for_a_valid_change() {
        let bytes = std::fs::read(fixture_path("hello.docx")).unwrap();
        for is_footnote in [true, false] {
            let mut doc = executor::block_on(WordDocument::load_for_initial_render(
                &bytes,
                &Options::default(),
            ))
            .unwrap();
            assert!(doc.raw_document.is_none());
            assert!(!doc
                .set_note_numbering(is_footnote, "decimal", 1, "continuous", Some(0))
                .unwrap());
            for (format, start, restart, section) in [
                ("invalid", 8, "eachSect", Some(0)),
                ("upperRoman", 0, "eachSect", Some(0)),
                ("upperRoman", 8, "invalid", Some(0)),
                ("upperRoman", 8, "eachSect", Some(999)),
            ] {
                assert!(doc
                    .set_note_numbering(is_footnote, format, start, restart, section)
                    .is_err());
            }
            assert!(doc.raw_document.is_none());
            assert!(doc
                .set_note_numbering(is_footnote, "upperRoman", 8, "eachSect", Some(0))
                .unwrap());
            let reopened = executor::block_on(WordDocument::load(
                &doc.export_docx().unwrap(),
                &Options::default(),
            ))
            .unwrap();
            for candidate in [&doc, &reopened] {
                let numbering = candidate.note_numbering(is_footnote, Some(0)).unwrap();
                assert_eq!(numbering.number_format.as_deref(), Some("upperroman"));
                assert_eq!(numbering.number_start, Some(8));
                assert_eq!(numbering.number_restart.as_deref(), Some("eachsect"));
                assert_eq!(
                    candidate.note_numbering(!is_footnote, Some(0)).unwrap(),
                    crate::document::NoteNumbering {
                        number_format: Some("decimal".into()),
                        number_start: Some(1),
                        number_restart: Some("continuous".into()),
                    }
                );
            }
        }
    }

