    #[test]
    fn authored_endnote_position_is_isolated_preserves_xml_and_reopens() {
        use crate::document::EndnotePosition;
        let xml = r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:x="urn:test"><w:body><w:p><w:pPr><w:sectPr><w:endnotePr x:keep="outer"><w:pos w:val="docEnd" x:keep="position"/><w:numFmt w:val="upperRoman"/><x:extra/></w:endnotePr></w:sectPr></w:pPr><w:r><w:t>First</w:t></w:r></w:p><w:p><w:r><w:t>Second</w:t></w:r></w:p><w:sectPr><w:endnotePr><w:pos w:val="docEnd"/></w:endnotePr></w:sectPr></w:body></w:document>"#;
        let bytes = build_document_docx(xml);
        let mut doc = executor::block_on(WordDocument::load(&bytes, &Options::default())).unwrap();
        let settings_before = doc.settings_xml_content();
        assert!(doc
            .set_endnote_position(EndnotePosition::SectionEnd, Some(0))
            .unwrap());
        assert!(!doc
            .set_endnote_position(EndnotePosition::SectionEnd, Some(0))
            .unwrap());
        let after = doc.export_docx().unwrap();
        assert!(doc
            .set_endnote_position(EndnotePosition::SectionEnd, Some(999))
            .is_err());
        assert_eq!(doc.export_docx().unwrap(), after);
        assert_eq!(doc.settings_xml_content(), settings_before);
        let reopened = executor::block_on(WordDocument::load(&after, &Options::default())).unwrap();
        for candidate in [&doc, &reopened] {
            assert_eq!(
                candidate.endnote_position(Some(0)).unwrap(),
                EndnotePosition::SectionEnd
            );
            assert_eq!(
                candidate.endnote_position(Some(1)).unwrap(),
                EndnotePosition::DocumentEnd
            );
            let xml = exported_document_xml(candidate);
            for preserved in [
                r#"x:keep="outer""#,
                r#"<w:pos w:val="sectEnd" x:keep="position"/>"#,
                r#"<w:numFmt w:val="upperRoman"/>"#,
                "<x:extra/>",
            ] {
                assert!(xml.contains(preserved), "lost {preserved}: {xml}");
            }
        }
        assert!(doc
            .set_endnote_position(EndnotePosition::SectionEnd, Some(1))
            .unwrap());
        let reopened = executor::block_on(WordDocument::load(
            &doc.export_docx().unwrap(),
            &Options::default(),
        ))
        .unwrap();
        assert_eq!(
            reopened.endnote_position(Some(1)).unwrap(),
            EndnotePosition::SectionEnd
        );
        assert_eq!(
            reopened.endnote_position(None).unwrap(),
            EndnotePosition::SectionEnd
        );
    }

    #[test]
    fn authored_note_numbering_preserves_existing_placement_and_extensions() {
        let xml = r#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:x="urn:test"><w:body><w:p><w:r><w:t>Notes</w:t></w:r></w:p><w:sectPr><w:footnotePr x:keep="outer"><w:pos w:val="beneathText"/><w:numFmt w:val="decimal" x:keep="format"/><x:extra x:keep="child"/></w:footnotePr><w:endnotePr><w:pos w:val="sectEnd"/></w:endnotePr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body></w:document>"#;
        let bytes = build_document_docx(xml);
        let mut doc = executor::block_on(WordDocument::load(&bytes, &Options::default())).unwrap();
        doc.set_note_numbering(true, "upperRoman", 8, "eachPage", Some(0))
            .unwrap();
        let saved = doc.export_docx().unwrap();
        let reopened = executor::block_on(WordDocument::load(&saved, &Options::default())).unwrap();
        for candidate in [&doc, &reopened] {
            let xml = exported_document_xml(candidate);
            for preserved in [
                r#"<w:footnotePr x:keep="outer">"#,
                r#"<w:pos w:val="beneathText"/>"#,
                r#"<w:numFmt w:val="upperRoman" x:keep="format"/>"#,
                r#"<x:extra x:keep="child"/>"#,
                r#"<w:endnotePr><w:pos w:val="sectEnd"/></w:endnotePr>"#,
                r#"<w:pgSz w:w="12240" w:h="15840"/>"#,
            ] {
                assert!(xml.contains(preserved), "lost {preserved}: {xml}");
            }
            assert!(xml.find("w:numStart").unwrap() < xml.find("w:numRestart").unwrap());
            assert!(xml.find("w:numRestart").unwrap() < xml.find("x:extra").unwrap());
            assert_eq!(
                candidate
                    .note_numbering(true, Some(0))
                    .unwrap()
                    .number_restart
                    .as_deref(),
                Some("eachpage")
            );
        }
    }

