    #[test]
    fn yokohama_page3_only_paren_run_inherits_font_size() {
        let data = std::fs::read(fixture_path("yokohama_page3_only.docx"))
            .expect("read yokohama_page3_only fixture");
        let options = Options::default();
        let doc = executor::block_on(WordDocument::load(&data, &options)).expect("load docx");
        let document = doc.document.as_ref().expect("document");
        let body = document.body.as_ref().expect("body");
        let paragraph = body
            .elements
            .iter()
            .filter_map(|element| element.as_paragraph())
            .find(|paragraph| {
                let text: String = paragraph.runs.iter().map(|run| run.text.as_str()).collect();
                text.starts_with(
                    "(5)　分割納付又は分割納入の方法により納付し、又は納入するかどうか",
                )
            })
            .expect("find (5) paragraph");

        let open_paren_run = paragraph
            .runs
            .iter()
            .find(|run| run.text == "(")
            .expect("find open paren run");
        let following_run = paragraph
            .runs
            .iter()
            .find(|run| {
                run.text
                    .starts_with("分割納付又は分割納入の方法により納付し、又は納入する場合")
            })
            .expect("find following run");

        let open_size = open_paren_run
            .properties
            .as_ref()
            .and_then(|props| props.font_size)
            .expect("open paren run font size");
        let following_size = following_run
            .properties
            .as_ref()
            .and_then(|props| props.font_size)
            .expect("following run font size");

        assert!(
            (open_size - 10.5).abs() < f32::EPSILON,
            "open paren run should inherit 10.5pt, got {open_size}"
        );
        assert!(
            (following_size - 10.5).abs() < f32::EPSILON,
            "following run should inherit 10.5pt, got {following_size}"
        );
    }

