    #[test]
    fn yokohama_page6_page_shift_starts_after_run_font_defaults() {
        let data = std::fs::read(fixture_path("yokohama_page6.docx"))
            .expect("read yokohama_page6 fixture");
        let package = executor::block_on(OpenXmlPackage::load(&data)).expect("load package");
        let doc_target = package
            .relationships
            .iter()
            .find(|rel| rel.r#type == RelationshipTypes::OfficeDocument.as_str())
            .map(|rel| rel.target.clone())
            .expect("document relationship");
        let document_xml = String::from_utf8_lossy(package.get(&doc_target).expect("document xml"));
        let mut raw_document = DocumentParser::new()
            .parse_document_xml(&document_xml)
            .expect("parse raw document");

        let rels_path = format!(
            "{}/_rels/{}.rels",
            doc_target
                .rsplit_once('/')
                .map(|(dir, _)| dir)
                .unwrap_or(""),
            doc_target.rsplit('/').next().expect("document file name")
        )
        .trim_start_matches('/')
        .to_string();
        let doc_relationships = package
            .get(&rels_path)
            .map(|data| {
                package
                    .parse_relationships(data)
                    .expect("parse document rels")
            })
            .unwrap_or_default();

        let mut styles = StylesPart::new();
        for rel in &doc_relationships {
            if rel.r#type == RelationshipTypes::Styles.as_str()
                || rel.r#type == RelationshipTypes::StylesWithEffects.as_str()
            {
                let target_path = WordDocument::resolve_target_path(&doc_target, &rel.target);
                let xml = String::from_utf8_lossy(package.get(&target_path).expect("styles xml"));
                styles.parse(&xml).expect("parse styles");
            }
        }

        let context = bundled_noto_context_with_yokohama_aliases();
        let heading_page = |document: &Document| {
            layout_document_lines(document, &context)
                .expect("layout document")
                .get_lines()
                .find(|line| {
                    line.text.starts_with(
                        "3　法第15条の6の2第2項に規定する条例で定める事項は、次に掲げる事項とする",
                    )
                })
                .map(|line| line.page)
                .expect("heading line page")
        };

        let raw_page = heading_page(&raw_document);

        WordDocument::apply_style_paragraph_defaults_to_document(&mut raw_document, &styles);
        let style_page = heading_page(&raw_document);

        WordDocument::apply_run_font_defaults_to_document(&mut raw_document, &styles);
        let run_font_page = heading_page(&raw_document);
        let mut cleared_inherited_sizes = raw_document.clone();
        if let Some(body) = cleared_inherited_sizes.body.as_mut() {
            for paragraph in body
                .elements
                .iter_mut()
                .filter_map(|element| element.as_paragraph_mut())
            {
                for run in &mut paragraph.runs {
                    if let Some(props) = run.properties.as_mut() {
                        props.font_size = None;
                    }
                }
            }
        }
        let cleared_size_page = heading_page(&cleared_inherited_sizes);
        let mut cleared_ascii_sizes = raw_document.clone();
        if let Some(body) = cleared_ascii_sizes.body.as_mut() {
            for paragraph in body
                .elements
                .iter_mut()
                .filter_map(|element| element.as_paragraph_mut())
            {
                for run in &mut paragraph.runs {
                    if run.text.is_ascii() {
                        if let Some(props) = run.properties.as_mut() {
                            props.font_size = None;
                        }
                    }
                }
            }
        }
        let cleared_ascii_size_page = heading_page(&cleared_ascii_sizes);

        assert_eq!(
            raw_page, 5,
            "raw parser layout should keep the heading on page 5"
        );
        assert_eq!(
            style_page, 5,
            "paragraph style defaults alone should keep the heading on page 5"
        );
        assert_eq!(
            run_font_page, 4,
            "run-font defaults shift the heading onto page 4 in the current runtime pipeline"
        );
        assert_eq!(
            cleared_size_page, 5,
            "clearing inherited run font sizes should move the heading back to page 5"
        );
        assert_eq!(
            cleared_ascii_size_page, 4,
            "clearing inherited font sizes only on ASCII runs is not enough; the page shift also depends on inherited sizes on Japanese runs"
        );
    }

    #[test]
